window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-pediatria-ped-1"]={"block":"medcurso:medcurso-pediatria-ped-1","label":"Medcurso · PED 1","count":443,"questions":[{"id":"medcurso-pediatria-ped-1-343775","number":"343775","sourceNumber":"343775","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A hipoglicemia neonatal ocorre com maior frequência nos pacientes com baixa reserva\nenergética, como nos recém-nascidos prematuros e naqueles com restrição do crescimento\nintrauterino. Cornblath em 2000 recomendou alguns limiares operacionais para o tratamento da\nhipoglicemia em neonatos. A respeito desses limiares operacionais, marque a resposta correta\nabaixo:","options":{"A":"Recém-nascido a termo saudável com menos de 24h de vida: 30 a 35mg/dL na primeira\nmedição.","B":"Recém-nascido com sinais ou sintomas clínicos anormais: 30 a 35mg/dL.","C":"Recém-nascido a termo saudável após 24h de vida: 60mg/dL.","D":"Recém-nascido com sinais ou sintomas clínicos anormais: 50mg/dL."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-343776","number":"343776","sourceNumber":"343776","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O teste do reflexo vermelho é o exame de rastreamento para anormalidades oculares,\ndesde a córnea até o seguimento posterior.\nA respeito desse teste de triagem, qual das afirmativas\nabaixo é a correta?","options":{"A":"A rotina de realização do teste do reflexo vermelho deve ocorrer da seguinte forma: antes da alta\nda maternidade, com 2, 6, 9 e 12 meses de vida e após 1 ano de idade com a frequência de duas\nvezes ao ano.","B":"O teste é considerado normal quando um dos olhos apresentam um reflexo vermelho brilhante.","C":"A rotina de realização do teste do reflexo vermelho deve ocorrer da seguinte forma: antes da alta\nda maternidade, na primeira consulta de puericultura, com 2, 6, 9 e 12 meses de vida e após 1 ano\nde idade com a frequência de duas vezes ao ano.","D":"A rotina de realização do teste do reflexo vermelho deve ocorrer da seguinte forma: antes da alta\nda maternidade, na primeira consulta de puericultura, mensalmente até os 12 meses de vida e após\n1 ano de idade com a frequência de duas vezes ao ano."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-343789","number":"343789","sourceNumber":"343789","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto fisiológico, nascido com idade gestacional de 36 semanas e 5\ndias é encaminhado a Unidade de Terapia Intensiva Neonatal com hipótese diagnóstica de infecção\ncongênita devido história materna suspeita. Ao realizar ultrassonografia transfontanelar, o\nresultado\ndemonstrou a presença de calcificações cerebrais periventriculares. Qual o provável diagnóstico?","options":{"A":"Toxoplasmose congênita.","B":"Citomegalovírose congênita.","C":"Sífilis congênita.","D":"Rubéola congênita."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-345492","number":"345492","sourceNumber":"345492","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido, 36 semanas e 6 dias, apgar 8/9, parto normal, nascido de mãe\nG1P1A0 que não realizou consultas de\npré-natal e apresentou teste rápido para HIV negativo e\nteste rápido para sífilis positivo no momento do parto. Mãe nega quaisquer tratamentos prévios.\nAssinale a alternativa que contenha a melhor conduta para o recém-nascido nesse caso:","options":{"A":"Como a mãe não foi tratada para sífilis na gestação, o recém-nascido não poderá ser tratado\ncom Penicilina Benzatina intramuscular,\nindependente do resultado dos exames.","B":"Aguardar o resultado do VDRL, no soro da mãe para decidir sobre a conduta do recém-nascido,\ne se o VDRL, no soro da mãe for não\nreagente, é dispensada qualquer conduta especial ao\n\nrecém-nascido.","C":"Nessa situação, a punção lombar do recém-nascido com estudo citobioquímico do líquor está\nindicada apenas se o VDRL no soro do mesmo for reagente.","D":"Se o recém-nascido apresentar VDRL no soro não reagente, os demais exames necessários\nnormais e ausência de sintomas, poderá\nreceber uma dose de Penicilina Benzatina intramuscular e\ndeverá fazer seguimento ambulatorial obrigatória."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-283289","number":"283289","sourceNumber":"283289","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A doença da membrana hialina é um distúrbio respiratório frequente em\nrecém-nascidos, marque a alternativa CORRETA:","options":{"A":"O quadro radiológico típico é de áreas de opacidades grosseiras e irregularidades difusas,\npodendo ser encontrado pneumotórax e pneumomediastino.","B":"Afeta recém-nascidos prematuros, sendo sua incidência diretamente proporcional a idade\ngestacional.","C":"A causa principal é a deficiência de surfactante, uma mistura alveolar fosfolipídica que reduz a\ntensão superficial dos alvéolos, com essa estabilidade comprometida, há formação de áreas difusas\nde atelectasias.","D":"No quadro clínico clássico observa-se gemidos, batimentos de asa de nariz, retrações inter e\nsubcostais, que melhoram com 48 horas de vida."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-283306","number":"283306","sourceNumber":"283306","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"As infecções perinatais afetam 0,5% a 2,5% de todos os nascimentos e constituem um\ngrande problema de saúde pública pela elevada morbimortalidade a elas associadas. Assinale a\nalternativa CORRETA considerando a toxoplasmose congênita:","options":{"A":"O risco de transmissão se aproxima de 100% quando a infecção materna ocorre no primeiro\ntrimestre da gestação.","B":"Cerca de 70% dos RN com infecção congênita são assintomáticos ao nascimento, sendo que a\nmetade das crianças acometidas têm manifestações graves nos primeiros dias de vida.","C":"A toxoplasmose congênita caracteriza-se por hidrocefalia, corioretinite, calcificações\nintracranianas e elevada proteinorraquia, bioquímico ao exame do líquor.","D":"O tratamento é longo, 1 ano, e consiste em sulfadiazina, pirimetamina, acido folínico e\nprednisona para todos os recém-nascidos."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-283308","number":"283308","sourceNumber":"283308","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual das abaixo NÃO é etiologia das convulsões no período neonatal?","options":{"A":"Encefalopatia hipóxico-isquêmica.","B":"Hipocalcemia.","C":"Aminoacidopatias.","D":"Enterocolite necrotizante."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-281148","number":"281148","sourceNumber":"281148","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido (RN) apresenta quadro de desconforto respiratório devido à doença de\nmembrana hialina, com baixa perfusão periférica. Com base nesse caso hipotético, assinale a\nalternativa que apresenta a conduta terapêutica correta.","options":{"A":"Fase expansiva com soro glicosado a 10% a 20 mL/Kg, seguida de infusão contínua de\ndobutamina caso não responda.","B":"Fase expansiva com soro fisiológico a 10 mL/Kg, seguida de infusão contínua de dopamina caso\nnão responda.","C":"Fase expansiva com soro glicosado a 5% a 29 mL/kg, seguida de adrenalina em infusão\ncontínua caso não responda.","D":"Fase expansiva com soro fisiológico a 20 mL/kg, seguida de adrenalina em infusão contínua\ncaso não responda.","E":"Fase expansiva com soro glicosado a 10% a 20 mL/Kg, seguida de infusão contínua com\ndopamina e dobutamina caso não responda."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-283334","number":"283334","sourceNumber":"283334","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A rubéola congênita NÃO está associada a complicação abaixo:","options":{"A":"Catarata.","B":"Defeitos septais cardíacos.","C":"Surdez neurossensorial.","D":"Pancreatite."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-251921","number":"251921","sourceNumber":"251921","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual das causas abaixo NÃO causa colestase em crianças?","options":{"A":"Deficiência de glicose-6-fosfato-desidrogenase (G6PD).","B":"Atresia de vias biliares.","C":"Hipotireoidismo.","D":"Hepatite auto-imune."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-251931","number":"251931","sourceNumber":"251931","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A hipoglicemia é um distúrbio metabólico frequente na neonatologia, marque a\nCORRETA, com relação a este distúrbio.","options":{"A":"São fatores de risco prematuridade, anemia falciforme e hipotireoidismo materno.","B":"Deve ser feito corticoide endovenoso, precocemente, na maioria dos casos.","C":"O flush de glicose a 10%(2ml/kg), endovenoso é o tratamento de escolha, nos sintomáticos.","D":"Nos grupos de risco não devemos realizar triagem por meio de fitas reagentes (dextro)."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-217707","number":"217707","sourceNumber":"217707","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"As doenças respiratórias constituem a causa mais frequente de admissão para\ncuidados intensivos, tanto do RN a termo quanto pré-termo. Com relação a essas doenças, a\nassertiva CORRETA é:","options":{"A":"A taquipneia transitória do RN geralmente ocorre em partos pós-termo e se caracteriza pelo\ninício precoce de taquipneia, por vezes, acompanhada de gemidos expiratórios ou retrações\nintercostais e ocasionalmente cianose.","B":"A síndrome da aspiração de mecônio é o resultado da obstrução das vias aéreas menores pela\naspiração de partículas finas de mecônio, caracterizada pelo desconforto respiratório nas primeiras\nhoras de vida com taquipneia, retrações, gemidos e cianose.","C":"A hipertensão pulmonar persistente neonatal ocorre em RN pré-termo e tem como alguns fatores\npredisponentes sepse de início precoce, hipoglicemia, policitemia, doença da membrana hialina e\npneumonia por aspiração de mecônio.","D":"A doença da membrana hialina tem sua incidência diretamente proporcional à idade gestacional\ne ao peso de nascimento, caracterizada pela\ndeficiência de surfactante, seja na diminuição da\nprodução ou por alteração na secreção."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-217655","number":"217655","sourceNumber":"217655","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A toxoplasmose congênita é uma infecção neonatal bastante frequente no Brasil,\nestima-se que nasçam de 1 a 10 crianças infectadas pelo toxoplasma gondii para cada 10.000\nnativivos em todo mundo. Marque a CORRETA com relação à toxoplasmose congênita:","options":{"A":"O teste de avidez para IgG, quando indica alta avidez (? 60%), reflete uma infecção ocorrida\napós 12 a 16ª semana de gestação, não sendo\nútil no início da gestação.","B":"A tríade clássica de hidrocefalia, calcificações cerebrais e coriorretinite é sugestiva e\nbastante\nfrequente.","C":"O tratamento é realizado com sulfadiazina, pirimetamina e ácido fólico, sendo associado à\nprednisolona na presença de coriorretinite e proteinorraquia >1.000 mg/dl no neonato.","D":"Quando não diagnosticada precocemente, a mesma pode resultar em coriorretinite ou\nmanifestações neurológicas (convulsões e obstrução\nliquórica) na infância tardia e adolescência."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-217675","number":"217675","sourceNumber":"217675","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A icterícia neonatal é uma condição comum, presente em até 85% dos recém-nascidos\na termo, sendo utilizadas as Zonas de Kramer\npara avaliação clínica, sendo necessário investigar\noutras causas de icterícia em recém-nascidos:","options":{"A":"Pós-termo, que apresentem icterícia zona II no segundo dia de vida.","B":"Que apresentam icterícia nas primeiras 24 horas de vida.","C":"Prematuros, que apresentem icterícia entre o 2º e 3º dias de vida, independente da zona de\nKramer.","D":"Com incompatibilidade Rh, independente da idade gestacional e o tempo de aparecimento da\nicterícia."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-217686","number":"217686","sourceNumber":"217686","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual padrão de herança é demonstrado no heredograma abaixo? O indivíduo II-4\napresenta qual risco de recorrência para a prole e qual variação genética?","options":{"A":"Autossômico dominante; 50%; penetrância incompleta.","B":"Autossômico recessivo; 25%; expressividade variável.","C":"Autossômico dominante; 50%; expressividade variável.","D":"Autossômico recessivo; 50%; penetrância incompleta."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-182653","number":"182653","sourceNumber":"182653","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido (RN) a termo de parto cesáreo, filho de mãe HIV+ e com VDRL de 1/16\nna ocasião do parto, apresenta boas condições\nde vitalidade e, após receber a primeira dose de\nzidovudina (AZT) é encaminhado ao alojamento conjunto. A conduta adequada em relação ao RN\nconsiste em:","options":{"A":"Solicitar o VDRL do RN, e se positivo, tratar com Penicilina G cristalina, além de prescrever AZT\n4mg/kg/dose, de 12/12hs.","B":"Manter o aleitamento materno desde que a carga viral da mãe seja indetectável.","C":"Iniciar profilaxia com sulfametoxazoltrimetropim contra pneumocistose a partir de 2 meses de\nvida, independente da contagem de linfócitos T-CD4+.","D":"Adiar a aplicação da BCG até que a infecção do RN seja descartada."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-183175","number":"183175","sourceNumber":"183175","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"São considerados fatores de risco diminuídos para SDR, EXCETO:","options":{"A":"Retardo crescimento intraútero.","B":"Mães que usaram corticosteróide.","C":"Masculinos (fator genético).","D":"RN com estresse intrauterino.","E":"Ruptura prolongada membranas amnióticas."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-183192","number":"183192","sourceNumber":"183192","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Foi internado, na unidade neonatal, um recém-nascido (RN) de 34 semanas de idade\ngestacional, nascido de parto cesária, índice de Apgar 8 e 9, respectivamente, no 1º e 5º minuto,\npeso de nascimento de 2100g. A mãe tinha infecção urinária e, com 6 horas de vida, o RN\nencontrava-se taquipneico, com tiragem intercostal e pouco gemente, O residente da unidade\nsuspeitou de sepse precoce, solicitou os exames de rastreamento e prescreveu antibiótico e tomou\noutras condutas, satisfazendo a resolução clínica do paciente. Assinale a alternativa correta do\nprovável esquema antimicrobiano que o residente deva ter prescrito para o paciente empiricamente.","options":{"A":"Ceftriaxona.","B":"Piperacilina/tazobactam e um aminoglicosídeo.","C":"Vancomicina e gentamicina.","D":"Ampicilina e um aminoglicosídeo.","E":"Uma cefalosporina de terceira geração e tobramicina ou gentamicina. Pediatria Página 8"},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-183208","number":"183208","sourceNumber":"183208","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido de 4 dias de vida, 27 semanas de idade gestacional e 1100 gramas\nde peso, está na UTI neonatal sob ventilação\nmecânica e apresenta a seguinte avaliação dos\ngases sanguíneos: pH = 7.21; paCO2 = 51 mmHg; paO2 = 85 mmHg, BE = -3 e BicNa = 17\nmmEq/L. Com esses dados, responder a alternativa correta.","options":{"A":"O paciente está em hipercapnia e, por isso, sua frequência respiratória deve ser diminuída.","B":"Esse paciente está em hiperóxia (paO2 = 85 mmHg).","C":"O único problema desse paciente é uma tendência à acidose metabólica.","D":"Esse paciente está com hiperóxia e hipercapnia.","E":"Os gases sanguíneos desse paciente estão dentro da normalidade levando-se em consideração\na idade gestacional de 27 semanas."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-182657","number":"182657","sourceNumber":"182657","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual dos achados encontrados no exame físico de um recém-nascido requer uma\ninvestigação mais ampla, pelo risco de associação com má formações?","options":{"A":"Eritema tóxico.","B":"Mancha mongólica.","C":"Milium sebáceo.","D":"Tufo de pêlos em região sacral."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-183143","number":"183143","sourceNumber":"183143","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A hiperbilirrubinemia, no período neonatal, decorrente de processo hemolítico, é\nencontrada nas condições abaixo, EXCETO:","options":{"A":"Incompatibilidade ABO.","B":"Deficiência de Glocose-6-fosfato desidrogenase.","C":"Incompatibilidade RH.","D":"Síndrome de Gilbert.","E":"Esferocitose."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-183156","number":"183156","sourceNumber":"183156","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"As manifestações oculares da síndrome da rubéola congênita são: I. catarata; II.\nretinopatia pigmentar; III. microftalmia; IV. descolamento da retina. Estão corretas as\nalternativas","options":{"A":"I, II, III e IV.","B":"I e IV, apenas.","C":"II e III, apenas.","D":"III e IV, apenas.","E":"I, II e III, apenas."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-183173","number":"183173","sourceNumber":"183173","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A síndrome da rubéola congênita é uma importante complicação da infecção pelo vírus\nda rubéola durante a gestação, principalmente\nno primeiro trimestre, podendo comprometer o\ndesenvolvimento do feto e causar aborto, morte fetal e anomalias congênitas. As manifestações\nclínicas da síndrome da rubéola congênita podem ser transitórias, permanentes ou tardias. É(São)\nmanifestação(ões) que faz(em) parte da síndrome da rubéola congênita I. Surdez; II. Catarata; III.\nCardiopatia; IV. Retardo mental. Está (ão) correta(s) a(s) alternativa(s):","options":{"A":"I, II, III e IV.","B":"III, apenas.","C":"I e IV, apenas.","D":"II e III, apenas.","E":"I, II e III, apenas."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-159076","number":"159076","sourceNumber":"159076","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A aferição da glicemia por fita em avaliação de rotina de recém-nascidos pré-termo\nassintomático revela um valor de 20 mg/dl. A conduta a ser tomada é:","options":{"A":"Oferecer soro glicosado por sucção.","B":"Aguardar resultado de glicemia venosa.","C":"Infundir glicose por via venosa.","D":"Oferecer mamadeira com fórmula para prematuros."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-159092","number":"159092","sourceNumber":"159092","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O índice de APGAR quantifica e resume a resposta de recém-nascido ao ambiente\nextrauterino. Deve ser avaliado no primeiro e\nno quinto minuto após o nascimento. Quando\nnecessário, devem-se repetir contagens adicionais a cada cinco minutos, até o 20° minuto. Analise\nas afirmações a seguir. I. O índice de APGAR é utilizado para determinar a indicação e as ações de\nreanimação que o recém-nascido irá receber. II. A cada um dos sinais avaliados na composição do\níndice de APGAR é atribuído um valor que varia entre 0 (pior situação) e 2 (melhor situação). III.\nOs\nsinais avaliados para compor o índice de APGAR são: frequência cardíaca, respiração, tônus\nmuscular, irritabilidade reflexa e coloração da pele. IV. Recém-nascido que recebe pontuação do\níndice de APGAR igual a dez (10) apresenta-se corado, com frequência cardíaca maior que 100\nbatimentos por minuto, respiração irregular, tônus flácido, espirro ou choro ao ser estimulado.\nEstão\ncorretas as afirmativas:","options":{"A":"I, II e III apenas.","B":"II,III e IV apenas.","C":"I,II e IV apenas.","D":"I, III e IV apenas."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-135959","number":"135959","sourceNumber":"135959","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação aos fatores de risco para\nhiperbilirrubinemia significante:","options":{"A":"Icterícia precoce;","B":"RNPT (recém-nascido pré-termo) tardio;","C":"Perda de peso superior a 7%,","D":"Descendência negra."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-135964","number":"135964","sourceNumber":"135964","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Dentre as alternativas a seguir, assinale aquela que NÃO apresenta sinais clínicos\nusualmente associados à hipoglicemia neonatal.","options":{"A":"Irritabilidade ou hipotonia;","B":"Recusa alimentar ou convulsões;","C":"Febre alta ou sudorese excessiva;","D":"Letargia ou tremores."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-135989","number":"135989","sourceNumber":"135989","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Laura está no 7° dia de vida, veio em sua primeira consulta pediátrica, nasceu de parto\ncesáreo por desproporção céfalo pélvica, à termo, chorou ao nascer, Apgar 9/9, peso de 3.200 gr e\n49 cm de comprimento. Mãe informa que a recém-nascida está em aleitamento materno exclusivo,\nmas que acha o seu leite fraco e que sua bebê dorme muito. Você examina a menor e encontra\numa icterícia leve zona II, peso de 2.950gr, comprimento de 50 cm, manchas mongólicas em região\nglútea, manchas ectásicas em região frontal de cicatriz umbilical de bom aspecto, sem outras\nalterações no exame físico. Qual a sua conduta?","options":{"A":"Tranquilizar a mãe, pois as alterações encontradas fazem parte do exame físico normal do\nrecém-nascido;","B":"Prescrever fórmula láctea de partida, pois a menor apresentou perda ponderal considerando o\npeso do nascimento, além de manter o\naleitamento materno;","C":"Orientar a mãe para acordar o bebê rigorosamente de 3/3 horas para estabelecer uma rotina\nalimentar e incrementar o ganho ponderal.","D":"Solicitar uma dosagem de bilirrubinas total e frações urgente, para avaliar a indicação de\nfototerapia e suspender o aleitamento materno pela possiblilidade de icterícia relacionada ao\naleitamento materno."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-108629","number":"108629","sourceNumber":"108629","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A conduta em relação à alimentação de um recém-nascido em boas condições de\nvitalidade, com idade gestacional de 34 semanas e pesando 2.400 g é:","options":{"A":"Leite artificial por gavagem.","B":"Leite artificial no copinho.","C":"Amamentação ao seio materno.","D":"Leite materno por gavagem."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-108770","number":"108770","sourceNumber":"108770","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação ao teste de oximetria, conhecido como o teste do coraçãozinho, marque a\nalternativa que MENOS corresponde ao objetivo da implantação deste teste de triagem, cuja\nrecomendação é que seja realizado em todos os recém-nascidos antes da alta hospitalar.","options":{"A":"O objetivo do teste do coraçãozinho é o de realizar uma triagem para a identificação de todas as\ncardiopatias congênitas, especialmente as cardiopatias com sopro cardíaco bem audível no período\nneonatal.","B":"A relevância do diagnóstico das cardiopatias congênitas está na tentativa de se reduzir a\nmortalidade infantil, pelo Pacto pela Vida, uma vez que as cardiopatias congênitas representam\ncerca de 10% dos óbitos infantis e cerca de 20% a 40% dos óbitos decorrentes de malformações\ncongênitas.","C":"Considerando que cerca de 1 a 2 em cada 1.000 recém-nascidos vivos apresentam cardiopatia\ncongênita crítica e que 30% destes recém-nascidos recebem alta hospitalar sem diagnóstico,\nevoluindo para óbito precoce, antes mesmo de receber tratamento, o teste do coraçãozinho está\nsendo implantado.","D":"O ecocardiograma deve ser realizado nos casos confirmados pela oximetria de pulso (Saturação\nSpO2 menor que 95% ou diferença igual ou\nmaior que 3% entre as medidas dos membros)."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-84456","number":"84456","sourceNumber":"84456","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Na Toxoplasmose congênita, no período neonatal, é característico o encontro de:","options":{"A":"Proteinorraquia elevada.","B":"Hipernatremia.","C":"Trombocitose.","D":"Hiperglobulinemia.","E":"Acolia fecal."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-66941","number":"66941","sourceNumber":"66941","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em uma unidade básica de saúde você atende um lactente de seis meses de idade que\nfoi levado à unidade por apresentar uma virose, febre baixa há um dia e coriza nasal. Durante o\nexame foi constatado que a criança se encontrava em bom estado geral, porém era hipotônica,\nsustentou a cabeça com cinco meses e ainda não rolava. Apresentava ainda uma fácies, infiltrada,\nmixedema, pele seca, obstipação e déficit de crescimento que foram notados pela mãe desde os\ndois meses de vida. As vacinas estavam em dia e a criança não realizou a triagem neonatal. Qual a\nhipótese diagnóstica mais provável?","options":{"A":"Desnutrição proteicocalórica.","B":"Síndrome Nefrótica.","C":"Fenilcetonúria.","D":"Hipotireoidismo congênito."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-66985","number":"66985","sourceNumber":"66985","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"<p>Recém-nascido apresentando orifício na parede abdominal de 3 cm de diâmetro, à\ndireita do cordão umbilical, com exteriorização de estômago e alças intestinais, sem membrana\nrecobrindo as alças. Qual o diagnóstico da malformação descrita?</p>","options":{"A":"Gastrosquise.","B":"Onfalocele.","C":"Extrofia de cloaca.","D":"Anomalia anorretal."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-341080","number":"341080","sourceNumber":"341080","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Menino recém-nascido pré-termo, limitrofe, apresenta peso adequado para a idade\ngestacional. No prontuário o Teste do\nCoraçãozinho foi registrado como \"\"normal\"\". Quanto ao\nTeste da Orelhinha a genitora foi orientada a agendar em um serviço de Fonoaudiologia, após a\nalta. O teste de Bruckner (Teste do Olhinho), realizado na maternidade imediatamente antes do\nhorário previsto para a alta, apresenta \"\"reflexo vermelho bilateral\"\". Considerando o caso,\nindique a\nconduta adequada, quanto ao achado no Teste do Olhinho:","options":{"A":"Relatar teste normal aos familiares.","B":"Repetir o teste na maternidade em 24 horas.","C":"Solicitar Mapeamento de Retina pelo oftalmologista.","D":"Repetir o teste com o oftalmologista em uma semana."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-341081","number":"341081","sourceNumber":"341081","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Menino recém-nascido pré-termo, limitrofe, apresenta peso adequado para a idade\ngestacional. No prontuário o Teste do Coraçãozinho foi registrado como \"\"normal\"\". Quanto ao\nTeste da Orelhinha a genitora foi orientada a agendar em um serviço de Fonoaudiologia, após a\nalta. O teste de Bruckner (Teste do Olhinho), realizado na maternidade imediatamente antes do\nhorário previsto para a alta, apresenta \"\"reflexo vermelho bilateral\"\". Indique o parâmetro\nprincipal\naferido pelo Teste do Olhinho:","options":{"A":"Integridade da mácula retiniana.","B":"Presença de edema na papila óptica.","C":"Simetria do reflexo luminoso nas córneas.","D":"Integridade dos meios oculares transparentes."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-341082","number":"341082","sourceNumber":"341082","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Menino recém-nascido pré-termo, limitrofe, apresenta peso adequado para a idade\ngestacional. No prontuário o Teste do Coraçãozinho foi registrado como \"\"normal\"\". Quanto ao\nTeste da Orelhinha a genitora foi orientada a agendar em um serviço de Fonoaudiologia, após a\nalta. O teste de Bruckner (Teste do Olhinho), realizado na maternidade imediatamente antes do\nhorário previsto para a alta, apresenta \"\"reflexo vermelho bilateral\"\". Indique a idade preconizada\npara maximizar a eficácia na realização da triagem pelo Teste da Orelhinha, se não for feito na\nmaternidade:","options":{"A":"28 dias.","B":"60 dias.","C":"90 dias.","D":"180 dias."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313442","number":"313442","sourceNumber":"313442","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação às causas de Calcificações Abdominais no recém-nascido, assinale a\nalternativa incorreta.","options":{"A":"Atresia jejunal ou ileal.","B":"Imaturidade funcional do cólon.","C":"Íleo meconial.","D":"Anomalia anorretal com fistula retovesical."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-307063","number":"307063","sourceNumber":"307063","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Menino nascido a termo há 20 dias, com peso adequado para a idade gestacional, sem\nintercorrências no parto ou na gestação, é levado à UBS com quadro de icterícia há 4 dias, que tem\naumentado de intensidade. Foi observada alteração na coloração das fezes e da urina. O bebê está\nem aleitamento materno exclusivo. No momento está ativo e afebril; acianótico; descorado +/IV;\nictérico +++/IV; auscultas cardíaca e respiratória sem anormalidades; fígado palpável a 1,5cm do\nrebordo costal direito, com superfície lisa, consistência endurecida; baço palpável a 1,5cm do\nrebordo costal esquerdo, endurecido. Sem outras alterações ao exame segmentar. Diante do\nquadro clínico, indique o diagnóstico provável para esse bebê.","options":{"A":"Icterícia fisiológica.","B":"Hepatite neonatal.","C":"Colestase neonatal.","D":"Icterícia do leite materno."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-307064","number":"307064","sourceNumber":"307064","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Menino nascido a termo há 20 dias, com peso adequado para a idade gestacional, sem\nintercorrências no parto ou na gestação, é levado à UBS com quadro de icterícia há 4 dias, que tem\naumentado de intensidade. Foi observada alteração na coloração das fezes e da urina. O bebê está\nem aleitamento materno exclusivo. No momento está ativo e afebril; acianótico; descorado +/IV;\nictérico +++/IV; auscultas cardíaca e respiratória sem anormalidades; fígado palpável a 1,5cm do\nrebordo costal direito, com superfície lisa, consistência endurecida; baço palpável a 1,5cm do\nrebordo costal esquerdo, endurecido. Sem outras alterações ao exame segmentar. Indique a\nconduta imediata para esse caso.","options":{"A":"Orientar banhos de sol.","B":"Administrar Interferon alfa.","C":"Suspender o leite materno.","D":"Encaminhar para especialista."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-307065","number":"307065","sourceNumber":"307065","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Menino nascido a termo há 20 dias, com peso adequado para a idade gestacional, sem\nintercorrências no parto ou na gestação, é levado à UBS com quadro de icterícia há 4 dias, que tem\naumentado de intensidade. Foi observada alteração na coloração das fezes e da urina. O bebê está\nem aleitamento materno exclusivo. No momento está ativo e afebril; acianótico; descorado +/IV;\nictérico +++/IV; auscultas cardíaca e respiratória sem anormalidades; fígado palpável a 1,5cm do\nrebordo costal direito, com superfície lisa, consistência endurecida; baço palpável a 1,5cm do\nrebordo costal esquerdo, endurecido. Sem outras alterações ao exame segmentar. Identifique entre\nas causas listadas a seguir, aquelas que se apresentam como provocadoras da hiperbilirrubinemia\ndireta no recém-nascido. I) Fisiológica. II) Hiperesplenismo. III) Doença hepática. IV) Doença das\nvias biliares. A alternativa que apresenta a resposta correta é:","options":{"A":"I, II e III","B":"I, II e IV","C":"I, III e IV","D":"II, III e IV"},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-307080","number":"307080","sourceNumber":"307080","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Bebê, sexo masculino, é levado, duas semanas após o parto, na maternidade de\nnascimento, com febre e eritema\nmaculopapular em tronco, palmas e plantas de pés, com secreção\nnasal serosanguinolenta e hipocromia de mucosas. A mãe não fez pré-natal completo. Um exame\nda mãe revela VDRL positivo com título de 1:32. Com relação à epidemiologia da sífilis congênita\nno Brasil, pode se afirmar:","options":{"A":"A incidência da sífilis congênita aumentou na última década.","B":"Houve redução de incidência pediátrica, e aumento da sífilis do adulto.","C":"O coeficiente de mortalidade infantil por sífilis reduziu nos últimos dez anos.","D":"Houve aumento do diagnóstico em gestantes, com redução da sífilis congênita."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-278621","number":"278621","sourceNumber":"278621","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Levando em consideração a fisiopatologia da Encefalopatia Hipóxico Isquêmica (EHI),\nassinale a alternativa correta.","options":{"A":"A protease hidrolisa, prioritariamente, os fosfolipídios celulares, mas também pode causar a\nruptura do esqueleto celular.","B":"A fosfolipase hidrolisa os fofolipidios celulares, com liberação de ácido araquidônico e seus\nmetabólitos NMDA e AMPA.","C":"NMDA e AMPA são receptores gliais específicos que determinam a entrada de cálcio no\ncompartimento intracelular, com ativação de enzimas como protease e fosfolipase.","D":"A despolarização neural provoca a liberação de glutamato, aminoácido neuroinibitório, que se\nacumula nos espaços intersinápticos e intercelulares."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-278622","number":"278622","sourceNumber":"278622","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"São indicadores de mau prognóstico na encefalopatia hipóxico isquêmica do\nrecém-nascido todos os abaixo, exceto.","options":{"A":"Asfixia grave e prolongada.","B":"Hipertensão intracraniana (>10mmHg).","C":"Poliúria persistente.","D":"Convulsões de início precoce."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-275993","number":"275993","sourceNumber":"275993","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Você, acompanhando o serviço de pediatria do hospital de referência da sua cidade,\nauxilia na avaliação inicial de um\nrecém-nascido. Após avaliar os três parâmetros, você verifica que\né um recém- nascido com necessidade de reanimação. Em relação ao tema, analise a sequência a\nseguir e assinale a alternativa INCORRETA.","options":{"A":"Os passos iniciais para um recém-nascido com mais de 34 semanas são: prover calor,\nposicionar a cabeça em leve extensão, aspirar vias aéreas (se necessário) e secar o\nrecém-nascido.","B":"Caso a frequência cardíaca seja menos que 100 bpm, haja apneia ou respiração irregular e seja\num recém-nascido com menos de 34 semanas, deve- se iniciar ventilação com pressão positiva\ncom balão e máscara facial com uma concentração de O2 de 21%, monitorar SatO2 com oximetria\nde pulso e monitorização cardíaca.","C":"Caso a frequência cardíaca continue menor que 100 bpm, deve-se checar a técnica e considerar\nintubação.","D":"Caso a frequência cardíaca continue a diminuir e fique menor que 60 bpm, indica-se a intubação\ntraqueal, massagem cardíaca, O2 a 100% e considerar cateterismo venoso.","E":"Caso a frequência cardíaca continue menor que 60 bpm, indica-se a administração de\nadrenalina endovenosa, preferencialmente pela veia umbilical."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-279050","number":"279050","sourceNumber":"279050","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre as causas de calcificações abdominais no neonato, assinale a alternativa\nincorreta.","options":{"A":"Íleo meconial.","B":"Atresia jejunal ou ileal.","C":"Anomalia anorretal com fistula retovesical.","D":"Imaturidade funcional do cólon."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-278631","number":"278631","sourceNumber":"278631","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa que apresenta o intervalo de temperatura alvo central da\nhipotermia terapêutica do recém-nascido.","options":{"A":"De 29,5 a 30,5 graus celsius.","B":"De 30,5 a 31,5 graus celsius.","C":"De 32,5 a 33,5 graus celsius.","D":"De 33,5 a 34,5 graus celsius."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-279051","number":"279051","sourceNumber":"279051","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual das condições a seguir é causa de enterocolite necrotizante em recém nascidos\nnão prematuros?","options":{"A":"Cardiopatia congênita cianótica.","B":"Estenose hipertrófica do piloro.","C":"Atresia do duodeno.","D":"Má rotação com bandas de Ladd."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-278636","number":"278636","sourceNumber":"278636","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Enterocolite necrotizante é a emergência gastrointestinal mais comum no período\nneonatal. Embora vários fatores contribuintes\nforam identificados, o fator de risco mais importante\npara apresentação da doença é:","options":{"A":"Aleitamento materno.","B":"Cateter central.","C":"Sexo feminino.","D":"Prematuridade."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-278644","number":"278644","sourceNumber":"278644","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A hérnia diafragmática congênita é uma causa relativamente comum de desconforto\nrespiratório neonatal. A maioria destas hérnias ocorrem no lado esquerdo. Assinale a correta.","options":{"A":"As hérnias diafragmáticas congênitas posterolaterais são conhecidas como hérnias de\nBochdalek.","B":"As hérnias diafragmáticas congênitas posterolaterais são conhecidas como hérnias de Morgagni.","C":"As hérnias diafragmáticas congênitas anteromediais são conhecidas como hérnias de Stoppa.","D":"As hérnias diafragmáticas congênitas anteromediais são conhecidas como hérnias de\nBochdalek."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-231344","number":"231344","sourceNumber":"231344","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido, 40 semanas de idade gestacional, Apgar 9/10, sem fatores de risco,\napresenta icterícia em face com 18 horas de vida. História obstétrica sem fatores de risco. Grupo\nsanguíneo materno: O +, do RN: B +. Exame físico: ativo, mamando bem, já eliminou mecônio e\napresentou diurese. Nesse caso, está indicado:","options":{"A":"aguardar completar 24 horas e colher exames para avaliar exsanguineotransfusão.","B":"observar e reavaliar a icterícia antes da alta para decidir sobre a realização de exames.","C":"colher exames laboratoriais para avaliar incompatibilidade ABO e decidir sobre fototerapia.","D":"suspender o aleitamento materno, pois se trata de icterícia associada ao aleitamento materno.","E":"indicar exanguineo transfusão pelo risco de kernicterus"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-231349","number":"231349","sourceNumber":"231349","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Todas as alternativas representam a indicação de Ventilação com Pressão Positiva na\nsala de parto. EXCETO:","options":{"A":"RN com 1apneia","B":"RN com respiração irregular","C":"RN com Freq Cardíaca menor que 100 bpm","D":"RN com Hérnia Diafragmática","E":"RN com Gasping"},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-231351","number":"231351","sourceNumber":"231351","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém nascido de 39 semanas, parto cesáreo, adequado para a idade gestacional,\nApgar 9/10, bolsa rota no ato, líquido\namniótico claro, apresenta taquipneia com retrações\nintercostais logo após o parto. Exame físico: ausculta pulmonar sem crepitantes. RX de tórax:\naumento da trama vascular pulmonar. História obstétrica: sem intercorrências. Diante do quadro, o\ndiagnóstico é:","options":{"A":"pneumonia do recém-nascido.","B":"síndrome de aspiração meconial.","C":"taquipneia transitória do recém- -nascido.","D":"hipertensão pulmonar persistente do recém-nascido.","E":"membrana hialina"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-249289","number":"249289","sourceNumber":"249289","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual é o objetivo do acompanhamento ambulatorial do prematuro?","options":{"A":"Realizar o diagnóstico precoce das alterações de crescimento.","B":"Identificar as alterações de peso no recém-nascido.","C":"Detectar os possíveis desvios do crescimento normal, principalmente quanto ao peso, ao\ncomprimento e ao perímetro cefálico.","D":"Detectar os possíveis desvios do crescimento do perímetro cefálico."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-249205","number":"249205","sourceNumber":"249205","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual é a dose de suplementação de cálcio e fósforo indicada para o recém-nascido\npré-termo?","options":{"A":"02 ml/kg/dia, duas vezes ao dia.","B":"03 ml/kg/dia, três vezes ao dia.","C":"03 ml/kg/dia, nos intervalos das mamadas.","D":"02 ml/kg/dia, nos intervalos das mamadas."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-249212","number":"249212","sourceNumber":"249212","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Observe as alternativas abaixo e assinale aquela que não representa uma causa\ncomum de icterícia no período neonatal.","options":{"A":"Anemia falciforme.","B":"Deficiência de G6PD.","C":"Icterícia pelo leite materno.","D":"Icterícia fisiológica."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-249215","number":"249215","sourceNumber":"249215","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Observando a figura apresentada abaixo, responda qual alteração morfológica está\npresente.","options":{"A":"Polidactilia","B":"Geno valgo","C":"Sindactilia","D":"Pés em garra"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-201775","number":"201775","sourceNumber":"201775","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Todas as alternativas representam a indicação de ventilação com pressão positiva,\nEXCETO:","options":{"A":"RN com apneia.","B":"RN com respiração irregular.","C":"RN com frequência cardíaca menor que 100 bpm.","D":"RN com hérnia diafragmática.","E":"RN com Gasping."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-201783","number":"201783","sourceNumber":"201783","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A equipe MÍNIMA para atender ao RN na sala de parto deveria:","options":{"A":"Um médico capaz de realizar todos os procedimentos de plantão à distância.","B":"Um profissional de saúde que saiba todos os passos iniciais e faça a ventilação com máscara\nem cada nascimento.","C":"Um profissional de saúde que saiba os passos\niniciais e chame um médico se for necessário ventilar.","D":"Um obstetra capaz de realizar todos os passos.","E":"Ter um técnico de saúde que saiba todos os passos inclusive os procedimentos invasivos como\nintubação e cateterismo umbilical em todos os nascimentos."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-215524","number":"215524","sourceNumber":"215524","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Todas as patologias citadas a seguir são comuns no período neonatal, EXCETO:","options":{"A":"Taquipneia transitória.","B":"Síndrome de aspiração do mecônio.","C":"Pneumonia lobar.","D":"Onfalocele."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-219860","number":"219860","sourceNumber":"219860","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de 3 dias de vida sob seus cuidados receberá alta da maternidade\nnesse momento. Sobre as triagens neonatais universais\nindicadas nessa idade, qual alternativa\nestá CORRETA para orientação aos pais:","options":{"A":"A triagem neonatal auditiva ou \"teste de orelhinha\" inclui a realização de avaliação por meio de\nemissões otoacústicas evocadas.","B":"A triagem neonatal biológica ou \"teste do pezinho\" avalia distúrbios congênitos e hereditários,\ndentre eles a tirosinemia.","C":"A triagem neonatal de cardiopatias congênitas críticas ou \"teste do coraçãozinho\" deve ser\nrealizada após as primeiras 24 horas de vida.","D":"A triagem neonatal ocular ou \"teste do olhinho\" é realizada através do teste do reflexo vermelho\nque avalia opacificação da retina."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-212163","number":"212163","sourceNumber":"212163","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Diante de um recém-nascido assintomático com história materna de toxoplasmose na\ngestação é correto afirmar:","options":{"A":"o pediatra deve ficar atento mesmo sem manifestações clínicas no momento do parto, devido à\nevolução posterior da doença com alterações oculares, como placas de coriorretinite e outras\nsequelas.","B":"deve-se colher sangue para testes sorológicos e, se a IgM for negativa, descartar a possibilidade\nde transmissão transplacentária.","C":"deve-se atentar para as questões oculares e, uma vez que passe no teste da orelhinha,\ndescartar a possibilidade de déficit auditivo.","D":"o diagnóstico de Toxoplasmose Congênita é baseado exclusivamente na comparação dos títulos\nsorológicos.","E":"a atenção deve incluir pneumonites, anormalidades ósseas e neurológicas subclínicas."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-187778","number":"187778","sourceNumber":"187778","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Mãe acompanhada no pré-natal de risco habitual. Realizou sorologias com resultados\nnegativos para sífilis, HIV e hepatite B.\nImune a Toxoplasmose. Deu entrada na maternidade em\ntrabalho de parto e história de perda de líquido há 20 horas, com idade gestacional estimada de 34\nsemanas. Parto por via vaginal, imediatamente após a internação. Com uma hora de vida,\ndificuldade respiratória, apresentando pontuação de 4 pelo Boletim de Silverman-Anderson. Qual a\nconduta CORRETA em relação a abordagem de sepse neonatal precoce pelo estreptococo do\ngrupo B?","options":{"A":"Alta a partir de 24 horas se clinicamente estável","B":"Iniciar antibioticoterapia logo após o nascimento","C":"Manter o recém-nascido em observação clínica por 48 horas","D":"Solicitar exames laboratoriais: hemograma, hemocultura e PCR e aguardar resultado da\nhemocultura para iniciar antibioticoterapia"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-182736","number":"182736","sourceNumber":"182736","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Visando a adoção de estratégia protetora, com objetivo de minimizar os efeitos\nadversos da ventilação mecânica invasiva em prematuros extremos, deve-se:","options":{"A":"Evitar valores de PaCO2 acima de 45mmHg.","B":"Manter a saturação de oxigênio de 85% a 89%.","C":"Promover o recrutamento alveolar com uso de PEEP de 8 a 10cmH2O.","D":"Utilizar volume corrente de 4 a 6ml/Kg."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-187789","number":"187789","sourceNumber":"187789","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa CORRETA em relação aos distúrbios metabólicos no período\nneonatal?","options":{"A":"A hipocalcemia neonatal precoce apresenta-se, na maioria das vezes, sintomática","B":"Asfixia perinatal não é o fator de risco para hipocalcemia","C":"Não há sintomas específicos associados a hipoglicemia, podendo os mesmos estarem\npresentes em outros distúrbios metabólicos","D":"Para filhos de mãe diabética está indicado screening mais prolongado, estendendo-se por 48 a\n72 horas de vida"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-182751","number":"182751","sourceNumber":"182751","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Quanto à transmissão do HIV em crianças, pode-se afirmar que:","options":{"A":"Atualmente predomina-se a transmissão pelo sangue e seus produtos contaminados com HIV.","B":"A maioria é infectada pela transmissão materno-infantil, durante a gestação e o parto e por meio\ndo aleitamento.","C":"O convívio social com os pais infectados tem sido causa frequente de transmissão aos filhos.","D":"A transmissão materno-infantil de mãe soropositiva para o HIV ocorre em mais de 90% das\ngestações."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-187803","number":"187803","sourceNumber":"187803","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Lactente, 40 dias de vida, sexo masculino com quadro de icterícia prolongada. Nasceu\nde parto normal, pesando 3kg. Exames de\ntriagem neonatal normais. Qual achado é o MAIS\nINDICATIVO de diagnóstico de atresia de vias biliares?","options":{"A":"Colúria","B":"Esplenomegalia","C":"Ganho de peso adequado","D":"Presença de fezes acólicas"},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-182816","number":"182816","sourceNumber":"182816","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Dentro da definição de caso, existem critérios utilizados para definição de casos de\nSífilis Congênita. Abaixo estão listados os do Primeiro Critério, porém um deles está inadequado,\nassinale-o:","options":{"A":"Criança cuja mãe apresente, durante o pré-natal ou no momento do parto, teste para sífilis não\ntreponêmico reagente com qualquer titulação e teste treponêmico reagente, que não tenha sido\ntratada ou tenha recebido tratamento inadequado.","B":"Criança cuja mãe não foi diagnosticada com sífilis durante a gestação e, na impossibilidade de a\nmaternidade realizar o teste treponêmico, apresente teste não treponêmico reagente com qualquer\ntitulação no momento do parto.","C":"Criança cuja mãe apresente, durante o pré-natal ou no momento do parto, teste para sífilis não\ntreponêmico reagente com qualquer titulação e teste treponêmico reagente, que tenha sido tratada\nou tenha recebido tratamento adequado.","D":"Criança cuja mãe não foi diagnosticada com sífilis durante a gestação e, na impossibilidade de a\nmaternidade realizar o teste não treponêmico, apresente teste treponêmico reagente no momento\ndo parto."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152631","number":"152631","sourceNumber":"152631","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual é a conduta de eleição que deve ser estabelecida em um recém-nascido a termo,\ncuja mãe é portadora de sífilis e a\nsorologia do RN é positiva?","options":{"A":"Penicilina cristalina por 14 dias.","B":"Eritromicina por 15 dias.","C":"Cefalosporina por 7 dias.","D":"Cefalosporina de terceira geração por 10 dias.","E":"Amoxicilina oral por 8 dias."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152640","number":"152640","sourceNumber":"152640","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O primeiro minuto de vida (denominado de ouro), refere ao tempo máximo após o\nnascimento para iniciar:","options":{"A":"Ventilação com pressão positiva.","B":"Oferta de O2 suplementar\n\n.","C":"Intubação orotraqueal.","D":"Massagem cardíaca.","E":"Adrenalina EV."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152645","number":"152645","sourceNumber":"152645","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Indicações de ventilação com pressão positiva por máscara, exceto:","options":{"A":"Apneia.","B":"Respiração Irregular.","C":"FC < 100 bpm.","D":"Suspeita de Hérnia Diafragmática.","E":"Gasping."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152630","number":"152630","sourceNumber":"152630","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-Nascido, Pequeno para Idade Gestacional (PIG), apresenta microcefalia, lábio\nsuperior fino e fenda palpebral pequena. Qual substancia pode ter sido usada pela mãe?","options":{"A":"Álcool.","B":"Cocaína.","C":"Maconha.","D":"Benzodiazepínico.","E":"Heroína."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-158776","number":"158776","sourceNumber":"158776","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em que idade gestacional ocorre risco mais elevado para ocasionar Síndrome da\nRubéola Congênita?","options":{"A":"Nas primeiras 11 semanas.","B":"Entre 12 e 13 semanas.","C":"Entre 13 e 15 semanas.","D":"Entre 15 e 16 semanas.","E":"Acima de 17 semanas."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131340","number":"131340","sourceNumber":"131340","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Dentre os itens abaixo, aquele que é fator preditivo de risco para icterícia neonatal\nsevera é:","options":{"A":"Gestação de mais de 40 semanas.","B":"História familiar negativa para deficiência de glicose 6 fosfato desidrogenase.","C":"Bilirrubina sérica maior que 5mg% nas primeiras 24 horas de vida.","D":"Uso de meperidina durante o parto.","E":"Parto vaginal."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131345","number":"131345","sourceNumber":"131345","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Ao nascer, a maioria dos recém-nascidos com infecção congênita por citomegalovírus\né:","options":{"A":"Asfixiada.","B":"Assintomática.","C":"Pré-termo.","D":"Pequeno para a idade gestacional.","E":"Natimorto."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131350","number":"131350","sourceNumber":"131350","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A pele do recém-nascido normal pode apresentar as seguintes características,\nEXCETO:","options":{"A":"Milium sebáceo.","B":"Hemangioma macular.","C":"Eritema tóxico.","D":"Máculas brancas.","E":"Vérnix."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-140164","number":"140164","sourceNumber":"140164","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O procedimento mais adequado na prevenção da síndrome da morte súbita do\nlactente:","options":{"A":"Dormir com os pais","B":"Usar pulsoximetro","C":"Usar travesseiro macio e alto","D":"Colocar em decúbito lateral para evitar engasgo","E":"Cocar em posição supina"},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131386","number":"131386","sourceNumber":"131386","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual das alternativas abaixo corresponde, na sequência correta ao A, B e C da\nreanimação neonatal:","options":{"A":"Iniciar a respiração, manter a circulação e manter a via aérea pérvia.","B":"Manter a via aérea pérvia, manter a circulação e iniciar a respiração.","C":"Manter a via aérea pérvia, iniciar a respiração, e manter a circulação.","D":"Iniciar a respiração, manter a via aérea pérvia e manter a circulação.","E":"Nenhuma das anteriores."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131393","number":"131393","sourceNumber":"131393","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Quando o recém-nascido é prematuro ou apresenta alterações na respiração, tônus\ne/ou coloração da pele ou mucosa, quais são os\npassos iniciais da reanimação que devem ser\nexecutados, em sequência? I ? aspirar a boca e as narinas; II ? colocar o RN sob fonte de calor\nradiante; III ? posicionar a cabeça do RN; IV ? secar o RN e desprezar os campos úmidos.","options":{"A":"II; III; I; IV.","B":"IV; II; III; I.","C":"I; IV; II; III.","D":"III; I; II; IV.","E":"III; II; I; IV."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131331","number":"131331","sourceNumber":"131331","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma criança acabou de nascer. Ela foi colocada sob calor radiante, posicionada,\naspirada e feita a estimulação tátil, porém,\npermanece em apnéia. Qual a sua conduta?","options":{"A":"Administrar oxigênio inalatório a 100%.","B":"Administrar oxigênio inalatório a 80%.","C":"Ventilar através da administração de oxigênio sobre pressão nas narinas.","D":"Ventilar com oxigênio através de ambu e máscara.","E":"Ventilar com oxigênio através de tubo endotraqueal."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-134844","number":"134844","sourceNumber":"134844","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Na sala de parto, rotineiramente, aplica-se 1 mg intramuscular, no recém-nascido, de\nvitamina K. Essa medida visa evitar qual das patologias abaixo?","options":{"A":"Púrpura trombocitopênica.","B":"Eritroblastose fetal.","C":"Deficiência nutricional.","D":"Doença hemorrágica."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-134851","number":"134851","sourceNumber":"134851","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"É causa de hemorragia retiniana em lactentes, além da síndrome do bebê sacudido:","options":{"A":"Parto normal.","B":"Discrasia sanguínea.","C":"Endocardite.","D":"Hipertensão grave."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-134064","number":"134064","sourceNumber":"134064","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A triagem auditiva neonatal deve ser realizada","options":{"A":"nos recém-nascidos com alterações craniofaciais.","B":"nos recém-nascidos que foram internados em UTI neonatal.","C":"em todos os recém-nascidos com 24 ? 48h de vida.","D":"nos recém-nascidos que apresentam achados clínicos sugestivos de infecção congênita."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-134060","number":"134060","sourceNumber":"134060","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, atendido na sala de parto 30 segundos após o nascimento,\nnão apresenta movimentos respiratórios espontâneos e\na sua frequência cardíaca é de 90 bpm.\nDiante de tal caso, indique a conduta CORRETA.","options":{"A":"Infundir adrenalina EV.","B":"Ventilar com pressão positiva.","C":"Prover 100% de oxigênio.","D":"Realizar massagem cardíaca."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-134067","number":"134067","sourceNumber":"134067","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A infecção congênita que o Ministério da Saúde considera como evento sentinela é a:","options":{"A":"Sífilis.","B":"Varicela.","C":"adenovirose.","D":"citomegalovirose."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-134820","number":"134820","sourceNumber":"134820","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O exame considerado como padrão ouro pela literatura para a pesquisa de maturidade\npulmonar fetal é:","options":{"A":"O teste de Clements.","B":"A pesquisa de corpos lamelares.","C":"A pesquisa de fosfatidilglicerol.","D":"A relação lecitina/esfingomielina."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-110531","number":"110531","sourceNumber":"110531","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Dentre os itens abaixo, aquele que é fator preditivo de risco para icterícia neonatal\nsevera é:","options":{"A":"Gestação de mais de 40 semanas;","B":"História familiar negativa para deficiência de\nglicose 6-fosfato desidrogenase;","C":"Bilirrubina sérica maior que 5 mg/dL nas primeiras 24 horas de vida;","D":"Uso de meperidina durante o parto;","E":"Parto vaginal."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-110536","number":"110536","sourceNumber":"110536","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Ao nascer, a maioria dos recém-nascidos com infecção congênita por citomegalovírus\né:","options":{"A":"asfixiado;","B":"assintomática;","C":"pré-termo;","D":"pequeno para a idade gestacional;","E":"natimorto."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-110544","number":"110544","sourceNumber":"110544","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido de cinco dias é trazido ao ambulatório. Ele está clinicamente bem e\na mãe procura o serviço porque ele está\nmuito \"amarelo?. Além de bilirrubina total e frações, os\nexames a serem solicitados são:","options":{"A":"transaminases e hemograma;","B":"hemograma e contagem de reticulócitos;","C":"transaminases e marcadores de hepatite;","D":"reticulócitos e tipagemsanguínea (mãe e recém-nascido);","E":"tipagemsanguínea (mãe e recém-nascido) e marcadores de hepatite."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-110558","number":"110558","sourceNumber":"110558","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma criança acabou de nascer. Ela foi colocada sob calor radiante, posicionada,\naspirada e feita a estimulação tátil, porém,\npermanece em apneia. Qual a sua conduta?","options":{"A":"ventilar com oxigênio através de ambu e máscara;","B":"administrar oxigênio inalatório a 80%;","C":"ventilar através da administração de oxigênio sobre pressão nas narinas;","D":"administrar oxigênio inalatório a 100%;","E":"ventilar com oxigênio através de tubo endotraqueal."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-109985","number":"109985","sourceNumber":"109985","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Logo após o nascimento um recém-nascido de termo apresenta-se com taquipneia,\nretrações com piora progressiva e cianose persistente. O abdome encontra-se escavado.\n\nVentilação com bolsa máscara é iniciada. A auscuta revela sons respiratórios diminuídos à\nesquerda e bulhas cardíacas que são mais\nintensas à direita. A explicação MAIS provável para\nesses achados é:","options":{"A":"Dextrocardia com situs solitus.","B":"Pneumotórax.","C":"Hérnia diafragmática.","D":"Atresia esofágica com fístula traqueoesofágica."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-109989","number":"109989","sourceNumber":"109989","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Dos agentes abaixo, qual é o MENOS provável de causar sepse neonatal de início\nprecoce?","options":{"A":"L. monocytogenes.","B":"Estreptococos do grupo B.","C":"Streptococcus pneumoniae.","D":"E. coli."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-109993","number":"109993","sourceNumber":"109993","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual das afirmações seguintes é VERDADEIRA a respeito de infecção congênita por\nCMV?","options":{"A":"Coriorretinite é a manifestação clínica mais comum.","B":"Infecção fetal ocorre apenas após infecção materna primária.","C":"Recém- nascidos infectados eliminam vírus na urina.","D":"Sequelas a longo prazo não ocorrem em neonatos infectados que são sintomáticos."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-109996","number":"109996","sourceNumber":"109996","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém- nascido pequeno para a idade gestacional, que apresenta microcefalia,\nerupção petequial disseminada, cataratas\nbilaterais e estenose pulmonar, provavelmente apresenta\nqual infecção?","options":{"A":"Rubéola.","B":"Citomegalovírus.","C":"Toxoplasmose.","D":"Sífilis."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-109779","number":"109779","sourceNumber":"109779","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN pré-termo tardio, com IG 36 semanas e 5 dias, peso de nascimento 2.580 g, recebe\nalta com 72 horas de vida, com aleitamento\nmaterno exclusivo e pesando 2.300 g, com bons\ncontroles de dextro. Qual é a sua orientação na alta?","options":{"A":"Retorno em 48 horas no consultório para reavaliação.","B":"Retorno em 1 semana no consultório para reavaliação.","C":"Retorno para reavaliação quando completar 15 dias de vida.","D":"Retorno para reavaliação após tomar vacina da hepatite B."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-110024","number":"110024","sourceNumber":"110024","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Criança com lábio e palato fendidos. Qual é a próxima etapa da avaliação?","options":{"A":"Ultrassonografia transfontanela.","B":"Consulta com cirurgia plástica.","C":"Exame físico cuidadoso.","D":"Cariótipo."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-86654","number":"86654","sourceNumber":"86654","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Indique a alternativa errada:","options":{"A":"Situações como controle de glicemia capilar, fototerapia e uso de antibioticoterapia são\nsuficientes para que o recém-nascido não possa permanecer em alojamento conjunto.","B":"Parto operatório, doença mental materna, depressão puerperal e dificuldades de deambulação\nmaterna não são contraindicações para o\nalojamento conjunto.","C":"O sistema de alojamento conjunto não isenta a equipe multiprofissional de sua responsabilidade\ncom os cuidados com o neonato.","D":"Bebês portadores de toxoplasmose congênita, bem como anomalias congênitas menores podem\nser referenciados para o sistema de alojamento\nconjunto.","E":"A alta hospitalar do neonato a termo, saudável, sem intercorrências, deve se dar após 48 horas\nde vida."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-86679","number":"86679","sourceNumber":"86679","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Ao reavaliar um recém-nascido a termo durante a assistência em sala de parto, após\nmedidas iniciais de aquecimento, posicionamento e desobstrução de vias aéreas, nota-se padrão\nrespiratório irregular e frequência cardíaca de 70 bpm. A melhor conduta, segundo diretrizes do\nprograma de reanimação neonatal, a ser seguida é:","options":{"A":"Realizar ventilação com pressão positiva com balão autoinflável sob máscara e O2 a 100%\ninicialmente, caso não haja dispositivo blender, com reavaliação de frequência cardíaca, cor e\npadrão respiratório em 30 segundos.","B":"Realizar ventilação com pressão positiva com balão autoinflável sob máscara e ar ambiente\ninicialmente, caso não haja dispositivo blender, com reavaliação de frequência cardíaca e padrão\nrespiratório em 30 segundos.","C":"Realizar ventilação com pressão positiva com balão autoinflável sob tubo endotraqueal com O2\na 100% inicialmente, com reavaliação de\nfrequência cardíaca e cor após 30 segundos.","D":"Realizar ventilação com pressão positiva com ventilador mecânico manual em tubo T sob\nmáscara com O2 a 50% inicialmente, caso tenha dispositivo blender acoplado.","E":"Realizar ventilação com pressão positiva com balão autoinflável sob tubo endotraqueal com ar\nambiente, com reavaliação de frequência cardíaca e cor após 30 segundos."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-86684","number":"86684","sourceNumber":"86684","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Puérpera com 23 anos dá à luz recém-nascido a termo, com boas condições de\nvitalidade e sem nenhuma anormalidade ao\nexame físico. Durante coleta de dados do pré-natal,\nrevela que no terceiro trimestre de gestação o VDRL se tornou positivo na diluição 1:32. Afirma que\niniciou tratamento 20 dias antes do parto com penicilina benzatina e que seu parceiro não\nnecessitou de medicamento, já que foi não reator. Considerando as normas do Ministério da\nSaúde, a melhor conduta dentre as descritas será:","options":{"A":"Não realizar investigação neste momento, já que a mãe foi adequadamente tratada, devendo ser\nrealizado acompanhamento ambulatorial do neonato.","B":"Colher novo VDRL materno, além de hemograma, punção lombar, radiografia de ossos longos e\nVDRL sangue periférico do recém-nascido e, caso qualquer alteração destes ou impossibilidade de\nseguimento, iniciar tratamento.","C":"Colher apenas VDRL materno e de sangue periférico do recém-nascido. Se o do neonato for\ntitulação maior ou igual a da mãe: iniciar tratamento com penicilina procaína por 14 dias.","D":"Colher VDRL materno e de sangue periférico do recém-nascido. Caso o do neonato for menor\nque o da mãe, fazer ainda assim dose de\npenicilina benzatina, para então liberar alta hospitalar.","E":"Colher VDRL do recém-nascido. Se menor que o materno em pelo menos 1 titulação, deverá\nreceber alta, sem maiores investigações."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-86623","number":"86623","sourceNumber":"86623","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, 39 semanas, com peso de nascimento: 3450 g, inicia icterícia\ncom 22 horas de vida, sem outras alterações\nao exame físico. A tipagem sanguínea materna é O\nnegativo e a do neonato é B positivo. Teste de Coombs direto negativo. A hipótese mais provável é:","options":{"A":"Icterícia neonatal tardia fisiológica.","B":"Icterícia neonatal precoce por incompatibilidade sanguínea ABO.","C":"Icterícia neonatal precoce por incompatibilidade sanguínea ABO e RH.","D":"Icterícia neonatal precoce por incompatibilidade sanguínea RH.","E":"Icterícia neonatal tardia por deficiência da enzima glicose-6-fosfato desidrogenase."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-86629","number":"86629","sourceNumber":"86629","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto cesárea, na ausência de trabalho de parto, prematuro tardio e\npeso de nascimento: 2.350 g, evoluiu com\ndesconforto respiratório precoce, necessitando de\nsuporte de oxigenoterapia, sob <i>hood</i> com fiO2: 30%, apresentando à radiografia de tórax:\nalargamento de espaços intercostais, com retificação de arcos, além de cisurite à direita. O\ndiagnóstico mais provável neste caso é:","options":{"A":"Síndrome do desconforto respiratório.","B":"Síndrome de aspiração meconial.","C":"Síndrome de aspiração do líquido amniótico.","D":"Pneumonia intrauterina.","E":"Taquipneia transitória do recém-nascido."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-86862","number":"86862","sourceNumber":"86862","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual o tempo preconizado, baseado em evidência, recomendado para clampeamento\ndo cordão umbilical em recém nascidos?","options":{"A":"Clampear quando não sentir a pulsação do\ncordão umbilical;","B":"3 minutos;","C":"2 minutos;","D":"1 minuto;","E":"Nenhuma das anteriores."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-86878","number":"86878","sourceNumber":"86878","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Lactente de 2 meses é trazido à consulta médica por apresentar choro frequente e\nobstrução nasal. No exame físico apresenta-se com palidez importante, dor intensa na\nmanipulação de membro superior direito, rinite piosanguinolenta, e hepatoesplenomegalia. O\ndiagnóstico mais provável para o caso é:","options":{"A":"Sífilis congênita;","B":"Septicemia;","C":"Leucemia;","D":"Maus tratos;","E":"Rubéola congênita."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-158413","number":"158413","sourceNumber":"158413","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um médico, em um exame de um recém nascido, faz a manobra de Barlow e ela é\npositiva. Neste caso, a articulação comprometida é a do:","options":{"A":"Pé.","B":"Coluna vertebral.","C":"Cotovelo.","D":"Ombro.","E":"Quadril."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-158418","number":"158418","sourceNumber":"158418","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Criança\nnascida a termo, por cesariana de urgência devido a descolamento prematuro de placenta,\napresenta-se em apneia e cianótica após receber passos iniciais de reanimação. Qual o passo a\nseguir?","options":{"A":"Entubação traqueal acompanhada de oxigênio inalatório para imediata ventilação.","B":"Iniciar ventilação por pressão positiva com ar ambiente com balão e máscara, e instalar\noximetria de pulso.","C":"Oferecer oxigênio inalatório por 30 segundos e verificar oximetria de pulso.","D":"Instalar oximetria de pulso e realizar estímulo tátil.","E":"Realizar expansão com soro fisiológico ? 10 ml/kg."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-362430","number":"362430","sourceNumber":"362430","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A afecção respiratória que acomete mais frequentemente recém-nascidos prematuros\ncom menos de 28 semanas de gestação, do sexo\nmasculino, em filhos de mães diabéticas, e que\nsofreram asfixia ao nascimento, chama-se:","options":{"A":"Síndrome do escape de ar.","B":"Síndrome da aspiração de mecônio.","C":"Síndrome da hipertensão pulmonar persistente neonatal.","D":"Síndrome do desconforto respiratório por deficiência de surfactante alveolar."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-362427","number":"362427","sourceNumber":"362427","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Pedro, RN a termo, adequado para idade gestacional, PN 3400g, filho de mãe\ncomorbidade e com pré-natal adequado,\nultrassom morfológico normal. Sorologia de toxoplasmose\ncom 7 semanas de gestação: IgM (método Elisa) positivo, IgG positivo, com alta avidez. Exame\nclínico normal ao nascimento. A conduta recomendada é:","options":{"A":"realizar avaliação de fundo de olho, ultrassonografia transfontanela e abdominal, hemograma,\npunção lombar e sorologias do recém-nascido,\nantes de indicar o tratamento.","B":"coletar sorologia para toxoplasmose do sangue do cordão, realizar fundoscopia e indicar o\ntratamento dependendo do resultado.","C":"realizar cuidados de rotina, não havendo necessidade de investigação diagnóstica ou de\ntratamento do recém-nascido.","D":"iniciar tratamento com sulfadiazina, pirimetamina e ácido folínico por um ano,\nindependentemente do resultado de exames."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-362424","number":"362424","sourceNumber":"362424","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante em acompanhamento pré-natal fez diagnóstico de HIV com 29 semanas.\nIniciou TARV e fez uso regular até o\nnascimento do bebê. A Carga viral (CV) com 38 semanas era\nde 1400 cópias. Com relação ao manejo do RN, qual deverá ser a conduta no alojamento conjunto:","options":{"A":"Coletar CV ao nascimento e iniciar profilaxia com AZT + 3TC + RAL por 28 dias.","B":"Coletar CV no primeiro dia de vida e iniciar profilaxia com AZT xarope por 28 dias.","C":"Coletar CV no 14° dia de vida e iniciar profilaxia com AZT e NVP por 28 dias.","D":"Coletar CV ambulatorialmente e iniciar profilaxia com TDF + 3TC + DTG."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-327286","number":"327286","sourceNumber":"327286","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Pedro é recém-nascido a termo, com peso de nascimento de 3 Kg, filho de mãe que\ndescobriu HIV na 20ª semana de gestação. Iniciou uso de TARV, assim que teve o diagnóstico. No\nmomento do Parto, não havia registro da Carga Viral, após o início da TARV. Qual a conduta mais\nadequada com Pedro na maternidade e seguimento:","options":{"A":"Coletar CV na sala de parto, aguardar resultado para iniciar TARV profilática por via oral e\nencaminhar para seguimento, com coleta de nova CV com: 14 dias, na 6ª e 12ª semana de vida.","B":"Coletar CV na sala de parto, iniciar AZT, 3TC e RAL por via oral e encaminhar para seguimento\ncom coleta de nova CV com: 14 dias, na 6ª e 12ª\nsemana de vida.","C":"Coletar CV na sala de parto, iniciar AZT por via oral e encaminhar para seguimento com coleta\nde nova CV com: 14 dias, na 6ª e 12ª semana\nde vida.","D":"Coletar CV na sala de parto, iniciar AZT, NVP por via oral e encaminhar para seguimento com\ncoleta de nova CV com: 14 dias, na 6ª e 12ª semana de vida."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-298250","number":"298250","sourceNumber":"298250","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido a termo, com 25 horas de vida, é submetido ao teste do\ncoraçãozinho (teste de oximetria), obtendo o\nseguinte resultado: membro superior direito 100% e\nmembro inferior esquerdo 96%. A conduta que deve ser tomada nessa situação é:","options":{"A":"Dar alta com 48 horas de vida, sem investigação adicional.","B":"Realizar ecocardiograma com urgência.","C":"Repetir o exame em uma hora e, se permanecer alterado, indicar ecocardiograma.","D":"Internar em UTI neonatal, iniciar prostaglandina IV para manter o canal arterial prévio e,\nsomente\ndepois, solicitar ecocardiograma."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-298254","number":"298254","sourceNumber":"298254","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante de 21 anos, primigesta, teve a primeira consulta de pré-Natal no primeiro\ntrimestre de gestação e apresentou teste rápido para HIV positivo. Foi encaminhada para\nacompanhamento no SAE e manteve o pré-natal na UBS. Apresentou a primeira carga viral HIV\n\n25.000 cópias, CD4 520 células. Iniciou tratamento com TDF + 3TC + DTG após 20 semanas de\ngestação. Não tinha outras ISTs ou comorbidades. Com 35 semanas de idade gestacional realizou\nnova Carga viral que estava em 1000 cópias. O Bebê nasceu com 39 semanas de gestação, parto\ncesárea, peso de nascimento 3500g Estatura 49cm PC 35 cm, apgar 9/10. Com relação a\nclassificação materna e as medidas a serem tomadas com relação ao recém nascido na\nmaternidade, assinale a alternativa CORRETA:","options":{"A":"Gestante de alto risco. Coletar Carga viral do RN, iniciar profilaxia com AZT + 3TC + Raltegravir\ne não amamentar.","B":"Gestante de baixo risco. Coletar Carga viral do RN, iniciar profilaxia com AZT e não amamentar.","C":"Gestante de alto risco. Coletar Carga viral do RN, iniciar profilaxia com AZT + Nevirapina e não\namamentar.","D":"Gestante de baixo risco. Coletar Carga viral do RN, iniciar profilaxia com AZT e liberar\namamentação."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-298255","number":"298255","sourceNumber":"298255","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Você é o plantonista da maternidade no interior e recebe uma parturiente que chega em\nperíodo expulsivo. Ao realizar os testes rápidos, vêm os seguintes resultados: HBsAg negativo, HIV\nnegativo, Sífilis reagente. O bebê nasce ativo, com Idade gestacional de 37 semanas, PN 2800g\nEst 48 cm PC 34 cm, com exame físico normal. Recebe aleitamento na sala de parto e vai para o\nalojamento conjunto. Você pede à mãe o cartão do pré-Natal e verifica que no primeiro trimestre ela\napresentou FTAbs positivo e VDRL 1:128. Ela nunca teve sífilis, não apresentava sintomas e nem o\nparceiro. Ambos receberam 3 doses de penicilina benzatina 1.200.000Ui em cada nádega por 3\nsemanas com intervalo de 7 dias entre elas, todas registradas no cartão. Possuem relacionamento\nestável e monogâmico. No segundo trimestre o VDRL encontrava-se 1:64 e na maternidade o\nexame veio 1:16. Você solicita VDRL do RN e vem 1:16 Como você classificaria a mãe e qual sua\nconduta com relação ao RN?","options":{"A":"Mãe adequadamente tratada. Trata-se de Bebê exposto a sífilis que deverá realizar VDRL com\n1, 3, 6 meses no seguimento ambulatorial.","B":"Mãe adequadamente tratada. Trata-se de Bebê com sífilis congênita que deverá receber\npenicilina cristalina ou procaina, dependendo do resultado do liquor.","C":"Mãe inadequadamente tratada. Trata-se de Bebê exposto a sífilis que deverá realizar VDRL com\n1, 3, 6 meses no seguimento ambulatorial.","D":"Mãe inadequadamente tratada. Trata-se de Bebê com sífilis congênita que deverá receber\npenicilina cristalina ou procaina, dependendo do resultado do liquor."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-298264","number":"298264","sourceNumber":"298264","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo nasceu de parto vaginal após uma gestação sem\nintercorrências. Ao exame inicial, observa-se\nque a criança apresenta opacificação do cristalino de\nambos os olhos, com reflexo vermelho ausente. O pai havia realizado cirurgia em idade precoce.\nSem outras alterações no restante do exame físico. O diagnóstico mais provável é:","options":{"A":"Catarata congênita","B":"Glaucoma congênito","C":"Atrofia de nervo optico","D":"Toxoplasmose congênita"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-286765","number":"286765","sourceNumber":"286765","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido a termo, com peso de nascimento de 3000g evoluiu após alguns\nminutos de vida com taquipnéia e cianose central. Ao exame está hidratado, com murmúrio\nvesicular audível em ambos os hemitórax e ausência de sopro cardíaco. O oxímetro de pulso na\nmão direita mostra saturação de 86%. O RN é então colocado no halo de oxigênio e após 20\nminutos a saturação atinge o valor de 88%. A hipótese diagnóstica mais provável é:","options":{"A":"Taquipnéia transitória","B":"Cardiopatia congênita cianogênica","C":"Pneumonia congênita","D":"Síndrome do sequestro pulmonar"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-286770","number":"286770","sourceNumber":"286770","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"São doenças detectadas através do teste do pezinho no SUS:","options":{"A":"Anemia falciforme, hipotireoidismo, fibrose cística e fenilcetonúria.","B":"Anemia de fanconi, hiperparatireoidismo, fibrose cistica e deficiência de biotinidase.","C":"Hiperplasia adrenal congênita, deficiência de G6PD, fibrose cistica e deficiência de\nbiotinidase.","D":"Anemia falciforme, hiperparatireoidismo, deficiência de G6PD e fenilcetonúria."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-286771","number":"286771","sourceNumber":"286771","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido de parto cesárea por DHEG, apgar 7/8, PN 1450g, comprimento 43\ncm e perímetro cefálico 31 cm recebeu\nestimativa de idade gestacional de 33 semanas e 4 dias.\n\nClassifique o recém-nascido:","options":{"A":"Macrossômico ao nascer","B":"Baixo peso ao nascer","C":"Muito baixo peso ao nascer","D":"Extremo baixo peso ao nascer"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-286774","number":"286774","sourceNumber":"286774","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A sífilis congênita ainda representa um sério problema de saúde pública no Brasil.\nSobre esta infecção, é CORRETO afirmar que:","options":{"A":"O acometimento fetal é mais comum quando a infecção materna ocorre no primeiro trimestre da\ngestação.","B":"A infecção transplacentária pode ocorrer durante toda a gestação e em qualquer estágio de\ninfecção materna.","C":"O teste treponêmico de amostra de cordão umbilical apresenta uma boa sensibilidade e\nespecificidade.","D":"O VDRL é um bom marcador para diagnóstico no recém-nascido, mas não serve para\nseguimento."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-252268","number":"252268","sourceNumber":"252268","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Você é chamado na sala de parto para atender um recém-nascido. O recém-nascido é\nde termo, sexo masculino, parto vaginal.\nNasceu hipotônico, choro ausente. Levado ao berço\naquecido, você posiciona o RN, aspira vias aéreas e ao exame ele se encontra em apneia e com\nfrequência cardíaca ausente, qual seu próximo passo?","options":{"A":"Iniciar massagem cardíaca.","B":"Ventilação com pressão positiva com máscara.","C":"Intubação traqueal.","D":"Adrenalina 1:10 000 em veia umbilical 0,1ml/Kg."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-252274","number":"252274","sourceNumber":"252274","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Na sala de parto um recém-nascido de termo é seco e estimulado ao nascer, está em\napneia, hipotônico e cianótico com frequência cardíaca de 70 bpm. Com um minuto de vida,\ncontinua cianótico, hipotônico e tem uma frequência cardíaca de 70 bpm, respirando irregularmente\na uma taxa de 15 respirações por minuto e faz algumas caretas durante a estimulação, mas não\nchora. A equipe segue as diretrizes apropriadamente, faz ventilação com pressão positiva com\nmáscara. Aos 5 minutos, a frequência cardíaca subiu para 90 bpm, o tronco ficou corado (mas as\nmãos e os pés permanecem cianóticos), está respirando espontaneamente e tem melhora do tônus\nflexor, mas não se movimenta ativamente. Aos 10 minutos, o lactente está chorando, respirando, se\nmovimentando ativamente, completamente corado e com frequência cardíaca de 120 bpm. Quais\nnotas foram as pontuações do Boletim de Apgar dessa criança?","options":{"A":"3, 7 e 9.","B":"3, 6 e 10.","C":"4, 6 e 9.","D":"4, 7 e 10."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-252275","number":"252275","sourceNumber":"252275","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido masculino, 10 dias de vida, vem à consulta na UBS pela primeira vez.\nFoi um recém-nascido de termo, parto\ncesáreo, sem intercorrências, com peso de nascimento de\n3.350g, boletim de Apgar 9/10/10. Tipagem sanguínea materna e do RN: B+. A criança recebeu alta\nno 3º dia de vida, com peso de 3.100g. Na consulta de hoje, a mãe refere que produz bastante leite\ne que a criança suga bem, mas está cansada porque a criança quer mamar de hora em hora,\neventualmente com intervalos de 30 minutos entre as mamadas. Criança evacua três vezes ao dia,\ncom fezes amareladas. Diurese clara, com 4 trocas de fraldas ao dia. Ao exame clínico, apresenta\nicterícia zona III, sem outras alterações significativas. Peso atual de 3.205g. A conduta indicada\né:","options":{"A":"Encaminhar a mãe para avaliação psicológica e convocar familiares para auxiliarem o cuidado.","B":"Reforçar a manutenção do regime de livre demanda e realizar seguimento habitual de\npuericultura.","C":"Iniciar fototerapia, com investigação de infecções, doenças metabólicas e erros inatos do\nmetabolismo.","D":"Orientar mamadas mais longas e efetivas, e marcar retorno precoce para reavaliação do peso."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-208303","number":"208303","sourceNumber":"208303","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante de 39 semanas deu entrada na maternidade em trabalho de parto.\nApresentou VDRL do 3º trimestre da gestação\nreagente com titulação 1:4 e relata ter feito\ntratamento com eritromicina porque a paciente referia \"alergia a penicilina\". O recém-nascido\nnasceu vigoroso e assintomático. Foi realizado VDRL no sangue periférico do recém-nascido cujo\nresultado mostrou-se \"reagente\" 1:2. Qual é a alternativa que melhor descreve o estado clínico e a\nconduta para o recém-nascido?","options":{"A":"Não haveria necessidade de investigação sorológica no RN, pois a eritromicina é droga de\nescolha no caso de história de alergia à penicilina.","B":"Não é portador de sífilis congênita, pois seu valor do VDRL é menor que o valor do exame da\nmãe. Alta com orientações.","C":"Portador de sífilis congênita. Utilizar ceftriaxona devido à possibilidade de alergia à\npenicilina no\nrecém-nascido.","D":"Portador de sífilis congênita. Utilizar penicilina cristalina."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-208364","number":"208364","sourceNumber":"208364","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, filho de mãe com diabetes gestacional, com peso de\nnascimento de 4350 g. Exame físico com 1 hora\nde vida: neurológico normal; com capacidade de\nsucção ativa. Exames laboratoriais: glicemia capilar = 35 mg/dl; hematócrito = 55%. Após coletar\nsangue para dosagem de glicose, a melhor conduta é:","options":{"A":"Infusão rápida de glicose intravenosa a 10% e repetir a dosagem de glicose.","B":"Colocar o recém-nascido para aleitamento materno e repetir glicemia capilar.","C":"Aguardar o resultado para a decisão de como proceder.","D":"Administrar fórmula láctea por sonda gástrica e repetir a glicemia capilar"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-176089","number":"176089","sourceNumber":"176089","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Você é o médico responsável pelo alojamento conjunto de uma maternidade municipal\ne se depara com um recém-nascido a termo,\nparto vaginal e com peso de nascimento de 3.450 g,\nem seu primeiro dia de vida. Paciente apresenta exame clínico sem alterações significativas e\nencontra-se com boa aceitação do aleitamento materno exclusivo. Ao verificar carteira de pré-natal,\nvocê percebe que a mãe apresenta sorologia para toxoplasmose negativa, em coleta realizada no\nsegundo trimestre, e positiva, em coleta realizada no terceiro trimestre de gestação. Diante do\ndescrito, assinale a assertiva que é considerada CORRETA neste momento:","options":{"A":"Recomenda-se coleta de teste sorológico da criança e, frente a resultado negativo, afasta-se a\npossibilidade de infecção perinatal.","B":"Caso confirmada a infecção perinatal por toxoplasmose, o paciente deverá receber tratamento\nmedicamentoso com sulfadiazina, pirimetamina e ácido folínico por até 6 meses.","C":"Caso confirmada a infecção perinatal por toxoplasmose, devemos ficar atentos às possíveis\ncomplicações tardias que o recém-nascido pode\napresentar, dentre elas a cardiopatia congênita é a\nmais frequente.","D":"Recomenda-se coleta de testes sorológicos da mãe e recém-nascido, além de avaliação\nadicional inicial com hemograma completo,\nfundoscopia ocular e ultrassonografia transfontanelar."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-176115","number":"176115","sourceNumber":"176115","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto normal, a termo, apresenta icterícia com 22 horas de vida.\nTipagem Sanguínea (TS) da mãe: O +; TS do RN: A+. Exame físico: discreta icterícia em face e\nparte superior do tórax. Exames laboratoriais: BT = 12 mg/dl; Coombs direto fracamente positivo,\npresença de esferócitos na lâmina de sangue periférico e teste da fragilidade osmótica negativo. A\nhipótese diagnóstica é:","options":{"A":"Doença hemolítica isoimune ABO.","B":"Doença hemolítica isoimune Rh.","C":"Esferocitose hereditária.","D":"Deficiência congênita de piruvatoquinase."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-151949","number":"151949","sourceNumber":"151949","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, adequado para a idade gestacional, apresenta icterícia com 16\nhoras de vida, sem outras alterações ao exame físico. A mãe tem tipagem sanguínea \"O\" negativo\ne, o recém-nascido, \"A\" positivo; Coombs direto: negativo. A hipótese diagnóstica é:","options":{"A":"Icterícia fisiológica.","B":"Doença hemolítica pelo sistema ABO.","C":"Icterícia associada ao aleitamento materno.","D":"Deficiência de glicose-6-fosfato desidrogenase."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-151893","number":"151893","sourceNumber":"151893","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de termo, com 48h de vida, desenvolve pápulas brancas e pequenas\ndistribuídas pela face, tronco e extremidades. O esfregaço dessas pápulas contém eosinófilo. O\ndiagnóstico provável é:","options":{"A":"Eritema tóxico.","B":"Miliária neonatal.","C":"Impretigo neonatal.","D":"Melanose pustular."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-151911","number":"151911","sourceNumber":"151911","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Como trato um recém-nascido com sífilis congênita diagnosticada na primeira semana\nde vida:","options":{"A":"Penicilina benzatina 50.000 U\\kg\\dia dose única IM.","B":"Penicilina procaina 100.000 U\\kg\\dia por 12\\12h IM.","C":"Penicilina G eristalina 25.000-50.000 U\\kg\\dia - 6\\6h dia EV.","D":"Penicilina G cristalina aquosa 100.000-150.000 U\\kg\\dia - 12\\12h EV."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-151927","number":"151927","sourceNumber":"151927","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual a principal ação do surfactante no pulmão do recém-nascido?","options":{"A":"Regular a produção de lecitina e esfingomielina, que estão diminuídos no final da inspiração.","B":"Reduzir a tensão superficial e auxiliar a manter estabilidade alveolar, diminuindo o colapso de\nespaços aéreos no final da expiração.","C":"Induzir o crescimento da árvore alveolar e aumentar a tensão superficial e colapso no final da\nexpiração.","D":"Inibir a síntese de proteínas que levam ao acúmulo de líquidos dentro dos sacos alveolares."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-129808","number":"129808","sourceNumber":"129808","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A avaliação da vitalidade ao nascer tem sido apontada como o principal elemento para\na indicação de necessidade de reanimação\nneonatal. Para isso recomenda-se que se faça uma\navaliação rápida da vitalidade do concepto, respondendo a quatro perguntas. Assinale abaixo a\nalternativa que contenha as perguntas recomendadas.","options":{"A":"Gestação a termo?; Respiração regular?; Ausência de mecônio?; Irritabilidade reflexa?","B":"Gestação pré-termo?; Chorando?; Cianose central?; Tônus muscular em flexão?","C":"Gestação a termo?; Frequência Cardíaca > 100 bpm?; Presença de mecônio?; Presença de\nCianose?","D":"Gestação a termo?; Ausência de mecônio?; Respirando ou chorando?; Tônus muscular bom?"},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-129750","number":"129750","sourceNumber":"129750","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Menino nascido a termo, por via vaginal, de mãe primípara com 22 anos, a gravidez\ntranscorreu sem complicações. Pouco antes do parto, uma bradicardia foi percebida no feto e, no\nmomento do parto, havia presença de mecônio espesso. O recém-nascido apresenta-se com\nhipotonia e bradicardia. Qual das opções a seguir é o primeiro passo da reanimação?","options":{"A":"Administração de epinefrina por meio de tubo endotraqueal.","B":"Ventilação com dispositivo bolsa-máscara.","C":"Intubação endotraqueal com sucção direta.","D":"Administração de oxigênio por cânula junto às narinas."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-107851","number":"107851","sourceNumber":"107851","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Os recém-nascidos (RN) compõem um grupo heterogênio. Quanto ao tamanho ao\nnascer, responda a assertiva CORRETA.","options":{"A":"Pequeno para a idade gestacional (PIG), abaixo do percentil 10, dependendo da idade\ngestacional.","B":"Grande para a idade gestacional (GIG), entre percentil 10 e 90, dependendo da idade\ngestacional.","C":"Pequeno para a idade gestacional (PIG), abaixo do percentil 10, independente da idade\ngestacional.","D":"Grande para a idade gestacional (GIG), acima do percentil 90, dependendo da idade\ngestacional."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-107860","number":"107860","sourceNumber":"107860","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A icterícia é um dos problemas mais frequentes no período neonatal. Quanto a etiologia\nda hiperbilirrubinemia indireta no RN. Assinale abaixo\nqual assertiva correspondente entre a\npatologia e hiperbilirrubinemia.","options":{"A":"Atresia de Vias Biliares Extra Hepática - icterícia não colestática.","B":"Síndrome da Icterícia por Leite Materno - icterícia não colestática.","C":"Síndrome de Gilbert - Icterícia colestática.","D":"Clampeamento tardio ou ordenha do cordão - icterícia colestática."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-103786","number":"103786","sourceNumber":"103786","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A listeriose deve estar incluída no diagnóstico diferencial de infecções por:","options":{"A":"Bronquiolite","B":"Diarreia","C":"Sepse neonatal","D":"Difteria"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-103811","number":"103811","sourceNumber":"103811","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de quatro dias de vida nasceu de parto normal e a termo, está em\naleitamento materno exclusivo e apresenta eliminação de secreção sanguinolenta pela vagina,\npequenos lábios proeminentes, e glândulas mamárias aumentadas bilateralmente. A conduta\nindicada nesse caso é:","options":{"A":"Solicitar pesquisa de 17-cetosteroides.","B":"Prescrever creme vaginal inespecífico.","C":"Solicitar cromatina sexual e cariótipo.","D":"Tranquilizar a mãe e observar a evolução."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-103819","number":"103819","sourceNumber":"103819","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"De acordo com a classificação da Organização Mundial de Saúde, recém nascido a\ntermo é aquele que apresenta idade gestacional de:","options":{"A":"36 a 40 semanas e 6 dias","B":"37 a 40 semanas","C":"37 a 41 semanas e 6 dias","D":"38 a 42 semanas"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-87467","number":"87467","sourceNumber":"87467","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Os Recém-Nascidos (RN) compõem um grupo heterogêneo. Quanto ao peso ao\nnascer, responda a assertiva CORRETA.","options":{"A":"RN classificados como RN de Peso Extremamente Baixo ao nascer apresentam peso ao\nnascimento inferior a 1500 g, independente da idade gestacional;","B":"RN classificados como RN de Baixo Peso apresentam peso ao nascimento inferior a 2500 g,\nindependente da idade gestacional;","C":"RN classificados como RN de Peso Extremamente Baixo ao nascer apresentam peso ao\nnascimento inferior a 2000 g, independente da idade gestacional;","D":"RN de tamanho excessivamente grande são aqueles cujo peso ao nascimento é igual ou\nsuperior a 3500 g, independente da idade gestacional;","E":"RN classificados como RN de Baixo Peso apresentam peso ao nascimento inferior a 3000 g."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-87421","number":"87421","sourceNumber":"87421","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O índice de Apgar é um método objetivo de quantificar a condição do recém-nascido e\né útil para se obter informações sobre o\nestado geral e a reação à reanimação. Qual seria o valor\ndo índice de APGAR, de um recém-nascido que após as medidas de reanimação apresentava\nrespiração irregular, frequência cardíaca maior que 100 bpm, movimento ativo, corpo rosado,\nextremidades cianóticas e choraminga?","options":{"A":"APGAR de 4.","B":"APGAR de 10.","C":"APGAR de 2.","D":"APGAR de 3.","E":"APGAR de 7."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-87471","number":"87471","sourceNumber":"87471","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Baseado na estratégia do Ministério da Saúde, OPAS, 2012, para Atenção Integral às\nDoenças Prevalentes na Infância (AIDPI) Neonatal,\nclassifique o Risco ao Nascer para o\n\nrecém-nascido, que apresenta: peso ao nascer < 2.000 g, desconforto respiratório, rotura\nprematura de membranas 18h antes do parto, febre\nmaterna, idade gestacional < 35 semanas.","options":{"A":"Baixo Risco ao Nascer.","B":"Médio Risco ao Nascer.","C":"Alto Risco ao Nascer.","D":"Muito Baixo Risco ao Nascer.","E":"Gravidez de Baixo Risco."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81953","number":"81953","sourceNumber":"81953","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O conteúdo de vitamina K do leite humano é baixo e pode contribuir para doença\nhemorrágica do recém nascido. Então, ao\nnascer, qual dose de vitamina K deve ser administrada\nao recém nascido?","options":{"A":"0,5 g via oral;","B":"0,5 g via parenteral;","C":"1 mg subcutâneo;","D":"1 mg via parenteral;","E":"2 mg via parenteral."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81919","number":"81919","sourceNumber":"81919","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Lactentes cujas manifestações clínicas e biópsia hepática sugerem obstrução biliar,\ndevem realizar:","options":{"A":"Transplante hepático;","B":"Laparotomia exploradora e colangiografia direta para determinar a presença e o local da\nobstrução;","C":"Reposição de vitaminas e lipossolúveis;","D":"Ultrassonografia abdominal;","E":"Cintilografia hepatobiliar."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81973","number":"81973","sourceNumber":"81973","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido com 24h de vida, nascido de parto vaginal, apresentação pélvica, pré\nnatal sem intercorrências, apresenta um \"clique\" do quadril quando se faz a abdução das coxas a\npartir de uma flexão do joelho e quadril. Qual a provável patologia do recém-nascido?","options":{"A":"Doença de legg -Calvé- Perthes;","B":"Sinovite transitória do quadril;","C":"Displasia do desenvolvimento do quadril;","D":"Epifisiólise;","E":"Doença de Osgood-Schlatter."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-80965","number":"80965","sourceNumber":"80965","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A icterícia é um dos problemas mais frequentes no período neonatal. Quanto à etiologia\nda hiperbilirrubinemia indireta no RN. Assinale abaixo\nqual assertiva NÃO corresponde à\napresentação de icterícia por hiperbilirrubinemia indireta.","options":{"A":"Atresia de Vias Biliares Extra Hepática.","B":"Síndrome da Icterícia por Leite Materno.","C":"Síndrome de Gilbert.","D":"Céfalo-hematoma.","E":"Clampeamento tardio ou ordenha do cordão."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-60853","number":"60853","sourceNumber":"60853","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de Termo (RNT), peso ao nascer 3,600g parto normal. Apgar 9' e 10',\nem aleitamento materno exclusivo, apresentou icterícia, com BT = 10 mg/dl. Os exames\nlaboratoriais afastaram a hipótese diagnóstica: infecção, incompatibilidade sanguínea e deficiência\nG6PD. Qual a sua conduta?","options":{"A":"Introduzir fórmula láctea","B":"Iniciar hidratação venosa","C":"Estimular aleitamento materno","D":"Contraindicar aleitamento materno","E":"Oferecer solução glicosada 5% por sucção"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-60833","number":"60833","sourceNumber":"60833","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação aos cuidados a serem tomados com o recém-nascido de Mãe soropositiva\npara o Vírus da Imunodeficiência Humana (HIV).\nMarque a alternativa CORRETA:","options":{"A":"O antirretroviral aprovado para uso na criança é a azitromicina que está disponível como solução\noral ou endovenosa e a dose preconizada\npara um recém-nascido a termo é 2 mg/kg/dose por via\noral a cada 6 horas.","B":"O recém-nascido deve ser banhado com água e sabão logo após o parto, assim que esteja\nestável, pois somente após a remoção de secreções maternas pode-se administrar medicações\ninjetáveis.","C":"Deve ser amamentado na primeira hora de vida para que adquira anticorpos maternos\nprotetores e não desenvolva a doença.","D":"Deve-se imediatamente, após o parto, realizar um teste rápido do recém-nascido para saber se\nele está contaminado.","E":"A profilaxia com antirretroviral deve ser administrada a criança 12 horas após o nascimento."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-60861","number":"60861","sourceNumber":"60861","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante diagnosticada com Lues no pré-natal foi tratada com eritromicina por 21 dias\npor ser alérgica à penicilina. O recém-nato nasce assintomático. Qual a melhor conduta a ser\ntomada em relação a este bebê?","options":{"A":"O recém-nascido, mesmo assintomático, deve ser avaliado incluindo VDRL de sangue periférico,\nradiografia dos ossos longos, liquor cefalorraquidiano (VDRL, celularidade e proteinorraquia),\nhemograma completo, para então definir o tratamento.","B":"A mãe é considerada adequadamente tratada, já que fez eritromicina por 21 anos, e como o\nrecém-nascido é assintomático, não há necessidade de investigação diagnóstica.","C":"O teste VDRL negativo no recém-nascido exclui a possibilidade de sífilis congênita.","D":"Deve-se acompanhar este recém-nascido por 10 dias e, se ele permanecer assintomático,\npode-se dar alta epidemiológica.","E":"O recém-nascido deve ser avaliado com VDRL em sangue periférico, hemograma completo e\nradiografia de ossos longos, mas não há necessidade de avaliação do liquor cefalorraquidiano já\nque o recém-nascido está assintomático."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-60869","number":"60869","sourceNumber":"60869","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em um recém-nascido com 48 horas de vida e diagnóstico de toxoplasmose congênita\ncomprovada, a fundoscopia mostra coriorretinite macular bilateral em atividade. O exame do liquor\ndemonstra uma hiperproteinorraquia. Qual seria o esquema terapêutico mais adequado para iniciar\ntratamento para esta criança?","options":{"A":"Espiramicina + corticosteroides.","B":"Sulfadiazina + pirimetamina + ácido fólico.","C":"Sulfadiazina + pirimetamina + ácido folínico.","D":"Sulfadiazina + pirimetamina + ácido folínico + corticosteroides.","E":"Espiramicina alternada de duas em duas semanas com sulfadiazina + corticosteroides."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-60887","number":"60887","sourceNumber":"60887","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação ao tratamento da toxoplasmose congênita, podemos afirmar que:","options":{"A":"Em criança com toxoplasmose congênita comprovada e em filhos de mulheres com\ntoxoplasmose aguda comprovada ou provável\ndurante a gestação, o recém-nascido deve ser\nsubmetido à avaliação clínica cuidadosa e investigação suplementar com hemograma completo,\nfundoscopia ocular e ultrassom transfontanela e, adicionalmente, deve-se realizar análise do liquor\ncefalorraquidiano (bioquímica e celularidade), tomografia computadorizada (sem a necessidade de\nuso de contraste radiológico), avaliação da função hepática e avaliação auditiva.","B":"Somente as crianças que apresentam sintomas como hepatoesplenomegalia, icterícia e\nplaquetopenia devem ser tratadas.","C":"Não há necessidade de avaliação de exame de fundo de olho, pois a coriorretinite na\ntoxoplasmose congênita é muito rara.","D":"Todas as crianças com toxoplasmose congênita comprovada devem receber tratamento por 6\nmeses consecutivos, independentemente da presença de sinais e/ou sintomas da doença.","E":"Se o recém-nascido for assintomático ao nascimento e com hemograma normal, mesmo que a\nmãe tenha diagnóstico de toxoplasmose aguda na gestação não precisa ser investigado e deve\nreceber alta hospitalar para acompanhamento em ambulatório de puericultura de baixo risco."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-60917","number":"60917","sourceNumber":"60917","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A icterícia constitui em um dos problemas mais frequentes no período neonatal e\ncorresponde à expressão clinica da\nhiperbilirrubinemia. Na prática, 98% dos recém-nascidos\napresentam níveis séricos de de bilirrubina indireta acima de 1mg/dl durante a primeira semana de\nvida, o que na maioria das vezes reflete a adaptação neonatal ao metabolismo da bulirrubina. É a\nchamada hiperbilirrubinemia fisiológica. Quanto ao diagnóstico da icterícia neonatal podemos\nafirmar:","options":{"A":"A icterícia fisiológica geralmente surge nas primeiras 24 horas de vida, em mães primíparas e\nalcançam niveis séricos maiores que 12 mg/dl.","B":"Presença de icterícia antes de 24 horas de vida e valores de bilirrubina total > 12 mg/dl,\nindependentemente da idade pós-natal, alerta para a investigação da causa.","C":"Pode-se avaliar clinicamente e afirmar que a icterícia é ''fisiológica'' se o recém-nascido\nestiver\ncom a boa sucção ao seio.","D":"Apenas a estimativa clínica é suficiente para avaliar os recém-nascidos com a icterícia neonatal,\nindependentemente da idade gestacional.","E":"Somente pela história clínica perinatal e familiar podemos averiguar o risco de um\nrecém-nascido desenvolver icterícia neonatal na primeira semana de vida."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-60931","number":"60931","sourceNumber":"60931","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A história clínica de recém-nascidos com icterícia neonatal permite detectar a presença\nde fatores epidemiológicos de risco associados\nao desenvolvimento de hiperbilirrubinemia\nsignificante na primeira semana de vida. Marque a alternativa CORRETA em relação aos fatores de\nrisco para o desenvolvimento de hiperbilirrubinemia significante em recém-nascidos > 35 semanas\nde idade gestacional:","options":{"A":"Icterícia após 48 horas de vida em recém-nascido a termo, que está com boa sucção ao seio\nmaterno.","B":"Idade gestacional de 35 semanas não constitui fator de risco independente para o\ndesenvolvimento de icterícia neonatal.","C":"Sexo feminino é um fator de risco para o desenvolvimento de icterícia neonatal,\nindependentemente do tipo sanguíneo do recém-nascido e da mãe.","D":"Recém-nascido com tipo sanguíneo O+, sendo a mãe A+, pode ter doença hemolítica por\nincompatibilidade ABO e desenvolver icterícia grave.","E":"Recém-nascido termo, com céfalo-hematoma e equimoses, sexo masculino, grupo Sg A+, sendo\na mãe O+, com história de um irmão que\nnecessitou tratamento com fototerapia."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-324671","number":"324671","sourceNumber":"324671","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Paciente, sexo feminino, nascida há 12 horas, apresentou, durante ultrassonografia\nmorfológica pré-natal, abaulamento em coluna\nvertebral lombar. Após o nascimento, foi identificada\npresença de protrusão sacular em região lombar medindo cerca de 10cm, coberta por membrana\nfina e avermelhada. A paciente também apresentava diminuição da mobilidade dos membros\ninferiores e retenção urinária. Determine a principal suspeita diagnóstica para o quadro clínico da\npaciente.","options":{"A":"Distúrbio de segmentação vertebral.","B":"Agenesia segmentar da coluna lombar.","C":"Mielomeningocele.","D":"Meningioma lombar."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-324672","number":"324672","sourceNumber":"324672","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Paciente, sexo feminino, nascida há 12 horas, apresentou, durante ultrassonografia\nmorfológica pré-natal, abaulamento em coluna\nvertebral lombar. Após o nascimento, foi identificada\npresença de protrusão sacular em região lombar medindo cerca de 10cm, coberta por membrana\nfina e avermelhada. A paciente também apresentava diminuição da mobilidade dos membros\ninferiores e retenção urinária. Indique o principal fator de risco para o surgimento da alteração\nencontrada na paciente.","options":{"A":"Trissomia cromossomial.","B":"Obesidade.","C":"Diabetes mellitus.","D":"Deficiência de ácido fólico."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-324673","number":"324673","sourceNumber":"324673","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Paciente, sexo feminino, nascida há 12 horas, apresentou, durante ultrassonografia\nmorfológica pré-natal, abaulamento em coluna\nvertebral lombar. Após o nascimento, foi identificada\npresença de protrusão sacular em região lombar medindo cerca de 10cm, coberta por membrana\nfina e avermelhada. A paciente também apresentava diminuição da mobilidade dos membros\ninferiores e retenção urinária. Indique a conduta cirúrgica mais adequada para essa paciente, caso\nnão seja possível o fechamento primário do defeito cutâneo.","options":{"A":"Deixar a área fechar por segunda intenção.","B":"Realizar enxerto de pele total.","C":"Confeccionar retalho local fasciocutâneo.","D":"Realizar colocação de expansor tecidual."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-284620","number":"284620","sourceNumber":"284620","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Menino, nascido de parto cirúrgico indicado por suspeita de descolamento prematuro\nda placenta, é assistido na sala de parto. A\nidade gestacional, aproximada, é de 37 semanas. A\ncriança é entregue ao pediatra, logo após o clampeamento do cordão umbilical. Ao primeiro minuto\nde vida, o bebê apresenta choro fraco, atitude fletida, movimenta-se sem muito vigor; está rosado e\ncom a frequência cardíaca de 106 bpm. Identifique a alternativa que informa a ordem correta de\nexecução dos procedimentos que compõem a assistência a essa criança.","options":{"A":"Posicionar a criança com a cabeça mais baixa do que o corpo; envolvê-la em campos estéreis e\nsecá-la; aspirar secreções de naso e orofaringe.","B":"Posicionar a criança com a cabeça mais baixa do que o corpo; aspirar secreções de naso e\norofaringe; envolvê-la em campos estéreis e secá-la.","C":"Envolver o recém-nascido em campos estéreis e secá-lo; posicioná-lo com a cabeça mais baixa\ndo que o corpo; aspirar secreções de naso e orofaringe.","D":"Envolver o recém-nascido em campos estéreis e secá-lo; aspirar secreções de naso e\norofaringe; posicioná-lo com a cabeça mais baixa do que o corpo."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-62894","number":"62894","sourceNumber":"62894","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN nascido a termo é encaminhado para o exame e acompanhamento neonatal de\nrotina. Antes da alta, foi feita pesquisa do\nreflexo vermelho (teste do reflexo de Bruckner ou teste do\nolhinho), cujo resultado pode ser visto na figura. (VER IMAGEM) A respeito do possível diagnóstico\napós o teste, é FALSO afirmar que:","options":{"A":"A catarata infantil é uma das principais causas de cegueira, passível de prevenção, e de visão\nsubnormal na infância. Essa condição aparece quando o cristalino apresenta uma opacificação que\npode ser total ou parcial, uni ou bilateral.","B":"O retinoblastoma é um tumor que se origina dos retinoblastos imaturos da retina neural, sendo o\ntumor maligno intraocular mais frequente encontrado em crianças.","C":"A retinopatia da prematuridade é uma doença vascular da retina que acomete recém-nascidos\npré-termos, principalmente aqueles que nasceram com\nmenos de 1.500 g e de 32 semanas de\nidade gestacional.","D":"A opacidade do cristalino pode ser decorrente de uma variedade de etiologias, podendo resultar\nde malformações oculares congênitas, de infecções\nintrauterinas (rubéola, citomegalovírus,\nvaricela, toxoplasmose).","E":"As apresentações clínicas mais frequentes da toxocaríase ocular são endoftalmite crônica,\nformação de granuloma no polo posterior ou\nformação de granuloma periférico, ocorrendo bilateral\ne, frequentemente, na forma congênita."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":["question_bank/media/medcurso/medcurso-pediatria-ped-1/62894.png"],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-62892","number":"62892","sourceNumber":"62892","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN nascido de parto cesáreo, pré-termo, baixo peso, pré-natal com duas consultas, a\ngenitora não fez os exames solicitados pelo obstetra e é usuária de álcool. Apresenta, ao nascer,\ndificuldade de sucção, opistótono, hiperexcitabilidade. Ao exame físico, nota-se fissura palpebral\npequena, nariz curto, filtro nasal hipoplásico com lábio superior fino, hipoplasia de maxilar,\nmicrocefalia e microftalmia. Das patologias relacionadas a seguir, a mais provável é:","options":{"A":"Síndrome alcoólica fetal.","B":"Síndrome de Turner.","C":"Rubéola congênita.","D":"SIDA/AIDS.","E":"Herpes congênito."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-62888","number":"62888","sourceNumber":"62888","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN, nascido pré-termo limítrofe, APGAR de 9 e 10 no primeiro e quinto minuto,\nrespectivamente, apresenta taquipneia com quatro\nhoras de vida. Ao exame, dispneico, com FR de\n98 inc/min, retração costal moderada, saturação de 0² 98%. RX de tórax com imagem de infiltrado\nlinear a partir dos hilos, silhueta cardíaca normal. O diagnóstico mais provável é de:","options":{"A":"pneumonia aspirativa.","B":"taquipneia transitória do RN.","C":"enfisema pulmonar congênito.","D":"doença de membrana hialina.","E":"hipertensão pulmonar persistente."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-281861","number":"281861","sourceNumber":"281861","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa incorreta em relação aos benefícios do CPAP.","options":{"A":"Diminui o trabalho respiratório e consumo de oxigênio.","B":"Não permite uma respiração espontânea.","C":"Melhora a função diafragmática.","D":"Diminui o edema alveolar."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-281886","number":"281886","sourceNumber":"281886","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Além do gonococo, dos patógenos listados, o mais provável em diagnóstico de oftalmia\nem recém-nascido é:","options":{"A":"Gardnerela.","B":"Clamídia.","C":"Tricomonas.","D":"Estreptococo beta hemolítico do grupo B."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-215592","number":"215592","sourceNumber":"215592","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Criança apresenta na primeira dentição os chamados ?Dentes de Hutchinson?, que são\nentalhes semilunares na borda dos mesmos. Provavelmente o caso se refere a:","options":{"A":"Sífilis congênita.","B":"Rubéola congênita.","C":"Varicela congênita.","D":"Infecção por citomegalovírus na gestação."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-181168","number":"181168","sourceNumber":"181168","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa INCORRETA:","options":{"A":"Em pacientes com sinais clínicos de hipertensão intracraniana, sinais neurológicos focais,\ninstabilidade hemodinâmica ou ventilatória, imunodeficiência, diminuição do sensório (escala de\ncoma de Glasgow < 13 ou queda no escore > 2), sugere-se a realização de tomografia de crânio\nantes da punção lombar.","B":"Recomenda-se em todos os pacientes com suspeita de encefalite, a pesquisa de PCR no líquor\npara Herpes Vírus tipo 1 e 2, Varicela Zoster e Enterovírus, o que permitirá a identificação da\nmaioria dos casos conhecidos.","C":"A pesquisa de HIV deve ser considerada somente em crianças com fatores de risco para HIV,\ntais como exposição vertical ao HIV.","D":"Quando o agente etiológico é a Varicela Zoster, deve-se administrar aciclovir e considerar o uso\nde corticóide em casos de vasculopatia."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-157582","number":"157582","sourceNumber":"157582","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre atresia da via biliar, assinale a alternativa ERRADA.","options":{"A":"Os principais achados histopatológicos são espaço porta expandido por fibrose e edema,\ninfiltrado inflamatório com predomínio de\nneutrófilos, neoformação ductal, plugs biliares nos ductos\nneoformados.","B":"Quadro clínico caracterizado por recém-nascidos previamente hígidos, sem\nhepatoesplenomegalia, com fezes coradas e sem\ncolúria. Após 8 a 12 semanas o fígado já esta\naumentado, com sinais de fibrose e/ou cirrose.","C":"A mais grave complicação é a colangite, podendo levar à destruição completa das vias biliares.\n\nCaracteriza-se por febre, dor à palpação do fígado, aumento das bilirrubinas, para a diminuição do\nfluxo biliar, elevação das enzimas hepáticas.","D":"O tratamento cirúrgico de escolha é a portoenterostomia de Kasai. Piores resultados estão\nassociados à idade menor que 12 semanas, porto hepatis tipo I, área de secção do porta hepatis\ncontendo dúctulos biliares."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-157609","number":"157609","sourceNumber":"157609","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual é a anomalia não associada à polidrâmnio?","options":{"A":"Atresia duodenal.","B":"Atresia de esôfago.","C":"Agenesia renal.","D":"Diabetes gestacional."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-157614","number":"157614","sourceNumber":"157614","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual deve ser o antibiótico de escolha para paciente com menos de 1 mês na presença\nde infecção por Estreptococo do grupo B?","options":{"A":"Vancomicina + cefepime.","B":"Ceftriaxone + ampicilina.","C":"Ampicilina + vancomicina.","D":"Ampicilina + gentamicina."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-157708","number":"157708","sourceNumber":"157708","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa que NÃO representa uma estratégia recomendada para prevenir\ninfecção fúngica em recém-nascidos.","options":{"A":"Usar fluconazol EV para recém-nascidos com menos de 27 semanas de gestação.","B":"Usar bloqueadores de bomba de próton para evitar gastrite.","C":"Restringir o uso de antibióticos de largo espectro.","D":"Usar dexametasona apenas quando há lesão pulmonar grave."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-139755","number":"139755","sourceNumber":"139755","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Ao avaliar uma gestante em trabalho de parto a termo, foi observado que, vinte\nsegundos após o início da contração uterina, a\nfrequência cardíaca do feto teve uma queda\nsignificativa e persistiu após seu término. Diante disso, podemos concluir que o feto apresenta:","options":{"A":"hidropisia generalizada.","B":"imaturidade cardíaca.","C":"asfixia grave.","D":"compressão cefálica."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-139794","number":"139794","sourceNumber":"139794","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"No sinal de Galeazzi, observa-se uma diferença de nível dos joelhos com a criança\ndeitada e com os membros fletidos. Aponte a\nalternativa que representa a patologia em que esse\nsinal clínico é encontrado.","options":{"A":"Luxação do quadril.","B":"Artrite séptica do joelho.","C":"Osteocondrite de calcâneo.","D":"Cifose do adolescente."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-111930","number":"111930","sourceNumber":"111930","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, com peso ao nascer de 3.500 g, iniciou icterícia com 16 horas\nde vida, sem apresentar sintomas ou outros\nachados físicos relevantes. A tipagem sanguínea\nmaterna é O negativo e a do RN, A positivo. Coombs direto: negativo. Qual é a hipótese\ndiagnóstica MAIS provável para esse caso?","options":{"A":"Icterícia fisiológica.","B":"Doença hemolítica pelos sistemas RH e ABO.","C":"Doença hemolítica pelo sistema ABO.","D":"Deficiência de glicose-6-fosfato desidrogenase."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-111935","number":"111935","sourceNumber":"111935","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN pré-termo tardio, com IG 36 semanas e 5 dias, peso de nascimento 2.580 g, recebe\nalta com 72 horas de vida, com aleitamento\nmaterno exclusivo e pesando 2.300 g, com bons\ncontroles de dextro. Qual é a sua orientação na alta?","options":{"A":"Retorno em 48 horas no consultório para reavaliação.","B":"Retorno em 1 semana no consultório para reavaliação.","C":"Retorno para reavaliação quando completar 15 dias de vida.","D":"Retorno para reavaliação após tomar vacina da Hepatite B."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-111829","number":"111829","sourceNumber":"111829","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"São vantagens do aleitamento conjunto, EXCETO:","options":{"A":"Aproximação entre mãe e filho e fortalecimento de laços afetivos entre ambos.","B":"Redução do risco de infecção hospitalar, devido à colonização de germes maternos e não\nhospitalares.","C":"Facilitar o relacionamento da mãe e filho em casa, tendo apoio da equipe de saúde, dando mais\nsegurança à mãe.","D":"Aprender sozinha ou com outras mães a cuidar dos filhos."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-350850","number":"350850","sourceNumber":"350850","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RNPT tardio - PIG - nasceu de parto vaginal em boas condições, colocado em contato\npele a pele e assegurada amamentação na\nprimeira hora de vida tendo apresentado boa pega e\nsugado de forma efetiva o seio materno. Atualmente, com 2 horas de vida, ao exame físico,\napresenta boa atividade e reatividade, presença de acrocianose e uma temperatura axilar = 36ºC.\nO nível glicêmico foi aferido por meio das fitas reagentes de glicose cujo resultado foi 28 mg/dl. O\nRN foi novamente colocado ao seio materno e a mãe foi orientada sobre amamentação. Uma nova\naferição de glicemia capilar foi programada para após 1 hora. Como prevenir novos episódios de\nhipoglicemia para esse RN?","options":{"A":"Evitar falsa aferição de hipoglicemia higienizando o local de punção com álcool.","B":"Prover complementação regular da dieta com fórmula para RNPT a cada 3 horas.","C":"Desenvolver estratégias para esse RN corrigir a sua condição de hipotermia.","D":"Transferir para unidade neonatal para qualificar o monitoramento da glicemia."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-350823","number":"350823","sourceNumber":"350823","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Durante a coleta da anamnese materna na sala de parto é identificado que uma mãe\nteve Sífilis durante a gestação. Parturiente e parceiro foram adequadamente tratados, de acordo\ncom o registrado no cartão pré-natal. O tratamento terminou aproximadamente 40 dias antes do\nparto. Qual a conduta inicial com o recém-nascido em relação a necessidade de testagem para\nSífilis?","options":{"A":"Coletar teste não treponemico da criança se essa apresentar alterações ao exame físico.","B":"Não existe necessidade de testagem da criança caso o teste rápido materno seja negativo.","C":"Realizar coleta de teste treponemico da criança por meio de sangue do cordão umbilical.","D":"Testagem simultaneamente da mãe e criança com teste não treponemico em sangue periférico."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-350818","number":"350818","sourceNumber":"350818","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A mãe de um bebê de 5 semanas de vida chega à Puericultura relatando que as fezes\ndo filho estão apresentando cores cada vez\nmais claras há cerca de 10 dias. Qual a interpretação\ncorreta para esse evento?","options":{"A":"Se as fezes estiverem brancas logo após as mamadas, esse aspecto é normal.","B":"Se a criança estiver bem, se não apresentar nenhum outro sintoma, esse aspecto é normal.","C":"Se as fezes estão claras, permanecendo quase brancas ou cinzentas, pode significar alguma\ndoença.","D":"Se a criança estiver evacuando poucas vezes ao dia com cores claras, pode significar\nnormalidade."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-321317","number":"321317","sourceNumber":"321317","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, 36 horas de vida, masculino, em aleitamento materno\nexclusivo, com diurese e evacuação, apresenta\no seguinte achado na fralda visto durante o exame\nfísico sem alterações.Conferir figura correspondente com melhor resolução no anexo (FIGURA\n4)Qual a melhor conduta?","options":{"A":"Achado habitual, seguir rotina do alojamento conjunto.","B":"Iniciar antibiótico e solicitar exames séricos e urinários no alojamento conjunto.","C":"Suspender o aleitamento materno e prescrever fórmula isenta de proteína de leite de vaca.","D":"Prescrever vitamina K e solicitar hemograma e coagulograma, transferindo o bebê para berçário."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-292830","number":"292830","sourceNumber":"292830","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Diante de um recém-nascido conduzido à mesa de reanimação, deve-se iniciar os\npassos da estabilização na sequência\nadequada, com duração de no máximo 30 segundos. Qual\ndas opções abaixo apresenta a sequência correta?","options":{"A":"Prover calor, fazer estímulo táctil, aspirar boca e narinas (se necessário) e enxugar.","B":"Fazer estimulação táctil, posicionar a cabeça em leve extensão, aspirar boca e narinas e secar.","C":"Prover calor, posicionar a cabeça em leve extensão, aspirar boca e narinas (se necessário) e\nsecar.","D":"Enxugar e aquecer, posicionar a cabeça em extensão, aspirar boca e narinas (se necessário) e\nestimular."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-259731","number":"259731","sourceNumber":"259731","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido a termo, com peso de nascimento de 3100 g e boas condições de\nvitalidade, encontra-se no alojamento conjunto com sua mãe, que relata que o bebê é tranquilo e\npega pouco o seio. Nasceu de parto vaginal, sendo realizada assistência adequada em sala de\nparto, com clampeamento tardio de cordão. Está com 72 horas de vida, com duas diureses no dia\nanterior e eliminação de mecônio uma vez. Ao exame, encontra-se ictérico até o umbigo. Ao ser\nsolicitado exame laboratorial, observa-se bilirrubina total de 9 mg/dl, com 72 horas de vida. Mãe\n0+/RN 0+. O resultado foi analisado no Nomograma de Bhutani. Qual a melhor conduta para este\nrecém-nascido?","options":{"A":"Fototerapia no Alojamento Conjunto.","B":"Fototerapia na Unidade de Cuidados Intermediários.","C":"Exsanguineo transfusão na Unidade de Cuidados Intensivos.","D":"Alta hospitalar após orientação sobre amamentação e retorno precoce."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-259732","number":"259732","sourceNumber":"259732","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O pediatra de plantão, em uma grande maternidade, é comunicado de um parto\ncesareano de urgência por sofrimento fetal.\nApós checar no centro cirúrgico, o material de\nreanimação, local de recepção e a fonte de oxigênio, recebe o recém-nascido. De acordo com o\nFluxograma da reanimação neonatal do Programa de Reanimação Neonatal da Sociedade\nBrasileira de Pediatria, quais perguntas iniciais o pediatra deve fazer para orientar as\nprovidências\nseguintes?","options":{"A":"Cianose? Reativo? Respirando ou chorando?","B":"Chorando forte? Cianose? Saturação de oxigênio acima de 92%?","C":"Gestação a termo? Respirando ou chorando? Tônus muscular em flexão?","D":"Frequência cardíaca acima de 100 bpm? Saturação de oxigênio acima de 92%? Chorando?"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-234052","number":"234052","sourceNumber":"234052","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Os recém-nascidos que, ao nascimento, não iniciam movimentos respiratórios regulares\ne/ou aqueles cujo tônus muscular está flácido\nprecisam ser conduzidos à mesa de reanimação.\n\nNesses casos, quais os passos iniciais indicados em um correto procedimento de reanimação?","options":{"A":"Posicionar a cabeça em extensão, aspirar boca e narinas, entubar e ventilar. Esses passos\ndevem ser executados em, no máximo, 60\nsegundos.","B":"Posicionar a cabeça em leve extensão, aspirar boca e narinas, e ventilar com ambu e máscara.\n\nEsses passos devem ser executados nos primeiros 30 segundos.","C":"Prover calor, posicionar a cabeça em leve extensão, aspirar boca e narinas, se necessário, e\nsecar o paciente. Esses passos devem ser executados em, no máximo, 30 segundos.","D":"Aspirar boca e narinas, posicionar a cabeça em leve extensão, prover calor e ventilar com ambu\ne máscara, além de massagem cardíaca. Esses\npassos devem ser executados nos primeiros 60\nsegundos."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-234053","number":"234053","sourceNumber":"234053","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido limítrofe (36 semanas), Apgar 9 e 9, mãe O+, encontra-se no\nalojamento conjunto com boa pega ao seio.\nNasceu de parto vaginal com clampeamento oportuno\nde cordão umbilical. Está com 22 horas de vida, com boa diurese e ainda com pouca eliminação de\nmecônio. Ao exame, encontra-se ictérico até zona III de Kramer. Qual o fator de alerta que pode\nestar associado a hiperbilirrubinemia severa?","options":{"A":"Clampeamento precoce do cordão.","B":"Pouca eliminação de mecônio.","C":"Icterícia nas primeiras 24 horas.","D":"Icterícia pelo leite materno."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-199720","number":"199720","sourceNumber":"199720","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"No alojamento conjunto, encontra-se um recém-nascido a termo assintomático cuja\nmãe realizou tratamento adequado para sífilis no 7º mês de gestação. O VDRL em amostra de\nsangue periférico do bebê é negativo. Segundo o Ministério da Saúde, na impossibilidade de\ngarantir o seguimento clínicolaboratorial, qual a melhor conduta para este RN?","options":{"A":"Considerar o caso resolvido.","B":"Tratar com penicilina G benzatina IM em dose única.","C":"Investigar e tratar com penicilina G benzatina IM em dose única.","D":"Investigar e tratar com penicilina cristalina ou procaína por 10 dias."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-199667","number":"199667","sourceNumber":"199667","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Lactente de oito meses de idade com história de sibilância recorrente, que piora nos\nquadros de infecções de vias aéreas. Mãe refere que criança tem sintomas contínuos desde o\nperíodo neonatal. Nasceu de parto cesáreo, pré-termo e fez uso de oxigenoterapia. Nega outras\nalterações, internamentos e alergias na família. Qual o diagnóstico mais provável?","options":{"A":"Displasia broncopulmonar.","B":"Imunodeficiência primária.","C":"Fibrose cística.","D":"Asma atópica."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-199700","number":"199700","sourceNumber":"199700","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido com 12 dias de vida encontra-se na UTI desde o nascimento por\nprematuridade. Apresenta-se com hipotermia,\napneia, resíduo gástrico positivo, pele rendilhada e\nhipoatividade. Realizada punção lombar que evidenciou liquor com baixos níveis de glicose,\nhiperproteinorraquia e pleocitose com predomínio de neutrófilos. Qual(is) o(s) antibiótico de\neleição,\ndentre os abaixo citados?","options":{"A":"Cefepime.","B":"Ampicilina.","C":"Metronidazol.","D":"Piperacilina + tazobactam."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-172957","number":"172957","sourceNumber":"172957","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido, segundo filho de uma mulher com tipagem sanguínea O negativo\ncom Coombs indireto positivo, apresenta os\nseguintes resultados de exames no sangue de cordão:\ntipagem sanguínea O positivo, coombs direto positivo, reticulócitos 8%, bilirrubina indireta de 4,4\nmg/dl e hemoglobina de 12,5 g/dl. Qual dos dados indicaria a realização de exsanguineotransfusão\npara este bebê?","options":{"A":"Reticulócitos aumentados no sangue de cordão.","B":"Hemoglobina do sangue de cordão de 12,5 g/dl.","C":"Bilirrubina indireta de sangue de cordão de 4,4 mg/dl.","D":"O coombs indireto da mãe e direto do recém-nascido positivos."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-172967","number":"172967","sourceNumber":"172967","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma agente comunitária de saúde apresentou sífilis adequadamente tratada na\ngestação anterior há 2 anos, quando ela e o\nparceiro fizeram uso de Penicilina benzatina em 3\ndoses de 2.400.000, com intervalo semanal. Atualmente, no 9º mês de uma segunda gestação, ela\ne o esposo apresentam VDRL de 1:1 e o teste rápido da sala de parto foi positivo. Compreendendo\nque será possível fazer acompanhamento do binômio mãe-bebê de forma adequada e que os\nexames do RN logo após o nascimento evidenciaram o VDRL sérico de 1:1, com os demais\nnormais, qual a melhor conduta para este RN?","options":{"A":"Penicilina benzatina - 1 dose de 600.000 UI.","B":"Seguimento clínico e laboratorial da criança.","C":"Penicilina procaína 50.000 UI/kg/dia por 10 dias.","D":"Penicilina cristalina 100.000 UI/kg/dia por 7 dias."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-172977","number":"172977","sourceNumber":"172977","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Logo após o nascimento, um recém-nascido de 35 semanas de idade gestacional e\npeso 2.500 g, encontra-se com batimento de asa\nde nariz, gemente, com retração esternal\nimportante e cianose de extremidades. A frequência respiratória é de 64 irpm e saturação de\noxigênio de 94%. Qual é a melhor conduta para o bebê, dentre as abaixo citadas?","options":{"A":"Aquecer, colocar no capacete (hood) com F1O2 de 60% e reavaliar com 2 horas de vida, na sala\nde parto.","B":"Aquecer em berço de calor radiante em ar ambiente e reavaliar com 2 horas de vida, na sala de\nparto.","C":"Iniciar o CPAP nasal precoce com PEEP de 5 cm H2O já na sala de parto e durante o\ntransporte.","D":"Proceder a intubação orotraqueal e iniciar a ventilação com pressão positiva."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-150879","number":"150879","sourceNumber":"150879","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN a termo, filho de mãe com sífilis não tratada na gestação, está no alojamento\nconjunto. Foi afastada neurossífilis e\nconsiderando que não está disponível a penicilina cristalina ou\nprocaína, qual a melhor conduta para esse recém-nascido, dentre as abaixo citadas?","options":{"A":"Cefepima por 7 dias.","B":"Cefepima por 10 dias.","C":"Ceftriaxona por 7 dias.","D":"Ceftriaxona por 10 dias."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-150884","number":"150884","sourceNumber":"150884","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, peso de 3.400 g, pré-natal sem intercorrências, boas\ncondições de nascimento, tipagem sanguínea O\nnegativo, em aleitamento materno exclusivo, com\nboa pega ao seio e eliminações fisiológicas, apresenta icterícia percebida com 60 horas de vida,\nzona I de Kramer. Qual a melhor conduta para esse recém-nascido?","options":{"A":"Alta hospitalar com retorno em 72 horas para reavaliação clínica.","B":"Permanência hospitalar por mais 12 a 24 horas para observar evolução da icterícia e posterior\nsolicitação de exames, caso evolua.","C":"Dosagem sérica de bilirrubina total e frações, Coombs direto, reticulócitos, hemograma completo\ne iniciar fototerapia no alojamento conjunto.","D":"Dosagem sérica de bilirrubina total e frações, Coombs direto, hemograma completo,\nreticulócitos, protelando a alta hospitalar até checagem dos resultados."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-126952","number":"126952","sourceNumber":"126952","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Você avalia a vitalidade imediata de um recém-nascido na sala de parto e identifica as\nseguintes situações: RN de termo, sem mecônio, respirando e chorando adequadamente, com bom\ntônus muscular. Logo em seguida, quais dos cuidados abaixo devem ser tomados?","options":{"A":"Prevenção de sangramentos por deficiência de fatores de coagulação.","B":"Prevenção da oftalmia gonocócica pelo método de Credé para RN de parto vaginal.","C":"Laqueadura do cordão umbilical; verificar a presença de duas artérias e de uma veia umbilical.","D":"Realização de exame físico detalhado, incluindo peso, comprimento e os perímetros cefálico,\ntorácico e abdominal."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-126984","number":"126984","sourceNumber":"126984","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Joana nasceu de parto vaginal a termo com 36 semanas, Apgar 8/9 e peso de 2300g. A\nmãe é moradora de rua em situação de vulnerabilidade social. Na visita no Alojamento conjunto\ndetectou-se icterícia, hepatoesplenomegalia e dor ao manuseio. Que exames são imprescindíveis\npara reforçar esclarecimento diagnóstico?","options":{"A":"VDRL da mãe e do recém-nascido, raio-x de ossos longos, punção lombar e fundo de olho.","B":"Hemograma completo, bilirrubinas, teste rápido para HIV e avaliação neurocomportamental.","C":"Bilirrubinas séricas, sorologia para citomegalovírus, ultrassonografia abdominal e tomografia\ncomputadorizada.","D":"Sorologia da mãe e do recém-nascido para toxoplasmose, raio-x de ombro, ultrassonografia\ntransfontanelar e fundo de olho."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-127003","number":"127003","sourceNumber":"127003","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A icterícia constitui-se em um dos problemas mais frequentes no período neonatal e\ncorresponde à expressão clínica da hiperbilirrubinemia. A hiperbilirrubinemia, na primeira semana\nde vida, é encontrada tanto no recém-nascido a termo como no prematuro. Diante de um prematuro\nde 36 semanas de idade gestacional, existem fatores epidemiológicos que orientam o\nneonatologista para uma investigação clínica e laboratorial. Quais das situações abaixo significam\nalta probabilidade de a icterícia ter origem patológica?","options":{"A":"Icterícia com início antes de 24-36 horas de vida, independentemente da idade pós-natal.","B":"Icterícia com início após 24 horas de vida, com pico no terceiro dia de vida.","C":"Icterícia em recém-nascidos com perda elevada de peso.","D":"Icterícia na presença de bossa serossanguínea."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-102169","number":"102169","sourceNumber":"102169","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Lactente, com 28 dias de vida, é levado ao pediatra com história de icterícia desde o\nnascimento. Pais informam que seu filho encontra-se em aleitamento materno exclusivo e em bom\nestado geral. As fezes da criança podem ser vistas na foto abaixo. (VER IMAGEM) Avaliação\nlaboratorial realizada há 3 dias revelou bilirrubina total de 9 mg/dl, com indireta de 5,5 mg/dl.\n\nNascera a termo e com peso adequado para a idade gestacional. A melhor conduta para essa\ncriança, no momento, é:","options":{"A":"Referenciar com urgência a serviço terciário para investigação de colestase neonatal.","B":"Encaminhar para intervenção cirúrgica em vias biliares sob risco de necessidade de transplante\nhepático.","C":"Colher exames de função hepática e sorologias para hepatites, com retorno para reavaliação\napós 1 mês.","D":"Suspender o leite materno, de acordo com as orientações do Ministério da Saúde constantes na\ncaderneta de saúde da criança."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-102176","number":"102176","sourceNumber":"102176","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante comparece à consulta de pré-natal, com 32 semanas de idade gestacional,\ntendo o diagnóstico de sífilis confirmado.\nInicia tratamento com penicilina benzatina, 2.400.000 UI\nem três doses (1 dose/semana), juntamente com o parceiro, com comprovação. Com 35 semanas,\ndá à luz um recém-nascido que se encontra assintomático. São solicitados exames para o bebê.\n\nCom esses dados, dentre as abaixo citadas, qual a melhor conduta para este recém-nascido?","options":{"A":"Penicilina procaína por 10 dias.","B":"Penicilina benzatina dose única.","C":"Penicilina cristalina por 10 dias.","D":"Observação e seguimento ambulatorial."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-102087","number":"102087","sourceNumber":"102087","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, por cesárea eletiva devido à malformação congênita, é\nsubmetido a procedimento cirúrgico nas primeiras horas de vida. Com 44 horas de idade, evolui\ncom quadro séptico. O pré-natal foi sem intercorrências, a bolsa foi rota no ato e a mãe estava\nassintomática no momento do parto. Qual a melhor conduta para decidir a antibioticoterapia a ser\nusada?","options":{"A":"Considerar infecção neonatal congênita.","B":"Considerar infecção neonatal tardia de provável etiologia hospitalar.","C":"Considerar infecção neonatal precoce de provável etiologia materna.","D":"Considerar infecção neonatal precoce de provável etiologia hospitalar."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-102093","number":"102093","sourceNumber":"102093","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de 36 semanas apresenta desconforto respiratório precoce, na primeira\nhora de vida. O BSA (Boletim de\nSilverman-Andersen) é igual a 3 e a frequência respiratória é de\n64 irpm, com PaO2 de 58 mmHg e PaCO2 = 44 mmHg. Reavaliado com 6 horas de vida,\n\nobserva-se BSA = 7 e frequência respiratória de 62 irpm, com necessidade crescente de aumento\nna fração inspirada de oxigênio, e dados da\ngasometria mostram PaO2 = 48 mmHg e PaCO2 = 54\nmmHg. Qual a hipótese diagnóstica mais provável diante dessa situação?","options":{"A":"Síndrome do desconforto respiratório.","B":"Síndrome adaptativa do recém-nascido.","C":"Taquipneia transitória do recém-nascido.","D":"Persistência do padrão fetal de circulação."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-102131","number":"102131","sourceNumber":"102131","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido, filho de mãe HIV positiva assintomática que fez adequada profilaxia no\npré-natal e no parto, nasce de parto cesáreo, eletivo, em boas condições, sendo feitas as medidas\npreconizadas para diminuição de risco da transmissão vertical do vírus, incluindo a profilaxia com\ndroga antirretroviral. Antes da alta hospitalar, foram solicitados os seguintes exames: hemograma\ncompleto, sorologias TORCHS, anti-HIV, HTLV-1/2, glicemia e provas de função hepática. Que\nexames adicionais devem ser solicitados?","options":{"A":"Nenhum.","B":"CD4/CD8.","C":"Carga viral.","D":"Citobioquímica do liquor."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-102164","number":"102164","sourceNumber":"102164","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo com boas condições ao nascer, primeiro filho, peso de\nnascimento de 3200g, 5º dia de vida, apresenta-se com icterícia (Zona IV), que se iniciou no\nterceiro dia de vida. O peso atual é de 2920g e está em aleitamento materno exclusivo, com\nmamadas rápidas e frequentes. Eliminações presentes.Tipagem sanguínea do RN é O positivo,\ncom Coombs direto negativo.Tipagem sanguínea da mãe é A negativo, com Coombs indireto\nnegativo. Qual a hipótese mais provável?","options":{"A":"Incompatibilidade sanguínea mãe-RN.","B":"Síndrome da icterícia pelo leite materno.","C":"Deficiência de glicose-6 fosfato desidrogenase.","D":"Icterícia por oferta inadequada do leite materno."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81231","number":"81231","sourceNumber":"81231","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Durante a avaliação de uma paciente com quadro de miopatia e acidose láctica, o\nmédico obtém a seguinte história familiar: a irmã, o irmão e a mãe são afetados. A paciente não\ntem outros irmãos. A avó materna e seus dois tios maternos têm a mesma doença, porém suas\nduas primas maternas são saudáveis. O seu pai e a ascendência genealógica dele não têm a\ndoença. Baseado na clínica e na história familiar dessa paciente, qual o tipo de herança mais\nprovável?","options":{"A":"Ligada ao X.","B":"Mitocondrial.","C":"Autossômica recessiva.","D":"Autossômica dominante."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81245","number":"81245","sourceNumber":"81245","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Criança com 30 dias de vida comparece à consulta e evidencia-se teste do pezinho\nalterado (positivo) para hipotireoidismo. Qual a\nCORRETA abordagem clínica para essa criança?","options":{"A":"Solicitar dosagens séricas de TSH e T4 livre.","B":"Repetir o teste do pezinho antes de novos exames.","C":"Iniciar tratamento e referenciar para centro especializado.","D":"Solicitar dosagem do T4 livre em amostra de papel de filtro."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81258","number":"81258","sourceNumber":"81258","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Ao avaliar a alta hospitalar de um recém-nascido de 38 semanas com tipagem\nsanguínea ?O negativo?, em adequado\naleitamento materno exclusivo, eliminações fisiológicas,\nobserva-se icterícia neonatal zona II de Kramer, sendo coletado bilirrubina sérica com 48 horas de\nvida com o seguinte resultado: BT = 9,0 mg/dl, com BI de 8,3 mg/dl. Procede-se a análise do risco\nconforme o nomograma de Bhutani. (VER IMAGEM). Não há história de icterícia em irmãos. Com\nrelação à icterícia apresentada pelo recém-nascido, qual a conduta médica?","options":{"A":"Iniciar fototerapia em alojamento conjunto.","B":"Alta hospitalar com retorno em 72 horas para reavaliação.","C":"Postergar alta hospitalar, repetir dosagem de bilirrubinas com 72 horas de vida.","D":"Postergar alta hospitalar, com observação até o 5° dia de vida quando ocorre o pico de\nhiperbilirrubinemia."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81272","number":"81272","sourceNumber":"81272","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, peso de 3 kg, filho de mãe com exame de VDRL positivo 1:16\nno último trimestre da gravidez. O tratamento\nfoi iniciado no último mês de gestação, quando ela e\no parceiro trataram-se com 3 doses de penicilina benzatina 2.400.000 UI. O recém-nascido está\nassintomático. Qual o melhor critério em que os profissionais de saúde devem se basear para\ndeterminar se esse recém-nascido possui risco de ser portador de sífilis congênita?","options":{"A":"História materna.","B":"VDRL positivo no sangue do recém-nascido.","C":"Aparecimento de sintomas clínicos no recém-nascido.","D":"Testes treponêmicos positivos no sangue do recém-nascido."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81283","number":"81283","sourceNumber":"81283","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, peso de nascimento de 3000 g, Apgar 9 no primeiro e no\nquinto minutos de vida, encontra-se com 48\nhoras de vida no alojamento conjunto, em aleitamento\nmaterno exclusivo, apresentando temperatura axilar de 37,8°C. A mãe é primípara, está\nassintomática, fez pré-natal sem nenhuma intercorrência clínica. Parto normal, com tempo de bolsa\nrota de 1 hora. O peso do recém-nascido, neste momento, é de 2.720 g e o exame físico é normal,\nexceto por uma discreta irritabilidade do bebê. O exame que melhor confirmaria a principal hipótese\ndiagnóstica para essa distermia é:","options":{"A":"Hemocultura.","B":"Hemograma completo.","C":"Dosagem sérica de sódio.","D":"Citobioquímica do liquor."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81230","number":"81230","sourceNumber":"81230","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN de 36 semanas apresenta desconforto respiratório precoce, com gemência audível\ncom estetoscópio, com leve batimento de asa de nariz, tiragem intercostal, sendo colocado em\nCPAP nasal com progressiva necessidade de aumento de fração inspirada de oxigênio. A\nradiografia de tórax no leito com 6 horas de vida é mostrada a seguir. (VER IMAGEM). Qual a\nconduta que melhor beneficiaria o recém-nascido, ocasionando menos riscos, dentre as abaixo\ncitadas?","options":{"A":"Diurético de alça.","B":"Corticoide sistêmico.","C":"Ventilação mecânica.","D":"Surfactante exógeno."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-81277","number":"81277","sourceNumber":"81277","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Nasce RN a termo, peso de 3 kg, com boa vitalidade, filho de mãe com HIV que fez\nadequada profilaxia no pré-natal e no parto.\nFoi adequadamente recepcionado ao nascer, suspensa\na amamentação e iniciado AZT nas primeiras 2 horas de vida. Foi notificado para vigilância\nepidemiológica como criança exposta ao HIV. Qual a melhor conduta a seguir para esse RN antes\nda alta hospitalar, segundo as diretrizes do Ministério da Saúde?","options":{"A":"Solicitar hemograma completo, provas de função hepática, sorologias TORCHS e glicemia.","B":"Iniciar nevirapina, solicitar hemograma completo, provas de função hepática e sorologias\nTORCHS.","C":"Solicitar hemograma completo, provas de função hepática, sorologias TORCHS, carga viral e\nCD4/CD8.","D":"Iniciar nevirapina, solicitar hemograma completo, provas de função hepática, sorologias, carga\nviral e CD4/CD8."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-65735","number":"65735","sourceNumber":"65735","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido prematuro, oriundo de inadequadas condições de parto e de\nnascimento, apresenta, nas primeiras 48 horas de\nvida, os seguintes sinais clínicos: instabilidade\ntérmica, dificuldade respiratória, hipotonia, irritabilidade e letargia, manifestações\ngastrointestinais,\nicterícia e palidez cutânea. Qual o diagnóstico etiológico mais provável?","options":{"A":"Sepse por Parvovírus.","B":"Sepse por Candida albicans.","C":"Sepse por Escherichia coli.","D":"Sepse por Staphylococcus aureus.","E":"Sepse por Pseudomonas aeruginosa."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-65741","number":"65741","sourceNumber":"65741","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Médico diarista atende um recém-nascido prematuro (Idade gestacional = 31 semanas;\npeso = 1430 gramas), sem intercorrências\nno trabalho de parto vaginal, que apresenta, nas\nprimeiras horas de vida, sinais de aumento do trabalho respiratório. A avaliação é que se trata de\nSíndrome do Desconforto Respiratório. Que medidas terapêuticas apresentam potencial para\nmodificar tal síndrome?","options":{"A":"Antibiótico precoce e óxido nítrico inalatório.","B":"Assistência ventilatória precoce e surfactante exógeno.","C":"Assistência ventilatória precoce, antibiótico precoce e prostaglandina E1.","D":"Antibiótico precoce, assistência ventilatória precoce e surfactante exógeno.","E":"Corticoide antenatal, assistência ventilatória precoce e surfactante exógeno."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-141622","number":"141622","sourceNumber":"141622","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A icterícia constitui-se em um dos problemas mais frequentes no período\nneonatal, motivo pelo qual é necessário saber\nquando a icterícia é fisiológica ou não\nfisiológica. Assinale a opção que indica uma situação na qual a icterícia tem grande probabilidade\nde origem patológica.","options":{"A":"Icterícia visível nas primeiras 24 horas de vida.","B":"Antecedente de irmão que apresentou icterícia.","C":"Bilirrubina indireta que aumenta mais do que 2 mg/dl em 24 horas.","D":"Icterícia em filho de mãe diabética com qualquer época de aparecimento."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-141621","number":"141621","sourceNumber":"141621","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a assertiva que constitui indicação de ventilação com pressão positiva com\nbalão auto-inflável na reanimação de recém-nascidos em sala de parto.","options":{"A":"Respiração irregular e frequência cardíaca menor que 90 bpm.","B":"Apneia, respiração irregular e/ou frequência cardíaca menor do 100 bpm.","C":"Apneia, respiração irregular e/ou frequência cardíaca menor que 120 bpm.","D":"Apneia, respiração irregular e/ou frequência cardíaca menor que 140 bpm."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-141603","number":"141603","sourceNumber":"141603","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Para que a criança tenha uma boa linguagem oral é preciso que ela tenha uma boa\naudição. Com relação a importância da avaliação auditiva, é correto afirmar:","options":{"A":"A perda auditiva decorrente de otite média recorrente, não é prevalente na infância.","B":"O teste da orelhinha permite identificar crianças com perda auditiva moderada, severa ou\nprofunda.","C":"Uma criança com atraso na linguagem, que tiver realizado teste da orelhinha no primeiro mês de\nvida com laudo normal, não precisa realizar nova avaliação auditiva.","D":"A triagem auditiva neonatal deve ser indicada apenas para os recém-nascidos com risco para\ndeficiência auditiva."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-141593","number":"141593","sourceNumber":"141593","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN com 7 dias de vida, apresentando na cicatriz umbilical, após a queda do coto,\npequena tumoração avermelhada, úmida e que ás\nvezes sangra discretamente. A conduta mais\napropriada é:","options":{"A":"Limpeza local com álcool a 70% e aplicação tópica de pomada antibiótica, pois se trata de\nonfalite localizada;","B":"Limpeza local com álcool a 70% e referir paciente para tratamento antibiótico parenteral, pois se\ntrata de onfalite disseminada;","C":"Limpeza local com álcool a 70% e cauterização sucessiva com nitrato de prata a 2% (bastão ou\nsolução), pois se trata de granuloma umbilical;","D":"Limpeza local com álcool a 70% e observar evolução da hérnia."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-365580","number":"365580","sourceNumber":"365580","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"No que concerne ao atendimento a crianças expostas à sífilis e àquelas com sífilis\ncongênita, assinale a alternativa correta.","options":{"A":"Recomenda-se o tratamento com penicilina cristalina ou procaína por 10 dias para todo\nrecém-nascido com evidência de neurossífilis.","B":"Caso a mãe tenha sido adequadamente tratada, um teste não treponêmico do recém-nascido\ncom título igual ou inferior ao materno exclui a\npossibilidade de sífilis congênita.","C":"Recomenda-se a realização do teste treponêmico, se estiver disponível na avaliação inicial do\nrecém-nascido, tendo em vista sua maior sensibilidade e especificidade em relação ao teste não\ntreponêmico.","D":"Todo recém-nascido de mãe com diagnóstico de sífilis durante a gestação, independentemente\ndo histórico de tratamento materno, deverá\nrealizar teste não treponêmico no sangue periférico."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-365578","number":"365578","sourceNumber":"365578","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"No Brasil, a triagem neonatal começou em 1976, na APAE de São Paulo, por meio de\niniciativas isoladas para detecção de fenilcetonúria. O Programa Nacional de Triagem Neonatal\n(PNTN) foi criado apenas em 2001 e vem sendo ampliado periodicamente. Assinale a alternativa\nque indica a doença triada e o exame realizado de acordo com o PNTN.","options":{"A":"Hipotireoidismo congênito - dosagem do T4 livre","B":"Fibrose cística - dosagem de cloro","C":"Fenilcetonúria - dosagem das concentrações de fenilalanina","D":"Anemia falciforme - visualização de hemácias em foice"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-365576","number":"365576","sourceNumber":"365576","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com base nas diretrizes da Sociedade Brasileira de Pediatria para atendimento ao\nrecém-nascido (RN) ? 34 semanas na sala de parto, assinale a alternativa correta.","options":{"A":"A ventilação com pressão positiva, quando indicada, inicialmente deve ser feita com ar ambiente,\nestando contraindicado o uso de O2 a 100%.","B":"O RN com boa vitalidade, nascido com líquido amniótico tinto de mecônio, deve ser levado\nimediatamente para berço aquecido para aspiração das vias aéreas, com o objetivo de reduzir a\naspiração de mecônio.","C":"A adrenalina deve ser administrada se FC < 60 bpm nos primeiros 60 segundos de vida.","D":"Recomenda-se o clampeamento do cordão umbilical no primeiro minuto após o nascimento, com\no objetivo de reduzir a perda de sangue do\nRN."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-349705","number":"349705","sourceNumber":"349705","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Entre os anos de 2015 a 2017, houve Emergência em Saúde Pública devido ao\naumento na ocorrência de nascidos vivos com\nmicrocefalia no Brasil associada à epidemia do vírus\nZika, época em que foram registrados 4.595 nascidos vivos com essa malformação congênita. A\npartir desse episódio, foi possível confirmar a associação entre o vírus Zika e a microcefalia.\n\nAssinale a alternativa que define corretamente a microcefalia grave.","options":{"A":"Recém-nascidos com perímetro cefálico inferior a 3 desvios-padrão, ou seja, mais de 3\ndesvios-padrão abaixo da média para idade gestacional e sexo.","B":"Recém-nascidos com perímetro cefálico inferior a 2 desvios-padrão, ou seja, mais de 2\ndesvios-padrão abaixo da média para idade gestacional e sexo.","C":"Recém-nascidos com perímetro cefálico inferior a 1 desvio-padrão, ou seja, 1 desvio-padrão\nabaixo da média para idade gestacional e sexo.","D":"Recém-nascidos com perímetro cefálico superior a 3 desvios-padrão, ou seja, mais de 3\ndesvios-padrão acima da média para idade gestacional e sexo.","E":"Recém-nascidos com perímetro cefálico superior a 2 desvios-padrão, ou seja, mais de 2\ndesvios-padrão acima da média para idade gestacional e sexo."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-322172","number":"322172","sourceNumber":"322172","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre a rubéola congênita, assinale a alternativa correta.","options":{"A":"Perda auditiva é a manifestação mais comum e usualmente é condutiva bilateral, e a severidade\nvaria de moderada a grave, com progressão ao\nlongo do tempo.","B":"Cerca de 50% apresentam algum tipo de defeito cardíaco estrutural, sendo mais comuns os\ndefeitos de septo cardíaco.","C":"O risco de transmissão materno-fetal é maior nas primeiras 10 semanas de gestação, e o risco\nde ocorrer malformações prolonga-se até a 18ª e a 20ª semana.","D":"As manifestações tardias de diabete melito e das patologias da tireoide são bastante comuns,\nafetando mais de 1/3 dos casos até a adolescência.","E":"O uso de imunoglobulina para tratamento da rubéola materna garante proteção contra a infecção\ndo feto."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-322181","number":"322181","sourceNumber":"322181","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A fibrose cística está presente em 99% dos pacientes com diagnóstico de íleo\nmeconial. Na ausência de fibrose cística, qual é um dos grupos de recém-nascidos (RN) mais\nacometidos?","options":{"A":"RN com icterícia.","B":"RN com asfixia perinatal.","C":"RN com doença hemolítica.","D":"RN com hipotireoidismo congênito.","E":"RN prematuro com peso muito baixo."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-305312","number":"305312","sourceNumber":"305312","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em qual das seguintes situações, pode-se proceder ao clampeamento tardio do cordão\numbilical?","options":{"A":"Descolamento prematuro de placenta.","B":"Nó verdadeiro de cordão umbilical.","C":"Ausência de tônus muscular em flexão.","D":"Placenta prévia.","E":"Prematuro de 34 semanas."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-305313","number":"305313","sourceNumber":"305313","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Você está de plantão em um hospital e é chamado para atender um Recém-Nascido\n(RN) em sala de parto. O parto é por via\nvaginal, e o RN nasce hipotônico e com movimentos\nrespiratórios irregulares. Você prontamente recebe o RN e inicia o atendimento. A avaliação da\nFrequência Cardíaca (FC) é o principal determinante da decisão de indicar as diversas manobras\nde reanimação. Sobre as particularidades de cada método que pode ser utilizado, assinale a\nalternativa CORRETA.","options":{"A":"A detecção da atividade elétrica do coração pelo monitor cardíaco não traz benefício na\ncondução da reanimação neonatal, pois atrapalha\nas demais manobras.","B":"A palpação do pulso carotídeo é o melhor método em sala de parto, apesar de subestimar a FC.","C":"A ausculta do precórdio com estetoscópio subestima a FC.","D":"A palpação do cordão umbilical superestima a FC.","E":"A oximetria de pulso detecta de forma contínua a frequência de pulso, é rápida e não subestima\nnem superestima a FC."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-274384","number":"274384","sourceNumber":"274384","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em qual das seguintes situações está autorizado o clampeamento tardio do cordão\numbilical, no atendimento em sala de parto?","options":{"A":"Prematuro de 34 semanas.","B":"Descolamento prematuro de placenta.","C":"Prolapso de cordão.","D":"Nó verdadeiro de cordão.","E":"Prematuro de 36 semanas, com tônus fraco."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-261256","number":"261256","sourceNumber":"261256","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Certo recém-nascido (RN) a termo, de parto vaginal, com peso ao nascimento de 3.200\ngramas, é encaminhado à consulta de puericultura aos sete dias de vida, em aleitamento materno\nexclusivo. A lactante relata dor extrema ao amamentar. O peso atual do paciente é de 2.600\ngramas. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Sonolência excessiva, hipoatividade e convulsões são manifestações de hipoglicemia\nneonatal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-261257","number":"261257","sourceNumber":"261257","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Certo recém-nascido (RN) a termo, de parto vaginal, com peso ao nascimento de 3.200\ngramas, é encaminhado à consulta de puericultura aos sete dias de vida, em aleitamento materno\nexclusivo. A lactante relata dor extrema ao amamentar. O peso atual do paciente é de 2.600\ngramas. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Na vigência de hipoglicemia neonatal prolongada, deve-se aventar a hipótese de erros\ninatos do metabolismo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-261258","number":"261258","sourceNumber":"261258","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Determinado recém-nascido (RN) a termo, grande para a idade gestacional, nascido de\nparto vaginal com período expulsivo prolongado, apresenta-se ao nascimento em apneia, com\nhipotonia. O líquido amniótico era tinto de mecônio. O paciente, então, é levado ao berço aquecido.\nDemonstra FC = 80 bpm e SatO? = 80%. A mãe realizou pré-natal adequadamente, sem\nmalformações congênitas detectadas no RN. A respeito desse caso clínico e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Nesse caso, recomenda-se o\nclampeamento do cordão umbilical após três minutos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-261259","number":"261259","sourceNumber":"261259","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Determinado recém-nascido (RN) a termo, grande para a idade gestacional, nascido de\nparto vaginal com período expulsivo prolongado, apresenta-se ao nascimento em apneia, com\nhipotonia. O líquido amniótico era tinto de mecônio. O paciente, então, é levado ao berço aquecido.\nDemonstra FC = 80 bpm; e SatO? = 80%. A mãe realizou pré-natal adequadamente, sem\nmalformações congênitas detectadas no RN. A respeito desse caso clínico e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Deve-se proceder imediatamente com\nmassagem cardíaca externa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-261260","number":"261260","sourceNumber":"261260","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Determinado recém-nascido (RN) a termo, grande para a idade gestacional, nascido de\nparto vaginal com período expulsivo prolongado, apresenta-se ao nascimento em apneia, com\nhipotonia. O líquido amniótico era tinto de mecônio. O paciente, então, é levado ao berço aquecido.\nDemonstra FC = 80 bpm; e SatO? = 80%. A mãe realizou pré-natal adequadamente, sem\nmalformações congênitas detectadas no RN. A respeito desse caso clínico e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Indica-se ventilar o paciente\nutilizando-se\nde pressão positiva.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-261261","number":"261261","sourceNumber":"261261","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Determinado recém-nascido (RN) a termo, grande para a idade gestacional, nascido de\nparto vaginal com período expulsivo prolongado, apresenta-se ao nascimento em apneia, com\nhipotonia. O líquido amniótico era tinto de mecônio. O paciente, então, é levado ao berço aquecido.\nDemonstra FC = 80 bpm; e SatO? = 80%. A mãe realizou pré-natal adequadamente, sem\nmalformações congênitas detectadas no RN. A respeito desse caso clínico e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Para a avaliação do\nneurodesenvolvimento na infância, indica-se avaliar o Apgar da criança ao nascimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-261262","number":"261262","sourceNumber":"261262","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Determinado recém-nascido (RN) a termo, grande para a idade gestacional, nascido de\nparto vaginal com período expulsivo prolongado, apresenta-se ao nascimento em apneia, com\nhipotonia. O líquido amniótico era tinto de mecônio. O paciente, então, é levado ao berço aquecido.\nDemonstra FC = 80 bpm; e SatO? = 80%. A mãe realizou pré-natal adequadamente, sem\nmalformações congênitas detectadas no RN. A respeito desse caso clínico e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Icterícia neonatal à custa de\nhiperbilirrubinemia indireta é uma das complicações do céfalo-hematoma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-261263","number":"261263","sourceNumber":"261263","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Determinado recém-nascido (RN) a termo, grande para a idade gestacional, nascido de\nparto vaginal com período expulsivo prolongado, apresenta-se ao nascimento em apneia, com\nhipotonia. O líquido amniótico era tinto de mecônio. O paciente, então, é levado ao berço aquecido.\nDemonstra FC = 80 bpm; e SatO? = 80%. A mãe realizou pré-natal adequadamente, sem\nmalformações congênitas detectadas no RN. A respeito desse caso clínico e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Crepitações, edema e assimetria\nclaviculares em RN são achados clínicos sugestivos de fratura.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-284364","number":"284364","sourceNumber":"284364","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A detecção em indivíduos saudáveis que poderão desenvolver uma doença hereditária\nno futuro é o objetivo dos testes preditivos\n(TP). Já a epigenética é uma importante ferramenta para\nexplicar as interações entre gene e ambiente. Acerca desses temas, julgue o item. Os estímulos\nambientais que atingem o feto através da placenta ou o recém-nascido por meio da amamentação\npodem provocar alterações químicas no DNA, que envolvem a sequência dos seus nucleotídeos ou\ndas suas estruturas proteicas, afetando a expressão genética.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-250103","number":"250103","sourceNumber":"250103","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um exame físico completo deve ser realizado na primeira consulta de puericultura.\nConsiderando essa informação, julgue o item a\nseguir. O teste do reflexo vermelho ou Bruckner test\ndeve ser realizado, em especial, nos prematuros com trinta e duas semanas ou menos e(ou)\nmenores de 1.500 g na 6.ª semana de vida, pois o teste é uma excelente triagem para retinopatia e,\ncaso esteja normal, dispensa o exame oftalmológico especializado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-250112","number":"250112","sourceNumber":"250112","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Acerca das patologias na infância, julgue o item a seguir. A grande maioria dos\nrecém-nascidos com sífilis congênita apresenta algum sinal ou sintoma ao nascer, principalmente\ncom alterações nos ossos longos detectáveis ao exame radiológico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-239316","number":"239316","sourceNumber":"239316","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma criança de três meses de idade, avaliada em consulta de puericultura, é\nclassificada, pelas curvas de crescimento da\nOrganização Mundial de Saúde, como portadora de\nmuito baixo peso e com perímetro cefálico abaixo do esperado para a idade. É internada para\ninvestigação do quadro, sendo solicitada tomografia de crânio que demonstrou calcificações\nintracranianas periventriculares. Acerca desse caso clínico e considerando os conhecimentos\nmédicos correlatados, julgue o item a seguir. O diagnóstico provável é o de toxoplasmose\ncongênita.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-239317","number":"239317","sourceNumber":"239317","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma criança de três meses de idade, avaliada em consulta de puericultura, é\nclassificada, pelas curvas de crescimento da\nOrganização Mundial de Saúde, como portadora de\nmuito baixo peso e com perímetro cefálico abaixo do esperado para a idade. É internada para\ninvestigação do quadro, sendo solicitada tomografia de crânio que demonstrou calcificações\nintracranianas periventriculares. Acerca desse caso clínico e considerando os conhecimentos\nmédicos correlatados, julgue o item a seguir. O tratamento deve ser realizado com sulfadiazina,\npirimetamina e ácido folínico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-239318","number":"239318","sourceNumber":"239318","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma criança de três meses de idade, avaliada em consulta de puericultura, é\nclassificada, pelas curvas de crescimento da\nOrganização Mundial de Saúde, como portadora de\nmuito baixo peso e com perímetro cefálico abaixo do esperado para a idade. É internada para\ninvestigação do quadro, sendo solicitada tomografia de crânio que demonstrou calcificações\nintracranianas periventriculares. Acerca desse caso clínico e considerando os conhecimentos\nmédicos correlatados, julgue o item a seguir. A avaliação oftalmológica está indicada nesse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-239319","number":"239319","sourceNumber":"239319","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma criança de três meses de idade, avaliada em consulta de puericultura, é\nclassificada, pelas curvas de crescimento da\nOrganização Mundial de Saúde, como portadora de\nmuito baixo peso e com perímetro cefálico abaixo do esperado para a idade. É internada para\ninvestigação do quadro, sendo solicitada tomografia de crânio que demonstrou calcificações\nintracranianas periventriculares. Acerca desse caso clínico e considerando os conhecimentos\nmédicos correlatados, julgue o item a seguir. O rastreio dessa infecção durante a gestação é\npreconizado pelas diretrizes do Ministério da Saúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-239320","number":"239320","sourceNumber":"239320","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma criança de três meses de idade, avaliada em consulta de puericultura, é\nclassificada, pelas curvas de crescimento da\nOrganização Mundial de Saúde, como portadora de\nmuito baixo peso e com perímetro cefálico abaixo do esperado para a idade. É internada para\ninvestigação do quadro, sendo solicitada tomografia de crânio que demonstrou calcificações\nintracranianas periventriculares. Acerca desse caso clínico e considerando os conhecimentos\nmédicos correlatados, julgue o item a seguir. A imunoglobulina hiperimune para essa doença pode\nser administrada até, no máximo, cinco dias após o contato de comunicantes suscetíveis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-239321","number":"239321","sourceNumber":"239321","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma criança de três meses de idade, avaliada em consulta de puericultura, é\nclassificada, pelas curvas de crescimento da\nOrganização Mundial de Saúde, como portadora de\nmuito baixo peso e com perímetro cefálico abaixo do esperado para a idade. É internada para\ninvestigação do quadro, sendo solicitada tomografia de crânio que demonstrou calcificações\nintracranianas periventriculares. Acerca desse caso clínico e considerando os conhecimentos\nmédicos correlatados, julgue o item a seguir. Trombocitopenia é um achado possível nesse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-214420","number":"214420","sourceNumber":"214420","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Determinado paciente, atualmente com 24 meses de vida, é levado pela própria mãe,\nde 18 anos de idade, a consulta com\nespecialista em desenvolvimento. No histórico, observa- se\ngestação durante a adolêscencia da mãe, complicada por trauma abdominal durante discussão\ncom o pai da criança, às 34 semanas de gestação, causando descolamento prematuro da placenta,\ncom necessidade de parto cesáreo de emergência por sofrimento fetal agudo por ocasião. O RN\nnasceu com 1.800 g, sendo necessária a realização de manobras de reanimação neonatal. Ele\npermaneceu internado na unidade de terapia intensiva neonatal por quatro semanas. Apresentou,\nao exame físico, FC de 90 bpm, FR de 20 irpm, saturação de oxigênio de 99%, reflexo cutâneo\nplantar em extensão, reflexo de preensão palmar ausente e capacidade de marchar com apoio\n(mas não sozinho). Refere ausência de controle esfincteriano no momento. O paciente fala algumas\npalavras com duas sílabas. Em relação ao caso clínico descrito, julgue o item a seguir. Não há\npresença de fatores de risco perinatais para distúrbios de desenvolvimento nesse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196631","number":"196631","sourceNumber":"196631","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto vaginal, prematuro tardio, pequeno para a idade gestacional,\nApgar 8 ao primeiro minuto e 10 ao quinto\nminuto, apresenta, em regiões palmoplantares, lesões\ncutâneas bolhosas, com áreas de descamação subjacentes, além de esplenomegalia. A gestante\nnão realizou pré-natal. Com base, nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Trata-se de uma infecção congênita que representa um evento sentinela, por\nrefletir a eficácia tanto de programas de controle quanto da assistência ao pré-natal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196642","number":"196642","sourceNumber":"196642","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto vaginal, prematuro tardio, pequeno para a idade gestacional,\nApgar 8 ao primeiro minuto e 10 ao quinto\nminuto, apresenta, em regiões palmoplantares, lesões\ncutâneas bolhosas, com áreas de descamação subjacentes, além de esplenomegalia. A gestante\nnão realizou pré-natal. Com base, nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Além de esplenomegalia, o recém-nascido também pode apresentar\nhepatomegalia e icterícia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196669","number":"196669","sourceNumber":"196669","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto vaginal, prematuro tardio, pequeno para a idade gestacional,\nApgar 8 ao primeiro minuto e 10 ao quinto\nminuto, apresenta, em regiões palmoplantares, lesões\ncutâneas bolhosas, com áreas de descamação subjacentes, além de esplenomegalia. A gestante\nnão realizou pré-natal. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Uma vez que o paciente é portador sintomático, descarta-se a punção\nlombar para coleta e análise de liquor, pois o tratamento com penicilina benzatina deverá ser\nprontamente instituído.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196691","number":"196691","sourceNumber":"196691","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto vaginal, prematuro tardio, pequeno para a idade gestacional,\nApgar 8 ao primeiro minuto e 10 ao quinto\nminuto, apresenta, em regiões palmoplantares, lesões\ncutâneas bolhosas, com áreas de descamação subjacentes, além de esplenomegalia. A gestante\nnão realizou pré-natal. Com base, nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Não são necessárias medidas preventivas de contato para o paciente, uma\nvez que essa infecção congênita não se transmite por secreções orgânicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196701","number":"196701","sourceNumber":"196701","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto vaginal, prematuro tardio, pequeno para a idade gestacional,\nApgar 8 ao primeiro minuto e 10 ao quinto\nminuto, apresenta, em regiões palmoplantares, lesões\ncutâneas bolhosas, com áreas de descamação subjacentes, além de esplenomegalia. A gestante\nnão realizou pré-natal. Com base, nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. A prematuridade e a restrição de crescimento intrauterino são achados\ndessa infecção congênita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196703","number":"196703","sourceNumber":"196703","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de parto vaginal, prematuro tardio, pequeno para a idade gestacional,\nApgar 8 ao primeiro minuto e 10 ao quinto\nminuto, apresenta, em regiões palmoplantares, lesões\ncutâneas bolhosas, com áreas de descamação subjacentes, além de esplenomegalia. A gestante\nnão realizou pré-natal. Com base, nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. A doença em questão pode cursar com lesões ósseas, com pseudoparalisia\ndos membros.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-214494","number":"214494","sourceNumber":"214494","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"H. C. S., primeiro filho de C. C. S., realizou acompanhamento de puericultura em posto\nde saúde desde a primeira consulta pós-natal\naté atualmente, quando tem 8 anos de idade. Ao\nlongo desse acompanhamento, as variações antropométricas foram registradas nas curvas de\ncrescimento (peso para idade, estatura/altura para a idade, IMC para a idade), e o desenvolvimento\npsiconeuromotor foi avaliado. Na primeira consulta, foi verificada história de parto vaginal\nlaborioso,\nmas não havia histórico de outras complicações gestacionais ou periparto. Atualmente, nas curvas\nantropométricas, observam-se z-score de +3,34 no IMC para a idade e z-score de -1,75 na altura\npara a idade. Considerando as várias consultas realizadas nesse período, os raciocínios\ndiagnósticos e as condutas a serem tomadas frente ao crescimento e desenvolvimento normal e\npatológico, julgue o item a seguir. Na primeira consulta de puericultura, estaria recomendada a\nrealização dos testes de Ortolani e Barlow para avaliação de fratura de clavícula intraparto e de\ndestacamento do plexo braquial, respectivamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196640","number":"196640","sourceNumber":"196640","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Determinada paciente de 16 anos de idade iniciou atendimento pré-natal em posto de\nsaúde da família e foi diagnosticada com\nHIV nas sorologias de primeiro trimestre, iniciando terapia\nantirretroviral adequada e com boa adesão imediatamente. Os demais exames de rotina de\n\npré-natal mostraram-se normais. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Crianças com\npeso de nascimento inferior a 1.500 g não devem\nfazer uso do AZT.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-179206","number":"179206","sourceNumber":"179206","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em uma gestante no terceiro trimestre de gestação, foi observada a seguinte sorologia\npara toxoplasmose: IgG+ e IgM+, com baixo índice de\navidez (20%). O Recém-Nascido (RN) não\napresentou qualquer sintoma ou alteração no exame físico. Foi realizada punção lombar, que\nevidenciou proteinorraquia ? 1.000 mg/dl, e exame de fundo do olho normal. Com base nesse caso\nhipotético, assinale a alternativa que apresenta a conduta terapêutica CORRETA para o RN.","options":{"A":"Pirimetamina, sulfadiazina, ácido fólico e prednisona até seis meses de vida.","B":"Pirimetamina, sulfadiazina, ácido fólico até um ano de idade e prednisona com retirada gradual\napós estabilização do processo inflamatório.","C":"Pirimetamina, sulfadiazina, ácido fólico até dezoito meses de vida.","D":"Pirimetamina, sulfadiazina e ácido fólico até um ano de idade.","E":"Apenas acompanhamento sorológico."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-179211","number":"179211","sourceNumber":"179211","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa que apresenta o fator de risco para desenvolvimento de\nhiperbilirrubinemia significante em RN > 35 semanas de idade gestacional.","options":{"A":"Icterícia nas primeiras 72 horas de vida.","B":"Tipagem sanguínea materna A e RN B.","C":"Tipagem sanguínea materna A ou B e RN O.","D":"Descendência asiática.","E":"Fator RH materno positivo e RN negativo."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-179209","number":"179209","sourceNumber":"179209","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa que apresenta fator de risco para sepse neonatal.","options":{"A":"Gênero masculino.","B":"Segundo gemelar.","C":"Infecção urinária materna em qualquer fase da gestação.","D":"Ruptura prematura de membranas amnióticas superior a seis horas.","E":"Colonização inespecífica do trato genital feminino."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-179177","number":"179177","sourceNumber":"179177","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Embora a grande maioria dos RN sejam assintomáticos ao nascimento, entre 5 e 15%\npodem ter anormalidades tardias, meses a\nanos após o nascimento, principalmente surdez\nneurossensorial, que pode ser bilateral em até 50% dos casos. São os seguintes sinais clínicos\nmais frequentemente observados na infecção congênita por esse agente: restrição do crescimento\nintrauterino; petéquias; hepatoesplenomegalia; icterícia associada à colestase; hiperbilirrubinemia\ndireta; microcefalia; calcificações periventriculares; trombocitopenia e aminotransferases séricas\naumentadas. Essa infecção congênita corresponde:","options":{"A":"À sífilis.","B":"À toxoplasmose.","C":"À Zika.","D":"À rubéola.","E":"Ao citomegalovírus."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-154320","number":"154320","sourceNumber":"154320","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O pediatra é chamado por uma enfermeira, responsável pelo plantão da maternidade\nde um hospital, e questionado acerca de um\nrecém-nascido de 6 horas de vida, que se encontra\ninternado em alojamento conjunto com a mãe. Ela informa que os pais estão ansiosos quanto à\npossibilidade de uma malformação cardíaca do paciente, uma vez que há casos na família. Após\nexaminar o paciente e não encontrar alterações, orienta os familiares, bem como a equipe de\nenfermagem, em relação à realização do teste do coraçãozinho, que é conduzida de forma\nuniversal como parte da triagem neonatal do Sistema Único de Saúde (SUS). O teste permite\nidentificar precocemente graves malformações cardíacas e, caso apresente resultado alterado, o\npaciente deve ser submetido a um exame de ecocardiograma para confirmar o diagnóstico. Acerca\ndo caso apresentado, da técnica recomendada pelo Ministério da Saúde e do resultado do teste,\nassinale a alternativa correta:","options":{"A":"Aferir a saturação de oxigênio (SpO2) no membro superior direito e em um dos membros\ninferiores, entre 12 e 24 horas de vida,\nantes da alta hospitalar. O resultado normal é saturação\nperiférica maior ou igual a 90% em ambas as medidas e diferença menor que 3% entre as medidas.\nCaso qualquer medida da SpO2 esteja alterada, uma nova aferição deverá ser realizada após 12\nhoras. Caso o resultado se confirme, um ecocardiograma deverá ser realizado prontamente.","B":"Aferir a saturação de oxigênio (SpO2) no membro superior esquerdo e em um dos membros\ninferiores, entre 24 e 48 horas de vida, antes\nda alta hospitalar. O resultado normal é saturação\nperiférica maior ou igual a 90% em ambas as medidas e diferença menor que 3% entre as medidas.\nCaso qualquer medida da SpO2 esteja alterada, uma nova aferição deverá ser realizada após uma\nhora. Caso o resultado se confirme, um ecocardiograma deverá ser realizado prontamente.","C":"Aferir a saturação de oxigênio (SpO2) no membro superior direito e em um dos membros\ninferiores, entre 36 e 48 horas de vida,\nantes da alta hospitalar. O resultado normal é saturação\nperiférica maior ou igual a 95% em ambas as medidas e diferença menor que 3% entre as medidas.\nCaso qualquer medida da SpO2 esteja alterada, uma nova aferição deverá ser realizada após 12\nhoras. Caso o resultado se confirme, um ecocardiograma deverá ser realizado prontamente.","D":"Aferir a saturação de oxigênio (SpO2) no membro superior direito e em um dos membros\ninferiores, entre 24 e 48 horas de vida,\nantes da alta hospitalar. O resultado normal é saturação\nperiférica maior ou igual a 95% em ambas as medidas e diferença menor que 3% entre as medidas.\nCaso qualquer medida da SpO2 esteja alterada, uma nova aferição deverá ser realizada após uma\nhora. Caso o resultado se confirme, um ecocardiograma deverá ser realizado prontamente.","E":"Aferir a saturação de oxigênio (SpO2) no membro superior esquerdo e em um dos membros\ninferiores, entre 12 e 24 horas de vida, antes\nda alta hospitalar. O resultado normal é saturação\nperiférica maior ou igual a 90% em ambas as medidas e diferença menor que 3% entre as medidas.\nCaso qualquer medida da SpO2 esteja alterada, uma nova aferição deverá ser realizada após 12\nhoras. Caso o resultado se confirme, um ecocardiograma deverá ser realizado prontamente."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-154329","number":"154329","sourceNumber":"154329","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido apresenta exantema maculoso, icterícia, petéquias e algumas\nvesículas, coriza hemorrágica e lesões ósseas\ncom imagens radiológicas de osteocondrite. Acerca\ndo caso clínico apresentado, assinale a alternativa que corresponde ao diagnóstico mais provável:","options":{"A":"Sífilis congênita.","B":"Infecção pelo herpesvírus.","C":"Infecção por pseudomonas.","D":"Infecção por Streptococcus beta-hemolítico do grupo B.","E":"Doença hemorrágica do recém-nascido."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152176","number":"152176","sourceNumber":"152176","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido (RN), no sexto dia de vida, é levado à unidade básica de saúde, pois a\nmãe vem observando que a criança está mais\n\"amarelada\" a cada dia. Notou a aparição com\naproximadamente 36 horas de vida. A mãe relata que a criança está em aleitamento materno\nexclusivo, satisfazendo-se após as mamadas. Ao exame físico, observa-se RN ictérico até zona IV\nde Kramer, corado, sem visceromegalias, peso 2.720 g (peso do nascimento = 2.950 g). Na\navaliação da caderneta de vacinação, identificou-se que a mãe tem grupo sanguíneo O positivo, e o\nRN tem grupo sanguíneo B positivo. Com base nesse caso hipotético, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. A provável causa da icterícia\nque a esse RN apresenta é a atresia de vias biliares.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152175","number":"152175","sourceNumber":"152175","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido (RN), no sexto dia de vida, é levado à unidade básica de saúde, pois a\nmãe vem observando que a criança está mais\n\"amarelada\" a cada dia. Notou a aparição com\naproximadamente 36 horas de vida. A mãe relata que a criança está em aleitamento materno\nexclusivo, satisfazendo-se após as mamadas. Ao exame físico, observa-se RN ictérico até zona IV\nde Kramer, corado, sem visceromegalias, peso 2.720 g (peso do nascimento = 2.950 g). Na\navaliação da caderneta de vacinação, identificou-se que a mãe tem grupo sanguíneo O positivo, e o\nRN tem grupo sanguíneo B positivo. Com base nesse caso hipotético, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. O tratamento da icterícia se\nbaseia em observação clínica, fototerapia e exsanguineotransfusão, devendo-se quantificar a\nbilirrubina direta e indireta do paciente, em amostra de sangue, para a definição da melhor\nconduta.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152061","number":"152061","sourceNumber":"152061","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido (RN), no sexto dia de vida, é levado à unidade básica de saúde, pois a\nmãe vem observando que a criança está mais\n\"amarelada\" a cada dia. Notou a aparição com\naproximadamente 36 horas de vida. A mãe relata que a criança está em aleitamento materno\nexclusivo, satisfazendo-se após as mamadas. Ao exame físico, observa-se RN ictérico até zona IV\nde Kramer, corado, sem visceromegalias, peso 2.720 g (peso do nascimento = 2.950 g). Na\navaliação da caderneta de vacinação, identificou-se que a mãe tem grupo sanguíneo O positivo, e o\nRN tem grupo sanguíneo B positivo. Com base nesse caso hipotético, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. A icterícia pode causar um\namplo espectro de disfunções neurológicas, desde a encefalopatia transitória até a instalação do\nKernicterus.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152064","number":"152064","sourceNumber":"152064","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido (RN), no sexto dia de vida, é levado à unidade básica de saúde, pois a\nmãe vem observando que a criança está mais\n\"amarelada\" a cada dia. Notou a aparição com\naproximadamente 36 horas de vida. A mãe relata que a criança está em aleitamento materno\nexclusivo, satisfazendo-se após as mamadas. Ao exame físico, observa-se RN ictérico até zona IV\nde Kramer, corado, sem visceromegalias, peso 2.720 g (peso do nascimento = 2.950 g). Na\navaliação da caderneta de vacinação, identificou-se que a mãe tem grupo sanguíneo O positivo, e o\nRN tem grupo sanguíneo B positivo. Com base nesse caso hipotético, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. A icterícia progride no sentido\ncéfalocaudal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152066","number":"152066","sourceNumber":"152066","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido (RN), no sexto dia de vida, é levado à unidade básica de saúde, pois a\nmãe vem observando que a criança está mais\n\"amarelada\" a cada dia. Notou a aparição com\naproximadamente 36 horas de vida. A mãe relata que a criança está em aleitamento materno\nexclusivo, satisfazendo-se após as mamadas. Ao exame físico, observa-se RN ictérico até zona IV\nde Kramer, corado, sem visceromegalias, peso 2.720 g (peso do nascimento = 2.950 g). Na\navaliação da caderneta de vacinação, identificou-se que a mãe tem grupo sanguíneo O positivo, e o\nRN tem grupo sanguíneo B positivo. Com base nesse caso hipotético, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. A icterícia patológica tem\naparecimento tardio, após as primeiras 24 horas de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-152081","number":"152081","sourceNumber":"152081","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Lactente de um mês de idade é levado à Unidade Básica de Saúde para sua segunda\nconsulta de puericultura. A mãe relata que\no paciente está em aleitamento materno exclusivo, peso\n\n= 4.125 g (peso de nascimento = 3.620 g), comprimento de 53 cm, e perímetro cefálico de 36 cm.\nCom base nessa situação, e considerando os conhecimentos médicos a ele relacionados, julgue o\nitem a seguir. O teste do coraçãozinho está registrado na caderneta. Esse é um teste de triagem\nque alerta para cardiopatias congênitas que o paciente possa apresentar e deve ser realizado,\nainda na maternidade, entre 12 e 24 horas de vida.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-289520","number":"289520","sourceNumber":"289520","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido prematuro, com 36 semanas de idade, pequeno para a idade\ngestacional, Apgar 5, 7 e 9, apresenta-se com\nicterícia, hepatoesplenomegalia e plaquetopenia logo\nnas primeiras 24 horas de vida. A ultrassonografia transfontanelar evidencia dilatação ventricular e\ncalcificações intracranianas difusas. Com base na hipótese clínica apresentada, julgue o item a\nseguir. Trata-se provavelmente de um quadro sintomático de toxoplasmose congênita; a\nconfirmação diagnóstica dá-se pela presença de IgM ou IgA específicas nos primeiros seis meses\nde vida, e da persistência de IgG específica no sangue periférico após os 12 primeiros meses de\nvida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-289527","number":"289527","sourceNumber":"289527","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido prematuro, com 36 semanas de idade, pequeno para a idade\ngestacional, Apgar 5, 7 e 9, apresenta-se com\nicterícia, hepatoesplenomegalia e plaquetopenia logo\nnas primeiras 24 horas de vida. A ultrassonografia transfontanelar evidencia dilatação ventricular e\ncalcificações intracranianas difusas. Com base na hipótese clínica apresentada, julgue o item a\nseguir. A infecção congênita apresentada no quadro clínico descrito pode evoluir com surdez\nneurossensorial, de forma que o paciente deve ser encaminhado futuramente para\nacompanhamento audiológico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131851","number":"131851","sourceNumber":"131851","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considere hipoteticamente que gestante de 30 anos de idade, com idade gestacional\nde 38 semanas, chega ao hospital do respectivo\nmunicípio em período expulsivo de trabalho de\nparto. Relata que realizou acompanhamento pré-natal completo e nega doenças crônicas ou\nintercorrências na gravidez. O bebê nasceu com respiração irregular, frequência cardíaca de 60\nbatimentos por minuto e líquido amniótico claro. Com base no exposto, assinale a alternativa que\napresenta o procedimento inicial mais indicado nessa situação clínica.","options":{"A":"Intubação orotraqueal com massagem cardíaca externa.","B":"Ventilação com pressão positiva com balão autoinflável.","C":"Massagem cardíaca externa.","D":"Intubação orotraqueal com ventilação positiva com balão autoinflável.","E":"Intubação orotraqueal com massagem cardíaca externa associada à infusão de solução\ncristaloide e uso de adrenalina em infusão venosa."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-105558","number":"105558","sourceNumber":"105558","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-Nascido (RN) apresenta quadro de desconforto respiratório devido à doença de\nmembrana hialina, com baixa perfusão periférica. Com base nesse caso hipotético, assinale a\nalternativa que apresenta a conduta terapêutica correta.","options":{"A":"Fase expansiva com soro glicosado a 10% a 20 mL/Kg, seguida de infusão contínua de\ndobutamina caso não responda.","B":"Fase expansiva com soro fisiológico a 10 mL/Kg, seguida de infusão contínua de dopamina caso\nnão responda.","C":"Fase expansiva com soro glicosado a 5% a 29 mL/Kg, seguida de adrenalina em infusão\ncontínua caso não responda.","D":"Fase expansiva com soro fisiológico a 20 mL/Kg, seguida de adrenalina em infusão contínua\ncaso não responda.","E":"Fase expansiva com soro glicosado a 10% a 20 mL/Kg, seguida de infusão contínua com\ndopamina e dobutamina caso não responda."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-105554","number":"105554","sourceNumber":"105554","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A pressão de vias aéreas positivas contínuas (CPAP) nasal é um dos recursos mais\nantigos e de ampla utilização nas UTI neonatais devido ao seu baixo custo e fácil manuseio. Seu\nuso tem indicação","options":{"A":"Profilática, pois previne pneumotórax e apneias, e terapêutica, principalmente nas hérnias\ndiafragmáticas, ao diminuir a pressão toráxica.","B":"Profilática, pois leva ao aumento da pressão média das vias aéreas por meio da elevação da\nPEEP (pressão expiratória), prevenindo o\ncolabamento dos alvéolos distais e melhorando a\noxigenação, além de evitar apneia. Terapêutica, pois reabre os alvéolos colabados, estabilizando a\nrespiração do RN.","C":"Terapêutica na falência respiratória com gasometria: PaO2 < 50 mmHg e PaCO2 > 65 mmHg,\nagindo profilaticamente na necessidade de suporte respiratório invasivo e evitando apneia.","D":"Profilática, pois leva ao aumento da pressão média das vias aéreas, por meio da elevação da\nPressão Inspiratória Máxima (PIM), evitando o colabamento dos alvéolos sem repercussões na\napneia, mas, terapeuticamente, só recupera os alvéolos colabados com o uso concomitante de\nsurfactante.","E":"Profilática, ao evitar a baixa perfusão periférica aumentando o débito cardíaco e a apneia, e\nterapêutica, ao aumentar a PO2 recrutando os alvéolos já colabados."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-105566","number":"105566","sourceNumber":"105566","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Há risco de icterícia precoce na seguinte situação, considerando a tipagem de sangue\nda mãe, a tipagem de sangue do RN e o Coombs\ndo RN, respectivamente:","options":{"A":"A+; B+; Coombs indireto do RN positivo.","B":"B+; O+; Coombs direto do RN positivo ou negativo.","C":"A+; O+; Coombs direto do RN positivo.","D":"O+; B+; Coombs direto do RN positivo ou negativo.","E":"O+; A+; Coombs indireto do RN positivo."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-105544","number":"105544","sourceNumber":"105544","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Os testes neonatais são importantes para a prevenção de agravos relacionados à\nsaúde. Constam, na caderneta de saúde da\ncriança do Ministério da Saúde, os exames de triagem\nneonatal que devem ser realizados. Considerando essa informação, assinale a alternativa que\napresenta a relação entre o tipo de exame e a sua CORRETA finalidade.","options":{"A":"Manobra de Ortolani para verificar luxação congênita de joelhos.","B":"Teste do pezinho para verificar, no mínimo, hipertireoidismo, fenilcetonúria e anemia\nfalciforme.","C":"Teste do olho para verificar acuidade visual.","D":"Triagem auditiva por meio de emissões otoacústicas evocadas para avaliar o ouvido interno e a\ncóclea.","E":"Teste do coração para verificar se a saturação do CO2 está > 40%."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-105562","number":"105562","sourceNumber":"105562","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Estudos epidemiológicos demonstram que a exposição fetal a níveis aumentados de\ndeterminados hormônios maternos pode gerar baixo peso ao nascimento. Esses hormônios têm\nsido apontados como um dos principais fatores de risco para desenvolvimento de doenças crônicas\nna fase adulta, como diabetes, hipertensão arterial e distúrbios psiquiátricos (depressão e\nansiedade). Eles são os hormônios:","options":{"A":"testosterona.","B":"tireoidianos.","C":"glicocorticoides.","D":"do crescimento.","E":"estrógenos."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-108232","number":"108232","sourceNumber":"108232","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Julgue o item que se segue, relativo as doenças infecciosas na infância e na\nadolescência. Considere o seguinte caso clínico.\nO exame de VDRL de uma parturiente no período\npós-parto foi positivo. A paciente reportou que havia tido sífilis sete anos atrás, tendo feito\ntratamento conforme recomendação médica, informou, ainda, que, após doze meses, o resultado\ndo VDRL tinha sido positivo 1/2 e que, na gestação atual, ela não havia feito testagem para\nsífilis. O\nteste treponêmico e o TPHA da parturiente feitos após o exame de VDRL pós-parto foram positivos.\nNo recém-nascido, o teste treponêmico e o TPHA foram positivos, e o VDRL positivo 1/1. No caso\nclínico descrito, o médico deverá concluir que o recém-nascido está infectado, portanto, o\nprofissional procederá à coleta de líquido cefalorraquidiano para exame, incluindo o VDRL,\nrealizada radiografia de ossos longos, e inciará tratamento do bebê com penicilina cristalina na\ndose de 100.000 UI/kg/dia durante dez dias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-108209","number":"108209","sourceNumber":"108209","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um menino de cinco anos de idade, nascido vigoroso de parto vaginal, de termo, foi\nlevado a uma consulta com oftalmologista\ndevido a um desvio do olho esquerdo identificado por\nsua mãe havia dois meses. Na consulta, o médico constatou estrabismo com esotropia e leucocoria\nà esquerda. Com base no caso clínico acima apresentado, julgue o item abaixo: O diagnóstico mais\nprovável para a criança em questão é retinopatia da prematuridade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-108229","number":"108229","sourceNumber":"108229","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"No item subsequente, é apresentado um caso clínico referente à resistência ao\n\nrecém-nascido, seguindo de uma assertiva a ser julgada. Um médico foi chamado para assistir um\nrecém- nascido na sala de parto. Ao consultar a história clínica da parturiente, o médico observou\nque ela apresentava fator Rh negativo e exame Coombs indireto positivo 1/16. Nesse caso, o\nmédico deve clampear precocemente o cordão umbilical; coletar e solicitar a tipagem sanguínea, o\nfator Rh e o exame Coombs diretamente do sangue do cordão umbilical; acompanhar o\n\nrecém-nascido no alojamento conjunto da mesma maternidade com uma visita médica após vinte e\nquatro horas de vida pós- natal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-108233","number":"108233","sourceNumber":"108233","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"No item subsequente, é apresentado um caso clínico referente à resistência ao\nrecém-nascido, seguindo de uma assertiva a ser julgada. Um médico estava assistindo um\nrecém-nascido de termo, que nasceu em apnei e envolto em líquifo amniótico claro. Inicialmente,\n\nele posicionou o recém-nascido em decúbito dorsal, aspitou suas vias aéreas e lhe aplicou breves\npiparotes. Enquanto o recém-nascido não iniciou a respiração. Até essa etapa, já tinham se\npassado trinta segundos. O médico, então, solicitou que seu auxiliar monitorizasse a saturação de\nO2 em membro superior direito do recém-nascido, que estava em 81% e iniciou o procedimento de\nventilação com pressão positiva por meio de um balão de ressuscitação manual. Nesse caso, de\nacordo com as normas de reanimação neonatal da Sociedade Brasileira de Pediatria, a ventilação\ncom a pressão positiva deve ser administrada com uma mistura de ar que contenha uma fração de\noxigênio de 80% a fim de se garantir um aumento da saturação de O2 até 90% no primeiro minuto.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-79684","number":"79684","sourceNumber":"79684","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"São causas de desconforto respiratório neonatal, podendo persistir por mais de 48h de\nvida, exceto:","options":{"A":"doença da membrana hialina.","B":"pneumonia.","C":"síndrome da aspiração de mecônio.","D":"taquipneia transitória do RN.","E":"pneumotórax espontâneo."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-82040","number":"82040","sourceNumber":"82040","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um prematuro nasceu após trinta e duas semanas de gestação, de parto vaginal, com\npeso de 1.500 gramas. O parto teve causa\nignorada e bolsa amniótica rota vinte e quatro horas\nantes do parto. O recém-nascido apresentou boletim de Apgar 7 e 7, no primeiro e quinto minutos\nde vida. Ainda na sala de parto, apresentou desconforto respiratório, com saturação de oxigênio de\n70% no sexto minuto de vida. Com base nesse caso clínico, julgue o item subsequente. O\n\nrecém-nascido deverá receber CPAP com máscara facial e oxigenoterapia conforme a saturação\nde oxigênio ainda na sala de parto, com a\nfinalidade de manter pressão positiva nas vias aéreas\nterminais e manter os alvéolos distendidos.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-82058","number":"82058","sourceNumber":"82058","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um prematuro nasceu após trinta e duas semanas de gestação, de parto vaginal, com\npeso de 1.500 gramas. O parto teve causa\nignorada e bolsa amniótica rota vinte e quatro horas\nantes do parto. O recém-nascido apresentou boletim de Apgar 7 e 7, no primeiro e quinto minutos\nde vida. Ainda na sala de parto, apresentou desconforto respiratório, com saturação de oxigênio de\n70% no sexto minuto de vida. Com base nesse caso clínico, julgue o item subsequente.\n\nAlimentação por via enteral deverá ser iniciada após vinte e quatro horas de vida, por sonda\norogástrica, em volumes de 10 a 20\nml/kg/dia, de preferência com colostro da própria mãe, desde\nque comprovada a estabilidade cardiovascular e respiratória do recém-nascido e a presença de\nruídos hidroaéreos no trato digestório.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-334885","number":"334885","sourceNumber":"334885","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Os disrafismos espinhais ocultos são um grupo de afecções dorsais que existem abaixo\nde uma cobertura intacta de derme e\nepiderme. Como a pele e o tecido nervoso se originam do\nectoderma, anomalias de ambos podem ocorrer simultaneamente. Em relação a esse tema, é\ncorreto afirmar que representa um estigma neurocutâneo","options":{"A":"mancha mongólica.","B":"sinus dérmicos.","C":"nevo auricular.","D":"pelos finos em região anal.","E":"ânus imperfurado."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-334888","number":"334888","sourceNumber":"334888","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido (RN) a termo, adequado para a idade gestacional, apresenta quadro\nde icterícia, iniciada com 30 horas de vida.\nNo quinto dia, teve um pico de hiperbilirrubinemia\nindireta de 15 mg/dL, com redução gradual. Está em aleitamento materno exclusivo, com bom\nganho de peso, sem outras alterações ao exame físico. A respeito da icterícia do RN, assinale a\nalternativa correta.","options":{"A":"Na icterícia do leite materno, pode ocorrer aumento da bilirrubina indireta, havendo indicação de\nsuspender o leite materno exclusivo.","B":"A terapêutica padrão-ouro da hiperbilirrubinemia indireta é a exsanguineotransfusão para\nqualquer valor sanguíneo.","C":"Prematuros com IG < 35 semanas apresentam, comumente, hiperbilirrubinemia direta, em razão\nde defeito na conjugação da bilirrubina.","D":"Deve-se solicitar o grupo sanguíneo da mãe e do RN, pois a incompatibilidade ABO leva á\nicterícia nas primeiras 24 a 36 horas de vida.","E":"Segundo as zonas de Kramer, observa-se o nível mais alto de bilirrubina na zona 3, cabeça e\npescoço."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-334889","number":"334889","sourceNumber":"334889","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O Método Canguru é um modelo de atenção perinatal voltado para a atenção\nqualificada e humanizada, que reúne\nestratégias de intervenção biopsicossocial com uma\nambiência que favoreça o cuidado ao recém-nascido (RN) e à sua família. O método promove a\nparticipação dos pais e da família nos cuidados neonatais. Faz parte do método o contato pele a\npele, que começa de forma precoce e crescente desde o toque, evoluindo até a posição canguru.\nNo que se refere a esse método, assinale a alternativa correta.","options":{"A":"Deve ser aplicado ao RN recebendo nutrição parenteral.","B":"Indicado para RN prematuro e (ou) de baixo peso.","C":"Pode atrasar o desenvolvimento neuropsicomotor por causa da posição.","D":"Impossibilita ao RN manter o seu controle térmico.","E":"Deve ser aplicado quando o RN atingir 2.000 gramas."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-343411","number":"343411","sourceNumber":"343411","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN com catarata, cegueira, surdez neurossensorial, microcefalia e persistência do\ncanal arterial, apresenta provável diagnóstico de:","options":{"A":"Sífilis congênita.","B":"Infecção congênita por citomegalovírus.","C":"Rubéola congênita.","D":"Infecção congênita por herpes-simples."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-334891","number":"334891","sourceNumber":"334891","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Certo recém-nascido (RN) de 30 semanas, nascido de parto cesariana, com peso de\nnascimento = 1.000 gramas, foi internado em unidade de terapia intensiva neonatal. Com sete dias\nde vida, iniciou episódios de apneia, com bradicardia e cianose. No que tange à apneia do RN,\nassinale a alternativa correta.","options":{"A":"A utilização de sulfato de magnésio na parturiente pode ser causa de apneia em RN prematuros.","B":"Os eventos de apneia em RN pré-termo aumentam por volta do final do primeiro mês de vida.","C":"As pausas respiratórias periódicas ocorrem com importante queda da saturação e duram maior\ntempo que a apneia.","D":"A utilização do CPAP nasal não está indicada por não conseguir proporcionar adequadas\npressões e (ou) volume residual pulmonar.","E":"O tratamento medicamentoso de escolha da apneia primária da prematuridade é a teofilina, pois\ntem menos efeitos colaterais."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-343421","number":"343421","sourceNumber":"343421","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN de parto cesariana, idade gestacional de 40 semanas, peso de nascimento 2,800\nkg, líquido amniótico claro e bolsa rota no\nato. Iniciou com desconforto respiratório logo após o\nnascimento, necessitando oxigênio inalatório. Radiografia de tórax normal. No final de 72 horas de\nvida, estava eupneico e sem necessidade de oxigênio. O provável diagnóstico é:","options":{"A":"Doença de Membrana Hialina.","B":"Síndrome de Aspiração de Mecônio.","C":"Pneumonia Congênita.","D":"Taquipneia Transitória do RN (TTRN)."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-301284","number":"301284","sourceNumber":"301284","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considere um recém-nascido (RN) do sexo masculino, com peso = 2.220 g, 46 cm,\nperímetro cefálico = 31 cm Apgar 8/09 e exame\nfísico normal. A mãe dele realizou pré-natal\nadequado. No teste de triagem materna, a sorologia mostrou-se negativa para toxoplasmose no\nprimeiro trimestre de gestação. Com 23 semanas, a mãe apresentou quadro de adenomegalia, com\nIgG e IgM anti-Toxoplasma gondii positivas e avidez de IgG < 20%. Assim sendo, iniciou-se o\ntratamento com espiramicina e efetuou-se o exame PCR para toxoplasmose no líquido amniótico,\ncujo o resultado foi positivo. Teve início, então, o tratamento dela com sulfadiazina, pirimetamina\ne\nácido folínico. A ultrassonografia obstétrica apresentou-se normal, o tratamento foi modificado para\nespiramicina com 37 semanas de gestação e fez-se parto cesariano com 39 semanas. Com base\nnesse caso clínico, julgue o item a seguir. A infecção aguda materna foi comprovada pela\nsoroconversão associada a uma avidez baixa de IgG. Houve também clínica sugestiva na mãe,\nfacilitando a determinação de que a infecção tenha acontecido no segundo trimestre, com risco de\nocorrer transmissão congênita. A infecção fetal foi confirmada pela PCR positiva para toxoplasmose\nno líquido amniótico e iniciou-se tratamento materno para minimizar o risco de doença clinicamente\naparente na criança.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-301285","number":"301285","sourceNumber":"301285","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considere um recém-nascido (RN) do sexo masculino, com peso = 2.220 g, 46 cm,\nperímetro cefálico = 31 cm Apgar 8/09 e exame\nfísico normal. A mãe dele realizou pré-natal\nadequado. No teste de triagem materna, a sorologia mostrou-se negativa para toxoplasmose no\nprimeiro trimestre de gestação. Com 23 semanas, a mãe apresentou quadro de adenomegalia, com\nIgG e IgM anti-Toxoplasma gondii positivas e avidez de IgG < 20%. Assim sendo, iniciou-se o\ntratamento com espiramicina e efetuou-se o exame PCR para toxoplasmose no líquido amniótico,\ncujo o resultado foi positivo. Teve início, então, o tratamento dela com sulfadiazina, pirimetamina\ne\nácido folínico. A ultrassonografia obstétrica apresentou-se normal, o tratamento foi modificado para\nespiramicina com 37 semanas de gestação e fez-se parto cesariano com 39 semanas. Com base\nnesse caso clínico, julgue o item a seguir. Considera-se a infecção fetal comprovada quando há\npresença de DNA do Toxoplasma Gondii em líquido amniótico, sangue ou tecido fetal (PCR) e\nentende-se como feto não infectado quando a mãe é soronegativa, ou por IgM ou IgA positivas na\nmãe, sem aparecimento de IgG, ou mediante amostra materna positiva antes da concepção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-273312","number":"273312","sourceNumber":"273312","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém nascido de 37 semanas de idade gestacional, com 5 dias de vida, permaneceu\nno alojamento conjunto por dificuldade de\namamentação. Pré natal feito de forma irregular, os\nexames de sorologias maternas são incompletos. No exame físico da criança chama atenção o\nperímetro cefálico de 30 cm, assim como presença de hepatomegalia e esplenomegalia discretas.\nRealizada ultrassonografia transfontanelar que evidenciou calcificações no parênquima cerebral,\npredominantemente periventriculares. Considerando os achados, o diagnóstico mais provável neste\ncaso é:","options":{"A":"Toxoplasmose congênita.","B":"Sífilis congênita.","C":"Citomegalovirose congênita.","D":"Rubéola congênita."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-268902","number":"268902","sourceNumber":"268902","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O pediatra de uma maternidade, quando chega ao plantão, é comunicado pelo obstetra\nque existe a probabilidade de ocorrerem dois\npartos na próxima hora, com idades gestacionais de\n38 semanas e de 35 semanas. Tendo em vista o quadro clínico apresentado e os conhecimentos\nmédicos relacionados a ele, assinale a alternativa correta.","options":{"A":"Caso os recém-nascidos (RN), logo após a sua extração completa da cavidade uterina, estejam\ncom respiração adequada e tônus muscular em\nflexão, indica-se o clampeamento tardio do cordão.","B":"Em ambos os casos, na idade gestacional de 38 semanas e na de 35 semanas, o contato pele a\npele com a mãe nunca deve ser indicado.","C":"Quanto maior a oferta de oxigênio suplementar durante a reanimação de RN, maior será a\nchance de sucesso da reanimação.","D":"O RN de 35 semanas somente é considerado prematuro, caso nasça com menos de 2.000\ngramas de peso.","E":"A normotermia do RN, temperatura corporal mantida entre 36,5ºC e 37,5ºC, tem como único\nobjetivo o sucesso da amamentação"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-274614","number":"274614","sourceNumber":"274614","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O planejamento e a efetivação das ações e da vigilância na atenção ao neonato são de\nextrema importância devido à vulnerabilidade da criança quando do nascimento. Considerando as\nfases do neonatal, classifica-se como período neonatal tardio o:","options":{"A":"Intervalo de tempo que vai do 2o dia até o momento em que a criança atinge 27 dias, 23 horas e\n59 minutos.","B":"Intervalo de tempo que vai do 7o dia até o momento em que a criança atinge 27 dias, 23 horas e\n59 minutos.","C":"Intervalo de tempo que vai do 7o dia até o momento em que a criança atinge 2 anos.","D":"Intervalo de tempo do nascimento até o 7o dia de vida da criança."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-274619","number":"274619","sourceNumber":"274619","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sépsis é a resposta sistêmica do organismo a um determinado evento. Quanto à sépsis\nneonatal:","options":{"A":"É a infecção bacteriana sistêmica que ocorre nos primeiros 28 dias de vida.","B":"É a infecção bacteriana sistêmica que ocorre nos primeiros 38 dias de vida.","C":"É a infecção fúngica sistêmica que ocorre nos primeiros 23 dias de vida.","D":"É a infecção fúngica sistêmica que ocorre nos primeiros minutos até as 42 horas de vida."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-266449","number":"266449","sourceNumber":"266449","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com relação aos achados de exames de imagem em paciente pediátrico, julgue o item\na seguir. Em se tratando de recém-nascido, a\nidentificação, na tomografia computadorizada do\ncrânio sem contraste, de calcificações periventriculares é mais compatível com o diagnóstico de\ntoxoplasmose congênita do que com o de citomegalovirose congênita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-266450","number":"266450","sourceNumber":"266450","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com relação aos achados de exames de imagem em paciente pediátrico, julgue o item\na seguir. Na radiografia simples do tórax ao\nfinal da primeira hora de vida de um recém-nascido\nprematuro de 28 semanas gestacionais que apresente desconforto respiratório imediatamente após\no parto, o achado de infiltrado reticulogranular difuso e broncograma aéreo até a periferia pulmonar\nbem como o borramento da silhueta cardíaca indicam o diagnóstico de doença da membrana\nhialina de grau III.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-291516","number":"291516","sourceNumber":"291516","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um médico de maternidade pública é chamado para realizar a sala de parto de\ngestante de 35 semanas com pré-eclâmpsia. Um\nrecém-nascido pesando 2,3 kg apresenta-se\nbanhado em líquido amniótico meconial, hipotônico e respirando de forma irregular. O médico\nassistente decide levá-lo à mesa de reanimação para realizar aspiração de vias aéreas superiores\nsob calor. Além disso, posiciona o pescoço em leve extensão, aspira a boca e narinas e seca o\npaciente. Após 30 segundos, o recém-nascido mostra respiração irregular e frequência cardíaca =\n80 bpm. Considerando a situação acima descrita, assinale a alternativa que apresenta a próxima\nconduta que deve ser tomada pelo médico assistente.","options":{"A":"Realizar ventilação com pressão positiva com máscara facial.","B":"Realizar massagem cardíaca externa.","C":"Realizar intubação orotraqueal.","D":"Realizar aspiração traqueal sob visualização direta."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-263397","number":"263397","sourceNumber":"263397","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido a termo de parto cesáreo, que foi indicado por sofrimento fetal,\nencontra-se, logo após o nascimento,\nhipotônico e cianótico, banhado em líquido meconial viscoso.\nNão houve retardo de crescimento intrauterino e a mãe não apresentou intercorrências durante a\ngestação. Na mesa de reanimação, foram realizadas as manobras iniciais de secagem, oferta de\ncalor e aspiração de boca e narinas com sonda. Decorridos 15 segundos, o recém-nascido\nencontra-se hipotônico, com respiração irregular e frequência cardíaca de 75 bpm. A conduta que\ndeve ser realizada até completar o primeiro minuto da reanimação é:","options":{"A":"Aspirar traqueia sob visualização direta para remover o mecônio.","B":"Intubar por via endotraqueal e ventilar com pressão positiva.","C":"Intubar por via endotraqueal e aspirar vias aéreas inferiores.","D":"Ventilar com pressão positiva através de máscara facial."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-291526","number":"291526","sourceNumber":"291526","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido de 15 dias é levado à primeira consulta de puericultura. A gestação\ncorreu sem intercorrências. Mãe relata ser\nasmática e fez uso de prednisona oral durante toda a\ngestação. Parto vaginal a termo. Peso de nascimento = 3 500 g. Apgar 9/9. Alta com 2 dias. Colheu\nteste do pezinho no 4.º dia de vida. Ao exame, o recém nascido mostra-se em ótimo estado geral,\ncorado e hidratado. O exame cardiovascular e respiratório sem anormalidades, assim como o\nexame do abdome. Considerando a história acima, assinale a alternativa que apresenta a doença\ncujo resultado no teste de triagem neonatal pode ter seu resultado modificado pela condição clínica\nmaterna descrita.","options":{"A":"Deficiência de biotinidase.","B":"Anemia falciforme.","C":"Hiperplasia adrenal congênita.","D":"Fibrose cística."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-263424","number":"263424","sourceNumber":"263424","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido a termo, com 24 horas de vida e peso de nascimento de 3.200 g,\nrealiza o teste de triagem neonatal para\ncardiopatia congênita crítica (teste do coraçãozinho) com\nos seguintes resultados. Saturação de O? em membro superior direito (MSD) de 97% e em membro\ninferior direito (MID) de 93%. A conclusão do resultado do teste e a conduta médica indicada em\nrelação ao caso são, respectivamente:","options":{"A":"Teste normal e a criança deve permanecer por mais 24 horas no alojamento conjunto para\nobservação e, então, poderá ser liberada para casa.","B":"Teste limítrofe e deve ser repetido após 12 horas de intervalo e, se persistir com saturação de\nMID < 95%, deve ser solicitada ecocardiografia.","C":"Teste alterado e deve ser solicitado exame radiológico de tórax e avaliação cardiológica com\necocardiografia para esclarecimento.","D":"Teste alterado e deve ser repetido após 1 hora de intervalo e, se persistir com alteração, deverá\nser solicitada ecocardiografia."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-230564","number":"230564","sourceNumber":"230564","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre as características clínicas habitualmente\nidentificadas nos pacientes com síndrome congênita do Zika Vírus:","options":{"A":"Manchas maculares pigmentares focais e cicatrizes retinianas.","B":"Contraturas congênitas.","C":"Hipertonia precoce marcante e sintomas extrapiramidais.","D":"Cardiopatias congênitas."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-244484","number":"244484","sourceNumber":"244484","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considere um recém-nascido que acaba de nascer por parto cesárea por desproporção\ncefalopélvica, a termo, idade gestacional de 39 semanas 3/7. Apresenta Apgar 9/10, peso ao\nnascimento = 4.215 kg, comprimento = 51 cm e perímetro cefálico = 35 cm. A mãe dele, primigesta,\nteve ganho de peso de 32 kg na gestação e, ao 3º trimestre, foi diagnosticada com diabetes\ngestacional. Não manifestou outras intercorrências no pré-natal. Considerando essas informações,\nalém do estímulo ao aleitamento materno exclusivo a ser iniciado na sala de parto deve-se estar\natento e monitorizar o bebê em razão do risco aumentado de","options":{"A":"hiperglicemia.","B":"hipoglicemia.","C":"hipoxemia.","D":"hipocalemia.","E":"hipercalcemia tardia."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-230574","number":"230574","sourceNumber":"230574","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Dentre as situações a seguir, qual esta associada à baixa idade gestacional?","options":{"A":"Encefalopatia hipóxico isquêmica.","B":"Infarto cerebral.","C":"Hemorragia subaracnóidea.","D":"Hemorragia intra-periventricular."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-206175","number":"206175","sourceNumber":"206175","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação às vantagens do alojamento conjunto, assinale a alternativa INCORRETA:","options":{"A":"Melhora o vínculo da mãe com o recém-nascido.","B":"Diminui os gastos do hospital com material.","C":"Diminui o risco de infecção hospitalar.","D":"Melhora o atendimento dos recém-nascidos que realmente precisam do berçário."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-206159","number":"206159","sourceNumber":"206159","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido pré termo, 28 semanas, masculino, nascido de parto normal, Apgar 3 e\n8; presença de fisiometria, intubado em sala de parto, foi encaminhado à UTI Neonatal. Mãe\nsecundigesta, fez pré-natal até 12 semanas, sorologias negativas, urocultura positiva para\nStreptococcus agalactiae tratada com antibioticoterapia. Refere ter iniciado perda de líquidos há 22\nhoras. São fatores de risco para sepse neonatal precoce identificados nesse caso, EXCETO:","options":{"A":"Mãe secundigesta.","B":"Trabalho de parto prematuro.","C":"Mãe colonizada por Strepto.","D":"Bolsa rota > 18 horas."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-206088","number":"206088","sourceNumber":"206088","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação aos distúrbios da glicemia do recém-nascido assinale a alternativa\nCORRETA:","options":{"A":"Hipoglicemia é definida como glicemia plasmática < 40mg/dl e hiperglicemia como glicemia\nplasmática > 120mg/dl.","B":"Tanto a hipoglicemia como a hiperglicemia podem causar repercussões no SNC.","C":"O tratamento da hipoglicemia é feito sempre com push de glicose com soro glicosado a 10%.","D":"No tratamento da hiperglicemia é importante o tratamento da causa, além do uso de insulina\nsubcutânea."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-206126","number":"206126","sourceNumber":"206126","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em áreas endêmicas, casais que desejam a concepção devem ser orientados quanto\naos riscos da infecção pelo vírus Zika e a\npossibilidade de malformações fetais. Sendo\nINCORRETO que:","options":{"A":"A transmissão sexual do vírus Zika foi comprovada por inúmeros relatos de casos, sendo a Zika\nconsiderada uma IST, cuja transmissão sexual pode ser evitada por meio do uso de preservativo.","B":"Para casais que desejam a concepção, recomenda-se aguardar até 2 meses após\nsinais/sintomas relacionados à infecção pelo vírus Zika quando o homem foi infectado.","C":"Deve ser reforçada a importância do uso do preservativo, especialmente após viagens a áreas\nendêmicas ou suspeita e/ou confirmação do diagnóstico da infecção pela parceria sexual.","D":"Isso porque a persistência das partículas virais foi observada em fluidos corporais, como sêmen."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-177244","number":"177244","sourceNumber":"177244","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um paciente, recém-nascido a termo, com 48 horas de vida, apresenta opacificação da\npupila esquerda no teste do olhinho, realizado na maternidade. Considerando-se o referido caso\nclínico e os conhecimentos médicos relativos a ele, é correto afirmar que a melhor conduta a ser\ntomada em relação ao recém-nascido é","options":{"A":"acompanhar o paciente em ambulatório de puericultura, com avaliações semestrais do\noftalmologista, em razão do risco de coriorretinite.","B":"encaminhá-lo o mais breve possível para avaliação oftalmológica, com o intuito de investigar\nretinoblastoma, catarata congênita ou glaucoma congênito.","C":"acompanhar o paciente em ambulatório de puericultura, sem que haja necessidade de avaliação\npor especialista.","D":"encaminhar o paciente para seguimento de rotina com solicitações de sorologias para\ncitomegalovírus e toxoplasmose.","E":"encaminhar o paciente para puericultura, para confirmação do teste com 6 meses de idade."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-177253","number":"177253","sourceNumber":"177253","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Neonato com idade gestacional de 35 semanas + 5 dias apresenta, ao exame físico,\nperímetro cefálico, peso e comprimento abaixo\ndo percentil 10 da curva de crescimento intrauterino\nde referência. Considerando-se o referido quadro clínico e os conhecimentos médicos relacionados\na ele, é correto afirmar que o neonato deve ser classificado como","options":{"A":"pré-termo tardio, pequeno para a idade gestacional, simétrico.","B":"pré-termo moderado, adequado para a idade gestacional,","C":"pré-termo tardio, adequado para a idade gestacional.","D":"a termo, pequeno para a idade gestacional, simétrico.","E":"pré-termo moderado, pequeno para a idade gestacional, assimétrico."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-177263","number":"177263","sourceNumber":"177263","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma paciente recém-nascida, com 39 semanas de idade gestacional e Apgar 8 e 9,\npeso ao nascer de 3.100 g, com apenas 2\nhoras de vida, apresenta dificuldade respiratória. No\nexame físico, ela apresenta FR = 78 irpm, FC = 144 bpm, Tax = 38,2 °C. Além disso, apresenta-se\nbem corada, hidratada, anictérica e acianótica, com fontanelas normotensas e auscultas cardíaca\ne respiratória sem alterações, com abdome sem achados patológicos. A mãe apresentou-se com\ninfecção urinária vigente e sem tratamento no momento do parto. Considerando-se o mencionado\nquadro clínico e os conhecimentos médicos relacionados a ele, é correto afirmar que a conduta\nmais adequada ao citado caso é","options":{"A":"verificar a saturação de oxigênio, retirar as roupas da paciente para melhorar a hipertermia e\nmanter rigorosa observação dos sinais vitais da criança.","B":"retirar as roupas da paciente para o recuo da temperatura, verificar a saturaçao de oxigênio e\nsolicitar hemograma completo da criança com 24 horas de vida.","C":"realizar a intubação orotraqueal para a melhoria do padrão respiratório e, em seguida, realizar a\ncoleta dos exames laboratoriais.","D":"iniciar empiricamente a administração de ampicilina e gentamicina e, após 24 horas, coletar\nexames de controle para sepse.","E":"solicitar rastreio para sepse (incluindo punção lombar) e verificar a glicemia capilar e a\nsaturação\nde oxigênio."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-158009","number":"158009","sourceNumber":"158009","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de 20 dias de vida apresenta convulsões de difícil controle e\nmicrocefalia ao nascimento. A gestação\nocorreu sem acompanhamento regular. Foi realizada uma\ntomografia de crânio, que evidenciou presença de calcificações periventriculares e confirmou\nmicrocefalia. No que se refere a esse caso clínico, quanto à infecção congênita mais compatível\ncom o quadro descrito, assinale a alternativa CORRETA:","options":{"A":"Toxoplasma gondii.","B":"Varicela zóster.","C":"Herpes-vírus.","D":"HIV.","E":"Citomegalovirus."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-158022","number":"158022","sourceNumber":"158022","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Neonato de 18 dias de vida apresenta quadro exantemático, desde a primeira semana\nde vida, caracterizado por máculas e pápulas\nque evoluiram para pústulas estéreis sobre uma base\neritematosa. Algumas têm resolução espontânea. Nesse caso clínico, o diagnóstico mais provável\né:","options":{"A":"Melanose pustulosa neonatal.","B":"Miliária.","C":"Pérolas de Epstein.","D":"Eritema tôxico neonatal.","E":"Crosta láctea."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-158035","number":"158035","sourceNumber":"158035","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considere hipoteticamente um lactente em tratamento para toxoplasmose congênita\ncom coriorretinite, em uso de pirimetamina e\nsulfadiazina. No terceiro mês de tratamento, ao exame\nde laboratório, apresenta palidez generalizada com pancitopenia. A respeito desse caso clínico,\nquanto à terapêutica mais apropriada ao quadro, assinale a alternativa CORRETA:","options":{"A":"Suspender pirimetamina.","B":"Aumentar doses de sulfadiazina.","C":"Acrescentar ácido folínico ao tratamento.","D":"Administrar aciclovir.","E":"Prescrever espiramacina."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-154467","number":"154467","sourceNumber":"154467","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma mulher de 32 anos, primigesta, dá a luz por parto normal a um RN com IG de 42\nsemanas e 2 dias, com peso de nascimento\nde 3870 g e comprimento de 52 cm. Logo após o\nnascimento a criança apresenta respiração regular, tônus muscular em flexão cianose central e FC\nde 118. De acordo com as novas diretrizes do Programa de Reanimação Neonatal da Sociedade\nBrasileira de Pediatria de 2016 está CORRETO nesse caso:","options":{"A":"Colocar a criança em contato pele a pele com a mãe e estimular a amamentação na primeira\nhora.","B":"Conduzir o RN a mesa de ressuscitação e após as manobras iniciais ofertar oxigênio com FiO2\nde 40% até a melhora da cianose.","C":"Proporcionar calor em berço aquecido, posicionar o polo cefálico, com coxim se necessário,\naspirar vias aéreas superiores, secar e\ndesprezar campos úmidos.","D":"Conduzir RN à mesa de ressuscitação e em caso de excesso de secreção com obstrução de via\naérea superior garantir a aspiração de boca, narinas e faringe posterior.","E":"Em caso de líquido amniótico meconial e na presença de profissional capacitado, proceder\nintubação e aspiração traqueal sob visualização direta."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-168529","number":"168529","sourceNumber":"168529","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um lactente com 3 meses de vida é atendido em sua terceira consulta em Unidade\nBásica de Saúde. Segundo o prontuário do\npaciente, ele nasceu a termo por meio de parto normal,\npesando 2.950 g e medindo 49 cm, sem intercorrências, e tendo alta após 24 horas do nascimento.\nPré-natal sem alterações. As emissões otoacústicas evocadas, realizadas duas vezes, e o potencial\nevocado do tronco encefálico, mostram-se alterados (respostas não satisfatórias). Foi realizado um\nnovo potencial evocado do tronco encefálico e o resultado mostra-se normal. O exame físico atual\nnão apresenta alterações, assim como o crescimento e o desenvolvimento da criança. Na situação\ndescrita, a conduta adequada é o acompanhamento audiológico do paciente na unidade","options":{"A":"básica, em conjunto com a especializada.","B":"especializada, com realização de audiometria.","C":"básica, com observação do seu desenvolvimento.","D":"especializada, para tratamento específico de otite crônica."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-129001","number":"129001","sourceNumber":"129001","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O mecanismo de ação da fototerapia é a transformação da bilirrubina nas áreas\nexpostas à luz, que modificam sua estrutura\nmolecular. A respeito dessa importante terapêutica no\nperíodo neonatal, assinale a alternativa CORRETA:","options":{"A":"A molécula de bilirrubina torna-se menos hidrossolúvel, permitindo que ela seja eliminada pelos\nrins e pelo fígado.","B":"Recém-nascidos afrodescendentes respondem menos ao tratamento, pois a pigmentação da\npele limita a penetração da luz na epiderme.","C":"Uma das principais complicações da fototerapia é a hipertermia.","D":"Nas icterícias associadas ao aleitamento materno, deve-se suspender temporariamente a\namamentação para evitar a fototerapia e suas complicações.","E":"A fototerapia só tem eficácia quando se utiliza acima de 15 mg% de bilirrubina indireta no soro,\no\nque contraindica seu uso nas icterícias\nfisiológicas."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-129007","number":"129007","sourceNumber":"129007","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A sepse neonatal precoce geralmente é causada por germes do trato geniturinário\nmaterno. Desse modo, o agente mais comum e o\nesquema de antibiótico a ser usado são\nrespectivamente","options":{"A":"Escherichia coli e antibiótico de amplo espectro para gram-negativo.","B":"Enterobacter e antibióticos de amplo espectro para gram-positivo.","C":"Clamídia e antifúngico.","D":"Gonococo e antibióticos de amplo espectro para gram-negativo.","E":"Streptococcus do grupo A e antibióticos de amplo espectro para gram-positivo."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-104780","number":"104780","sourceNumber":"104780","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa que apresenta importante exame laboratorial que caracteriza\ndiagnóstico de infecção bacteriana no período neonatal.","options":{"A":"Níveis elevados de proteína C-reativa.","B":"Níveis baixos de relação entre neutrófilos imaturos e o total de neutrófilos.","C":"Creatinina elevada.","D":"Níveis elevados de antiestreptolisina O.","E":"Níveis elevados de mucoproteína."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-104772","number":"104772","sourceNumber":"104772","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a alternativa que apresenta a conduta correta em caso de RN manifestar\nconjuntivite gonocócica.","options":{"A":"Tratar o RN com antibiótico sistêmico e os pais com colírio de antibiótico.","B":"Tratar apenas o RN com colírio de antibiótico.","C":"Tratar o RN com colírio de antibiótico e os pais com antibiótico sistêmico.","D":"Tratar tanto o RN quanto os pais com colírio de antibiótico e com antibiótico sistêmico.","E":"Tratar o RN apenas com antibiótico sistêmico, não necessitando tratar os pais."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-111280","number":"111280","sourceNumber":"111280","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Durante exame físico de um recém-nascido eutrófico você observa pequenas vesículas\ncísticas esbranquiçadas na rafe mediana do palato\nmedindo cerca de dois mm e restante da\nmucosa oral sem alterações. A conduta correta neste caso é:","options":{"A":"Iniciar tratamento tópico com nistatina para evitar progressão da doença.","B":"Iniciar tratamento com antibiótico oral devido a faixa etária.","C":"Encaminhar o recém-nascidoa um odontopediatra\npara possível intervenção.","D":"Solicitar perfil lipídico, pois tais vesículas\napresentam conteúdo rico em gordura.","E":"Não é necessária nenhuma conduta, pois se trata de pérolas de Epstein."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-97753","number":"97753","sourceNumber":"97753","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um paciente com dois meses de idade foi atendido no Hospital apresentando há um\nmês coriza mucossanguinolenta e choro à\nmobilização do braço esquerdo. Nasceu a termo, com\npeso de 2 kg, comprimento de 47 cm e perímetro cefálico de 34 cm. Ao exame físico, a criança\nmostrava-se ativa e hidratada, chorava à manipulação do braço esquerdo e apresentava edema em\nporção proximal de úmero. Na ausculta cardiopulmonar, o murmúrio vesicular estava bem\ndistribuído e as bulhas cardíacas eram rítmicas. No abdome palpava-se o fígado a 4 cm do rebordo\ncostal direito e 4 cm do apêndice xifoide e o baço a 4 cm do rebordo costal esquerdo. Resultados\nde exames: Hemoglobina = 9.5 g/dl (Valor de referência: 11,5 - 13,5 g/dl); Hematócrito = 28% (Valor\nde referência: 34% - 40%); Leucócitos = 8.000/ mm³ (Valor de referência. 5.500 - 14.500/mm³);\nSegmentados = 43 %; Linfócitos = 55%; Monócitos = 2%; Plaquetas = 155.000/mm³ (Valor de\nreferência: 150.000 - 350.000/mm³); Bilirrubina total = 1.5 mg/dl (Valor de referência. 0,3-1.2\nmg/dl);\nAST (TGO) = 11 U/L (Valor de referência: < 35 U/L) e ALT (TGP) = 58 U/L (Valor de referência: <\n31 U/L). É solicitado internamento para investigação. A conduta adequada após a admissão é:","options":{"A":"pesquisa de treponemas no sangue, estudo do liquor, radiografia de ossos longos; iniciar\npenicilina cristalina endovenosa.","B":"ultrassonografia de abdome total, radiografia de úmero, fundoscopia; iniciar ganciclovir\nendovenoso.","C":"radiografia de crânio e úmero; iniciar sulfadiazina e pirimetamina por via oral.","D":"avaliação de função hepática e radiografia de ossos longos; iniciar aciclovir endovenoso."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-80739","number":"80739","sourceNumber":"80739","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A Caderneta de Saúde da Criança traz importantes informações, com dados desde o\npré-natal. Em relação às sorologias maternas que estão consignadas na caderneta sob a forma de\nCódigo Internacional de Doenças, aquelas de grande relevância e que, de algum modo, podem ser\nprevenidas ou tratadas no período neonatal são:","options":{"A":"HIV, sífilis, toxoplasmose e rubéola.","B":"HIV, hepatite C, sífilis e toxoplasmose.","C":"HIV, sífilis, toxoplasmose e hepatite B.","D":"Doença de Chagas, toxoplasmose, sífilis e hepatite C.","E":"Rubéola, sífilis, hepatite B e HTLV."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-97742","number":"97742","sourceNumber":"97742","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um lactente com seis meses de idade é trazido a consulta médica em Unidade Básica\nde Saúde para avaliação de atraso do\ndesenvolvimento. A mãe relata que compareceu a somente\nduas consultas de pré-natal e que a criança nasceu de parto vaginal e a termo, pesando 3.240 g,\ncom Apgar 9/10. A alta se deu em dois dias. O sorriso social surgiu com um mês e sustentou o\npescoço com dois meses. Entretanto, hoje não segura objetos, nem rola. Não consegue sentar com\napoio. História familiar não revela casos semelhantes. Ao exame o lactente mostra-se em regular\nestado geral, interagindo pouco com o observador; corado, hidratado, anictérico e acianótico;\nausência de estigmas cutâneos. Auscultas cardíaca e respiratória sem anormalidades. Exame\nneurológico evidencia perímetro cefálico acima do percentil 90 para a idade, aumento de tônus e de\nreflexos profundos nos quatro membros, associado com redução da força proximal. Coordenação\npreservada. Exame dos pares cranianos demonstra dificuldade em acompanhar os objetos\napresentados. Fundo de olho evidencia cicatriz de coriorretinite bilateralmente. Tomografia\ncomputadorizada do crânio evidencia múltiplas calcificações difusamente distribuídas no\nparênquima, associadas a aumento do volume dos ventrículos laterais, terceiro e quarto\nventrículos. O agente etiológico mais provável para o quadro clínico descrito é:","options":{"A":"vírus da rubéola.","B":"Toxoplasma gondii.","C":"Treponema pallidum.","D":"vírus do herpes simples."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-75465","number":"75465","sourceNumber":"75465","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido com 36 semanas de idade gestacional, parto cesariano, Apgar 6 e 8,\npeso de nascimento = 2.100 g, evoluiu com\nsintomas precoces e graves nas primeiras 24 horas de\nvida (icterícia, hepatoesplenomegalia, elevação das enzimas hepáticas, anemia, trombocitopenia e\nhemorragia), associados ao quadro de microcefalia com calcificações cerebrais periventriculares,\nmicroftalmia, coriorretinite e surdez. A principal hipótese diagnóstica para esta infecção\ncongênita e\no tratamento de escolha são, respectivamente:","options":{"A":"herpes simples e aciclovir.","B":"citomegalovírus e ganciclovir.","C":"rubéola e tratamento de suporte.","D":"sífilis congênita e penicilina cristalina.","E":"toxoplasmose e piremetamina/sulfadiazina."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-304871","number":"304871","sourceNumber":"304871","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Neonato, sexo feminino, de 10 dias de vida, comparece à primeira consulta de\npuericultura em aleitamento materno exclusivo.\nMãe refere como queixa que as fezes são \"quase\nbrancas\". História gestacional sem alterações. Nascimento sem intercorrências, 39 semanas,\nantropometria normal para a idade gestacional. Mãe A+, filho A+. Ao exame clínico, apresenta\nexcelente estado geral, ganho de peso satisfatório, icterícia leve em pele e mucosas, abdome\ngloboso, com fígado a 3 cm do rebordo costal direito, liso, borda fina. Durante a palpação\nabdominal, a neonata evacuou e ficou confirmado que as fezes são hipocólicas. Com base nestas\ninformações, marque a alternativa CORRETA:","options":{"A":"Importante fazer o teste de retirada do leite materno por 72h para exclusão da icterícia do leite\nmaterno e retorno à pigmentação das fezes.","B":"Retirar o leite de vaca da mãe, pois pode ser uma das raras manifestações de alergia alimentar\nà proteína do leite de vaca com repercussão\nhepática e intestinal.","C":"Avaliar a possibilidade de doença hepática obstrutiva tais como Atresia de Vias Biliares\nExtra-Hepáticas (AVBEH) ou cisto de colédoco, já que a correção cirúrgica imediata é\nimprescindível.","D":"Avaliar o diagnóstico precoce de hepatite neonatal idiopática que cursa com hiperbilirrubinemia\nintensa, com aumento importante da bilirrubina\nindireta."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-351627","number":"351627","sourceNumber":"351627","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considere o caso a seguir: Ao ser informado sobre a admissão de uma parturiente de\n39 semanas e 2 dias de idade gestacional, o\npediatra encarregado pela sala de parto prontamente\nrequisitou o cartão de pré-natal desta mãe, inteirando-se de que se tratava de gravidez de risco\nhabitual, com nove consultas realizadas em unidade básica de saúde, com sorologias para HIV,\nsífilis, toxoplasmose, rubéola e hepatite B não reagentes. A gestante apresentou níveis tensionais\nadequados em todas as consultas, níveis glicêmicos controlados e não houve episódios de\ninfecção. Ao realizar anamnese materna, orientou a gestante acerca do papel do pediatra na sala\nde parto. Após isso realizou briefing com a equipe assistencial e novamente conferiu a presença de\nmatérias e equipamentos necessários a reanimação neonatal. Cerca de uma hora mais tarde, com\na evolução do parto por via vaginal, ao nascimento observou-se que o recém-nascido estava\nhipotônico. O pediatra procedeu ao clamp imediato, levou o neonato ao berço aquecido, secou o\npaciente e estendeu levemente seu pescoço para abertura de via aérea. Ao constatar que a\nfrequência cardíaca era de vinte batimentos por minuto, iniciou imediatamente ventilação com\npressão positiva sem oxigênio suplementar. Solicitou a seu auxiliar que monitorizasse o paciente.\n\nTrinta segundos depois, notou que, apesar de a técnica de ventilação estar correta, a frequência\ncardíaca era de zero batimentos por minuto.\nDiante disso, iniciou imediatamente massagem\ncardíaca sincronizada em três compressões para uma ventilação. Assegurou-se que a técnica de\ncompressão e ventilação com máscara facial estavam corretas. Como não houve melhora,\nprocedeu à infusão de adrenalina - via cateter umbilical - de três em três minutos, e finalmente ao\nuso de expansão com soro fisiológico. Ainda assim, o paciente não apresentou melhora com as\nmedidas instituídas, evoluindo para óbito. Nesse caso, ao avaliarmos a abordagem do pediatra, é\nCORRETO afirmar que:","options":{"A":"A sequência de reanimação foi realizada de forma correta e adequada, não havendo impacto\npossível no desfecho do caso.","B":"A infusão de adrenalina por cateter umbilical na reanimação neonatal não tem indicação, sendo\no acesso intraósseo o mais adequado nessas\nsituações.","C":"A massagem cardíaca na reanimação em sala de parto só deve ser iniciada a perviedade da via\naérea estar garantida por intubação orotraqueal.","D":"A anamnese materna é de responsabilidade do médico obstetra, tendo o pediatra dispendido\ntempo precioso nessa coleta de informações, as\nquais poderiam ser obtidas em conversa com o\ncolega obstetra."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-354079","number":"354079","sourceNumber":"354079","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Ao nascimento, após as primeiras respirações, o clampeamento tardio do cordão facilita\na transição hemodinâmica para o ambiente\nextrauterino ao permitir:","options":{"A":"A redução do retorno venoso ao coração direito, enquanto a resistência vascular sistêmica está\ndiminuindo.","B":"O aumento do retorno venoso ao coração direito, enquanto a resistência vascular sistêmica está\ndiminuindo.","C":"A redução do retorno venoso ao coração esquerdo, enquanto a resistência vascular pulmonar\nestá aumentando.","D":"A redução do retorno venoso ao coração direito, enquanto a resistência vascular pulmonar está\naumentando.","E":"A manutenção do retorno venoso ao coração esquerdo, enquanto a resistência vascular\npulmonar está diminuindo."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-368170","number":"368170","sourceNumber":"368170","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo nasce hipotônico e com respiração irregular. Após serem\nrealizados os passos iniciais de reanimação\nneonatal, manteve respiração irregular e FC = 80 bpm.\nO próximo passo a ser realizado é:","options":{"A":"estímulo tátil vigoroso em plantas dos pés e dorso.","B":"ventilação com pressão positiva por cânula endotraqueal.","C":"ventilação com pressão positiva por máscara, em ar ambiente.","D":"ventilação com pressão positiva por máscara com oxigênio a 30%."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-336262","number":"336262","sourceNumber":"336262","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN prematuro, masculino, idade gestacional de 27 semanas e 3 dias, nascido por\nSindrome Help materna, estando a mesma na\nUTI desde seu nascimento. Mantido em ventilação\nmecânica, cateter umbilical venoso e arterial, sem antibiótico, uso de nutrição parenteral e fórmula\nenteral própria para prematuro iniciada com 48h de vida. No 7° dia de internação evoluiu com\npalidez, vômito bilioso, instabilidade hemodinâmica com déficit perfusional, sangramento nas fezes,\ndistensão abdominal e dor difusa a palpação. Realizado RX abdome (abaixo). Qual a melhor\nconduta neste caso?","options":{"A":"Antibioticoterapia de largo espectro e reavaliação radiológica em 24h","B":"Ultrassonografia de abdome total","C":"Laparotomia exploradora de urgência","D":"RX abdome seriado a cada 6 horas"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-345713","number":"345713","sourceNumber":"345713","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Quanto à melhor técnica para monitorar a frequência cardíaca do recém-nascido na\nsala de parto, assinale a alternativa correta.","options":{"A":"Ausculta com estetoscópio","B":"Oximetria de pulso","C":"Eletrocardiografia","D":"Palpação do cordão umbilical"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-345714","number":"345714","sourceNumber":"345714","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com relação à definição de hipotensão para um recém-nascido, assinale a alternativa\ncorreta.","options":{"A":"A hipotensão no recém-nascido pode ser definida como PAM menor que 30 mmHg.","B":"Nos recém-nascidos, a hipotensão é a PAM menor que a idade gestacional menos 3.","C":"A hipotensão nos recém-nascidos pode ser definida como a PAM menor que p3 de acordo com\no gráfico de Zubrow.","D":"Não há um consenso sobre a definição de hipotensão em recém-nascidos."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-337633","number":"337633","sourceNumber":"337633","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"No Brasil, o número de mortes por prematuridade, asfixia e infecção é muito acima do\nesperado e, em grande parte, relacionado às causas sensíveis à atenção de qualidade no pré-natal\ne no nascimento. Nesse contexto, sobre o Recém-Nascido (RN) de baixo peso, é CORRETO\nafirmar que:","options":{"A":"O peso ao nascer deve ser inferior a 2.000g para que o recém-nascido possa ser classificado\ncomo RN de baixo peso, independentemente da idade\ngestacional.","B":"O RN de baixo peso, pode se subdividir em dois grupos, sendo RN de peso extremamente baixo\nao nascer < 1.500g e baixo peso ao nascer entre 1.500g e 2.499g.","C":"O RN pré-termo, ou prematuro, é aquele que possui idade gestacional menor que 37 semanas,\npodendo ainda ser dividido em dois\nsubgrupos: imaturidade extrema, com idade gestacional inferior\na 28 semanas de gestação e RN pré-termo, de 28 a 36 semanas de gestação.","D":"A variação de peso considerada normal para cada período da gestação está entre os percentis\nde 20 e 80 e RN pode ser classificado como\nPequeno para Idade Gestacional (PIG), se estiver\nabaixo de 20."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-320439","number":"320439","sourceNumber":"320439","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Durante uma sala de parto, pediatra dá suporte à um recém-nascido, filho de gestante\nque teve acompanhamento pré-natal irregular.\nO recém-nascido apresenta uma tumefação dorsal\nmediana na altura da coluna lombar, de cor avermelhada, coberta por uma fina membrana com\nextravasamento lento de líquido claro através de uma fenda na membrana. A equipe do hospital\ninforma que o neurocirurgião só estará? disponível dentro de dois dias. A conduta neste caso:","options":{"A":"Transferir para unidade com neurocirurgião e realizar cirurgia imediata.","B":"Internar na UTI neonatal e solicitar parecer do neurologista.","C":"Internar em alojamento conjunto e aguardar parecer do neurocirurgião.","D":"Internar na UTI neonatal e solicitar ressonância magnética da coluna lombar.","E":"Internar na UTI neonatal e solicitar ultrassonografia da coluna lombar."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-320441","number":"320441","sourceNumber":"320441","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido, sexo masculino, é levado ao setor de emergência com 16 horas de\nvida. O paciente nasceu na residência da\nfamília, e o pai informa que o bebê ?evacuou sangue?.\nExame físico: peso 3.500g, comprimento 50 cm, FC 150 bpm, FR 50 irpm, pulsos periféricos\nfacilmente palpáveis, exsudação sanguinolenta no coto umbilical. Exames laboratoriais: plaquetas:\n300.000/mm, TAP e PTT prolongados, BT: 5mg/dl, função hepática normal. A medida terapêutica\nmais importante é a administração de:","options":{"A":"antibiótico.","B":"vitamina K.","C":"fatores de coagulação.","D":"plasma fresco congelado.","E":"acetato de desmopressina."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-337641","number":"337641","sourceNumber":"337641","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Uma das mais difíceis e complexas mudanças relacionadas ao nascimento é a\ntransição abrupta para o feto de uma dependência total de suprimento da glicose materna para\numa total independência desta, após a ligadura do cordão umbilical. Sobre os distúrbios\nmetabólicos do recém-nascido, é CORRETO afirmar que:","options":{"A":"Os sinais e sintomas de hipoglicemia em neonatos são inespecíficos, e incluem abalos, letargia,\nfome excessiva, sucção vigorosa, apneia, crises\nde cianose, dificuldade respiratória, convulsões\nmioclônicas ou multifocais, e, muito raramente, coma.","B":"A antecipação e a prevenção são fundamentais para o manejo do RN sob risco de hipoglicemia.\n\nEm recém-nascidos pré-termo ou recém-nascidos pequenos para idade gestacional, o controle da\nglicemia deve ser feito em 3, 6, 12 e 24 horas, e após isso, em intervalos de 8 a 12 horas conforme\nprotocolos das unidades.","C":"A diabetes gestacional ou pré-gestacional materna, administração de drogas à gestante e\nhipertensão e pré-eclâmpsia são fatores de risco para desenvolvimento de hiperglicemia transitória\nneonatal.","D":"O limiar costuma ser considerado para diagnóstico de hiperglicemia nos neonatos como sendo\n126mg/dL no sangue, sendo necessária intervenção terapêutica independente da presença de\nglicosúria com diurese osmótica."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-336288","number":"336288","sourceNumber":"336288","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante, 30 semanas de idade gestacional, DHEG grave, internada há 4 dias inibindo\ntrabalho de parto prematuro, sem outras alterações no pré natal. Evoluiu com piora clínica sendo\nnecessária cesariana de urgência. RN nasceu bem, transferido a UTIN em CPAP nasal, realizou\nRX de tórax abaixo. Sobre o diagnóstico mais provável e a indicação de corticoide ante natal\nassinale a alternativa correta:","options":{"A":"Síndrome do desconforto respiratório, corticóide ante natal era indicada para mãe.","B":"Taquipneia transitória do recém-nascido, conticóide ante natal não era indicada para mãe.","C":"RX normal para o prematuro, corticóide ante natal era indicada para mãe.","D":"Pneumonia, corticóide ante natal não era indicada para mãe."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-335111","number":"335111","sourceNumber":"335111","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo nasce hipotônico e com respiração irregular. Após serem\nrealizados os passos iniciais de reanimação\nneonatal, manteve respiração irregular e FC = 80 bpm.\nO próximo passo a ser realizado é:","options":{"A":"Realizar estímulo tátil vigoroso em plantas dos pés e dorso.","B":"Aplicar ventilação com pressão positiva por cânula endotraqueal.","C":"Aplicar ventilação com pressão positiva por máscara em ar ambiente.","D":"Aplicar ventilação com pressão positiva por máscara com oxigênio a 30%."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-334762","number":"334762","sourceNumber":"334762","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"As infecções adquiridas intra-útero ou durante o trabalho de parto são causas de\nsignificativa morbidade e mortalidade neonatal.\nCorrelacione a coluna com os nomes de algumas\ninfecções adquiridas intra-útero ou durante o trabalho com a coluna dos sinais e sintomas e a\nseguir assinale a alternativa com a ordem correta. (1) Sífilis. (2) Rubéola. (3) Toxoplasmose. (4)\nCitomegalovírus. ( ) Calcificações intracranianas difusas, hidrocefalia, coriorretinite, líquor com\ninexplicável pleiocitose ou proteína elevada e hepatoesplenomegalia. ( ) Rash maculopapular\n(palmas das mãos e plantas dos pés), rinite persistente, osteocondrite e periostite e\npseudoparalisia\nde Parrot. ( ) Catarata, cardiopatia congênita (persistência do canal arterial ou estenose\npulmonar),\nperda auditiva e retardo de crescimento intrauterino. ( ) Calcificações periventriculares,\nmicrocefalia,\ntrombocitopenia, hepatoesplenomegalia e petéquias.","options":{"A":"1, 2, 3, 4.","B":"2, 3, 1, 4.","C":"3, 1, 2, 4.","D":"2, 4, 1, 3."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-306701","number":"306701","sourceNumber":"306701","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante de 37 semanas e 5 dias, após diagnóstico de pré eclampsia é encaminhada\npara cesariana. O recém-nascido (RN) nasce\nhipotônico e em apneia. O pediatra em sala de parto\nsolicita clampeamento imediato de cordão umbilical, leva RN ao berço aquecido e faz os passos\niniciais. Após, avalia o RN que apresenta FC: 90 bpm e mantém apneia. A próxima conduta a ser\nrealizada deve ser:","options":{"A":"CPAP em sala de parto.","B":"Intubação orotraqueal.","C":"Ventilação com pressão positiva.","D":"Massagem cardíaca."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-291628","number":"291628","sourceNumber":"291628","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A alternativa que descreve as complicações mais frequentes nos recém-nascidos de\nmães diabéticas é:","options":{"A":"Hipocalcemia, policitemia e hemorragia intracraniana.","B":"Hipoglicemia, Cardiopatia congênita e policitemia.","C":"Anemia, hipoglicemia e déficit sucção.","D":"Anemia, hipocalcemia e síndrome de aspiração meconial.","E":"Anemia, hipoglicemia e hiponatremia."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-291629","number":"291629","sourceNumber":"291629","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido pré-termo de 34 semanas de idade gestacional, pequeno para idade\ngestacional, peso de nascimento de 1.500 gramas, mãe hipertensa grave. Apresenta com uma hora\nde vida dosagem capilar de glicose pela glicofita de 12mg/dL. A conduta terapêutica imediata é\nrealizar:","options":{"A":"Hidratação venosa com glicose a 50% e alimentação por sucção com duas horas de vida.","B":"Infusão rápida de glicose 10%, alimentação com duas horas de vida por gavagem e controle de\nglicemia capilar em seis horas.","C":"Infusão rápida de glicose 10%, mais hidratação venosa com glicose a 10% e controle de\nglicemia capilar em 30 minutos.","D":"Hidratação venosa com SF 0;9%, alimentação com uma hora de vida por sucção e controle de\nglicemia capilar em duas horas.","E":"Estimular aleitamento materno e reavaliar criança em 1 hora."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-291630","number":"291630","sourceNumber":"291630","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante com 39 semanas de idade gestacional admitida em trabalho de parto. Oito\nconsultas de prénatal, segunda gestação, histórico de sífilis na gestação anterior. Com 11 semanas\nde idade gestacional apresentou VDRL de 1:128, recebendo três doses de Penicilina Benzatina,\n2.400.000UI, com intervalo de uma semana entre cada dose. Parceiro se recusou a pesquisar e\ntratar sífilis. Teve queda titulação VDRL 1:16. Com 28 semanas de idade gestacional, apresentou\naumento de título de VDRL de 1:64. Parto vaginal, recém-nascido vigoroso, assintomático ao\nexame físico, sendo encaminhado ao alojamento conjunto. Nesse caso, é correto afirmar que:","options":{"A":"Mãe inadequadamente tratada para sífilis gestacional, devemos realizar apenas o VDRL de\nsangue periférico do recém-nascido. Se o VDRL do\nrecém-nascido for reator, independente do\ntítulo, devemos tratar com Penicilina Cristalina por dez dias, mesmo que haja possibilidade de\nseguimento ambulatorial.","B":"Mãe adequadamente tratada para sífilis gestacional, devemos realizar o VDRL de sangue\nperiférico do recém-nascido, avaliação liquórica, hemograma completo e radiografia de ossos\nlongos. Só iniciar o tratamento se houver alteração em qualquer dos exames de triagem.\nAcompanhar ambulatorialmente, minimamente por dois anos.","C":"Mãe inadequadamente tratada para sífilis gestacional, devemos realizar o VDRL de sangue\nperiférico, punção lombar, hemograma, radiografia\nde ossos longos do bebê. Se o VDRL do\nrecém-nascido for reator e houver alteração no líquor, devemos tratar com Penicilina Cristalina por\ndez dias e acompanhar ambulatorialmente, por pelo menos 2 anos.","D":"Mãe adequadamente tratada para sífilis gestacional, devemos realizar o VDRL de sangue\nperiférico do recém-nascido. Se o VDRL do\nrecém-nascido for não reator, devemos tratar com\nPenicilina Benzatina em dose única, independente da possibilidade de seguimento ambulatorial.","E":"Mãe inadequadamente tratada para sífilis gestacional, devemos realizar VDRL e hemograma do\nde sangue periférico do recém-nascido. Se o\nVDRL do recém-nascido for não reator, devemos dar\nalta hospitalar para seguimento ambulatorial."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313306","number":"313306","sourceNumber":"313306","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considere a alternativa que descreve, corretamente, o teste do coraçãozinho:","options":{"A":"Aferição da oximetria de pulso no membro superior direito (MSD) e em um dos membros\ninferiores (MI). RN entre 24 e 48 horas de vida, antes da alta hospitalar.","B":"Aferição da oximetria de pulso no membro superior esquerdo (MSD) e em um dos membros\ninferiores (MI). RN entre 24 e 48 horas de vida, antes da alta hospitalar.","C":"Aferição da oximetria de pulso no membro superior direito (MSD) e no membro superior\nesquerdo (MSE). RN entre 24 e 48 horas de vida, antes da alta hospitalar.","D":"Aferição da oximetria de pulso no membro superior direito (MSD) e em um dos membros\ninferiores (MI). RN entre 6 a 12 horas de vida, antes da alta hospitalar.","E":"Aferição da oximetria de pulso no membro superior esquerdo (MSD) e em um dos membros\ninferiores (MI). RN entre 6 a 12 horas de vida, antes da alta hospitalar."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313307","number":"313307","sourceNumber":"313307","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"MHR é RN, nascida de parto cesárea, de primípara de 20 anos. Nasceu com 48 cm,\n2,950 Kg, Apgar 9, sem alterações congênitas. Ao exame clínico, o pediatra verifica hemorragia\nabaixo da aponeurose epicraniana que conecta os componentes frontal e occipital dos músculos\nfronto-occipitais. O diagnóstico desse achado é:","options":{"A":"Hematoma Subgaleal.","B":"Céfalo-hematoma.","C":"Bossa sanguinolenta.","D":"Borra serossanguínea.","E":"Caput succedaneum."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313308","number":"313308","sourceNumber":"313308","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A atresia biliar é a principal causa de transplante hepático em crianças e, se não\ntratada, é fatal em 100% dos casos. A única\nalternativa para evitar o transplante hepático, tendo\nmelhores resultados se realizada, precocemente, é a cirurgia de:","options":{"A":"Nissen (portoenterostomia).","B":"Kasai (portoenterostomia).","C":"Bohr (portoenterostomia).","D":"Whipple (portoenterostomia).","E":"Hartmann (portoenterostomia)."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313310","number":"313310","sourceNumber":"313310","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre as medicações de reanimação neonatal, a adrenalina endotraqueal é indicada na\ndosagem de:","options":{"A":"0,1 ? 0,3 mL/Kg.","B":"0,25 ? 0,5 mL/Kg.","C":"0,5 ? 1,0 mL/Kg.","D":"0,8 ? 1,5 mL/Kg.","E":"1,0 ? 2,0 mL/Kg."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313311","number":"313311","sourceNumber":"313311","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com relação ao diagnóstico diferencial das infecções congênitas. Não há edema\ngeneralizado em casos de:","options":{"A":"Sífilis.","B":"Citomegalovirose.","C":"Doença de Chagas.","D":"Vírus Herpes Simples.","E":"Toxoplasmose generalizada."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313312","number":"313312","sourceNumber":"313312","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"De acordo com o Ministério da Saúde, os seguintes princípios devem ser adotados para\nmelhorar os efeitos da terapia com o surfactante: I- Estimular o uso de corticoide antenatal em\ngestantes de risco para parto prematuro; II- Implementar recursos suficientes de pessoal,\nequipamentos e laboratório para o cuidado de RN com insuficiência de múltiplos órgãos. Além\ndisso, manter vigilância constante da qualidade do atendimento a esses pacientes; III- Preferir os\npreparados contendo surfactante endógeno de animais, exceto nas situações em que a lesão\ninflamatória é extensa, como na síndrome do desconforto respiratório - SDR grave, pneumonias,\nsíndrome de aspiração meconial - SAM e na síndrome do desconforto respiratório agudo ? SDRA;\nIV- Iniciar com dose de 10 mg/kg de fosfolípides. Caso o paciente apresente melhora da função\npulmonar, manter essa dose se houver necessidade de novo tratamento. Nas situações em que há\nlesão inflamatória extensa (SDR grave, pneumonias, SAM e SDRA), considerar o uso de doses\nmaiores, próximas a 15 mg/kg de fosfolípides. A necessidade de doses adicionais deve ser\nindividualizada. Dos itens acima:","options":{"A":"Apenas os itens III e IV estão corretos.","B":"Apenas os itens I e II estão corretos.","C":"Apenas os itens I e III estão corretos.","D":"Apenas os itens II e III estão corretos.","E":"Apenas os itens II e IV estão corretos."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313313","number":"313313","sourceNumber":"313313","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A cianose, coloração azulada decorrente da presença de pelo menos 5 g de\nhemoglobina não saturada, é intercorrência,\nrelativamente comum, no RN, que, frequentemente,\npossui níveis de hemoglobina:","options":{"A":"Abaixo de 9 g/dL.","B":"Abaixo de 11 g/dL.","C":"Acima de 13 g/dL.","D":"Acima de 15 g/dL.","E":"Acima de 18 g/dL."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313314","number":"313314","sourceNumber":"313314","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O milium sebáceo está presente em 40% dos RNs. É correto afirmar que o milium\nsebáceo manifesta-se por:","options":{"A":"Pelos finos que costumam recobrir a região do ombro e da escápula.","B":"Material gorduroso e esbranquiçado na cabeça e nas extremidades.","C":"Manchas azul-acinzentadas localizadas, preferencialmente, no dorso e nas regiões glútea e\nlombossacra.","D":"Pequenos pontos brancos (menor que 1mm), localizados na base do nariz, queixo e fronte.","E":"Lesões eritematosas multiformes (pápulas, máculas e até algumas vesículas), esparsas ou\nconfluentes."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313315","number":"313315","sourceNumber":"313315","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN pré-termo (32 semanas), com presença de taquipneia, retração subcostal e tiragem\nintercostal importantes, gemidos expiratório e crises de cianose. Achados radiológicos pouca\nexpansão pulmonar, infiltrado micronodular difuso (vidro fosco?) e aerobroncogramas. Sobre o caso\nclínico, temos que: I- O uso do CPAP ? pressão de distensão contínua de vias aéreas ? deve ser\nprecoce. II- Possivelmente é um caso de doença de membrana hialina (DMH). III- O uso de\nsurfactante, nesses casos, leva à piora drástica da condição respiratória, sendo contraindicado.","options":{"A":"Nenhum dos itens está correto.","B":"Apenas os itens I e II estão corretos.","C":"Apenas os itens I e III estão corretos.","D":"Apenas os itens II e III estão corretos.","E":"Todos os itens estão corretos."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-305036","number":"305036","sourceNumber":"305036","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considere um recém-nascido a termo nasce hipotônico e com respiração irregular.\nApós serem realizados os passos iniciais de\nreanimação neonatal, manteve respiração irregular e\nFC = 80 bpm. Nesse caso, o próximo passo é:","options":{"A":"Realizar estímulo tátil vigoroso em plantas dos pés e dorso.","B":"Aplicar ventilação com pressão positiva por cânula endotraqueal.","C":"Aplicar ventilação com pressão positiva por máscara, em ar ambiente.","D":"Aplicar ventilação com pressão positiva por máscara com oxigênio a 30%."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-260687","number":"260687","sourceNumber":"260687","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém nascido a termo, parto normal, com 18 horas de vida, em bom estado geral,\ngrupo sanguíneo A positivo, em aleitamento\nmaterno exclusivo, apresenta-se ictérico até a região\ndo tronco. No prontuário materno há registro de Gesta: 1 Para: 1, Aborto: 0, três consultas de\n\npré-natal; tipagem sanguínea materna: O positivo; sorologias do último trimestre de gestação:\nnegativas. A conduta adequada é realizar:","options":{"A":"Hemograma, bilirrubinas, Coombs direto e suspender aleitamento materno.","B":"Hemograma, bilirrubinas, ultrassonografia de abdome e suspender aleitamento materno.","C":"Hemograma, reticulócitos, bilirrubinas, ultrassonografia de abdome e manter aleitamento\nmaterno.","D":"Hemograma, reticulócitos, bilirrubinas, Coombs indireto e manter aleitamento materno.","E":"Hemograma, reticulócitos, bilirrubinas, Coombs direto e manter aleitamento materno."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-260688","number":"260688","sourceNumber":"260688","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Ao prestar assistência a um parto vaginal, você observa que ao romper a bolsa o\nlíquido amniótico encontra-se meconial. Logo\napós a extração o recém-nascido se encontra com\ntônus preservado, mas com movimentos respiratórios irregulares. A conduta apropriada neste caso\napós o clampeamento do cordão umbilical é:","options":{"A":"Secar o corpo e a cabeça do recém-nascido e promover o contato pele-a-pele com a mãe,\nsempre friccionando a sua pele para que ele respire normalmente.","B":"Secar o corpo e a cabeça do recém-nascido, promover o contato pele-a-pele com a mãe e\naspirar o nariz do recém-nascido nesta posição para facilitar sua respiração.","C":"Levar o recém-nascido para unidade de calor radiante, posicionar a cabeça, aspirar a traqueia e\nrealizar intubação orotraqueal.","D":"Levar o recém-nascido para unidade de calor radiante, posicionar a cabeça, aspirar boca e nariz,\nsecar, desprezar campos e avaliar.","E":"Clampeamento tardio do cordão umbilical e após promover o contato pele-a-pele com a mãe e\naspirar o nariz do recém-nascido nesta posição para facilitar sua respiração."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-287351","number":"287351","sourceNumber":"287351","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"São doenças que acometem o indivíduo na infância que podem ser diagnosticada no\n\n?teste do pezinho?, EXCETO?","options":{"A":"Fibrose cística.","B":"Hipotireoidismo.","C":"Fenilcetonúria.","D":"Deficiência da 21- hidroxilase."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-287906","number":"287906","sourceNumber":"287906","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre as doenças de pele no recém-nascido, analisar os itens abaixo: I. A miliária,\nproblema cutâneo comum no período neonatal, pode\nse manifestar em dois tipos: cristalina e rubra.\n\nII. A infecção secundária por Candida é um evento muito frequente nas dermatites da região das\nfraldas. III. O impetigo é causado exclusivamente pelo Streptococcus pyogenes. Está(ão)\nCORRETO(S).","options":{"A":"Somente o item I.","B":"Semente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-287911","number":"287911","sourceNumber":"287911","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Considerando-se a icterícia neonatal, analisar os itens abaixo: I. A icterícia\nfisiológica\nreflete uma adaptação neonatal ao metabolismo\nda bilirrubina indireta e tem início precoce, em\ngeral nas primeiras 24 horas de vida. II. A icterícia que tem início tardio, com mais de 24 horas de\nvida, decorre de processo patológico, com possibilidade de elevação anormal da concentração\nsérica de bilirrubina indireta e com possível dano cerebral. III. A icterícia associada ao leite\nmaterno\nem neonatos saudáveis e em aleitamento materno exclusivo pode perdurar até o segundo ou\nterceiro mês de vida. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item III.","C":"Somente os itens I e II.","D":"Somente os itens II e III.","E":"Nenhum dos itens."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-255622","number":"255622","sourceNumber":"255622","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A icterícia neonatal ocorre em 85% dos neonatos nascidos a termo e a maioria dos\ncasos é fisiológica. Sobre os fatores de\nmaior risco para hiperbilirrubinemia indireta, MARQUE A\nCORRETA:","options":{"A":"Mãe de tipagem AB.","B":"Mãe hipertensa.","C":"Baixo aporte de leite materno na primeira semana de vida.","D":"Recém-nascido termo."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-255623","number":"255623","sourceNumber":"255623","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O diagnóstico precoce das infecções congênitas e adquiridas no período perinatal é de\nfundamental importância para o início da terapia adequada e determinação do prognóstico. Em\nrelação à sífilis congênita. MARQUE A CORRETA:","options":{"A":"Pode ser classificada como sífilis congênita precoce ou tardia.","B":"Os testes não treponêmicos, como o VDRL, são pouco sensíveis e muito específicos.","C":"Os casos notificados se estabilizaram nos últimos anos.","D":"Nos recém-nascidos de mães com sífilis inadequadamente tratada, sem alterações clínicas,\nradiológicas, hematológicas ou liquóricas e VDRL negativo, não é necessário o tratamento."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-234416","number":"234416","sourceNumber":"234416","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação à rubéola na gravidez, assinale a alternativa INCORRETA:","options":{"A":"A rubéola é uma doença infecciosa aguda virótica causada pelo vírus da família ?Fogaviridae?,\nsendo que a infecção ocorre de forma horizontal\nou vertical.","B":"Os sintomas são inespecíficos no período prodrômico da rubéola, e o exantema quando surge é\ndo tipo maculopapilar fino.","C":"A principal forma de transmissão dessa doença é a vertical e os mecanismos de danos ao feto\nocorrem por lesões intensas e bem localizadas.","D":"O diagnóstico clínico de rubéola é muito difícil por algumas razões. Dentre elas os vários tipos\nde exantema que são atribuídos à rubéola e vice-versa."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-232126","number":"232126","sourceNumber":"232126","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Aleitamento materno é fundamental para o crescimento e desenvolvimento adequados\nda criança. No período neonatal, mesmo o\nrecém-nascido saudável poderá apresentar icterícia\nprecoce em razão de aleitamento materno insuficiente, cuja etiologia é hiperbilirrubinemia","options":{"A":"direta por esteatose hepática.","B":"direta por céfalo-hematoma.","C":"indireta por deficiência da enzima lactoferrina.","D":"indireta por deficiência de alfa-1-antitripsina.","E":"indireta por aumento da circulação êntero-hepática da bilirrubina."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-232128","number":"232128","sourceNumber":"232128","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Todo recém-nascido é avaliado ao nascimento pelo escore de Apgar, no primeiro e no\nquinto minuto de vida. Qual dos itens não faz parte dessa avaliação?","options":{"A":"Tônus muscular.","B":"Reatividade à aspiração.","C":"Frequência respiratória.","D":"Frequência cardíaca.","E":"Coloração."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-227099","number":"227099","sourceNumber":"227099","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Colestase é a incapacidade de secretar bilirrubina, o que resulta em hiperbilirrubinemia\nconjugada e icterícia. Sobre a colestase, é\nINCORRETO afirmar que:","options":{"A":"A doença extra-hepática mais comum é a atresia biliar.","B":"A incompatilibade de Rh, seria a principal causa de colestase.","C":"As causas tóxicas ocorrem principalmente devido ao uso de nutrição parental.","D":"A colestase é tipicamente observada nas primeiras 2 semanas de vida."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-232131","number":"232131","sourceNumber":"232131","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido, 39 semanas de idade gestacional, Apgar 9/10, sem fatores de risco,\napresenta icterícia em face com 18 horas de vida. História obstétrica sem fatores de risco. Grupo\nsanguíneo materno: O +, do RN: B +. Exame físico: ativo, mamando bem, já eliminou mecônio e\napresentou diurese. Nesse caso, está indicado","options":{"A":"observar e reavaliar a icterícia antes da alta para decidir sobre a realização de exames.","B":"colher exames laboratoriais para avaliar incompatibilidade ABO e decidir sobre fototerapia.","C":"aguardar completar 24 horas e colher exames para avaliar exsanguineotransfusão.","D":"suspender o aleitamento materno, pois se trata de icterícia associada ao aleitamento materno.","E":"alta hospitalar com reavaliação em 24 horas."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-227101","number":"227101","sourceNumber":"227101","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sífilis congênita é uma infecção de múltiplos sistemas, causada pelo Treponema\npallidum e transmitida ao feto pela placenta.\nEm relação a sífilis congênita, assinale a alternativa\nINCORRETA:","options":{"A":"A sífilis congênita precoce manifesta-se com erupções vesiculobolhosas características ou\nerupção macular com coloração cúprica nas palmas das mãos e nas solas dos pés.","B":"A sífilis congênita tardia geralmente se manifesta após o segundo mês de vida e causa úlcera\ngomosa.","C":"A suspeita diagnóstica de sífilis congênita precoce baseia-se usualmente na sorologia materna,\nrealizada de rotina no início da gestação, com frequência no terceiro trimestre e no parto.","D":"A sífilis pode causar muitas anormalidades diferentes nas radiografias dos ossos longos."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-227316","number":"227316","sourceNumber":"227316","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A capacidade de manter constante a temperatura corporal é limitada no\nRecém-Nascido e depende da idade gestacional e pós natal, do peso de nascimento e das\ncondições clínicas do Recém-Nascido. Assinale a repercussão clínica que não ocorre na\nhipotermia.","options":{"A":"Edema ou escleredema.","B":"Diminuição do débito cardíaco.","C":"Diminuição da produção de surfactante.","D":"Diminuição do consumo de oxigênio."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-246796","number":"246796","sourceNumber":"246796","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Lactente de 45 dias apresenta colestase desde a segunda semana de vida. Qual dos\nachados clínicos afasta temporariamente o\ndiagnóstico de atresia das vias biliares?","options":{"A":"Ganho de peso adequado.","B":"Fígado palpável.","C":"Baço palpável.","D":"Icterícia às custas de aumento da bilirrubina direta.","E":"Fezes coradas."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-199498","number":"199498","sourceNumber":"199498","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A icterícia neonatal é, provavelmente, o diagnóstico mais frequentemente realizado nos\nrecém-nascidos. Em relação a icterícia neonatal, assinale a alternativa INCORRETA:","options":{"A":"A produção diária de bilirrubina no recém- nascido é pelo menos duas vezes mais do que na\ncriança maior.","B":"O aleitamento materno está claramente associado a aumento na incidência da icterícia neonatal.","C":"A icterícia que se inicia antes de 24h de vida, frequentemente se deve à doença hemolítica.","D":"A metabolização e a reciclagem de sangue sequestrados em hematomas, equimoses ou\nhemorragias são uma causa frequente de hiperbilirrubinemia direta."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-202730","number":"202730","sourceNumber":"202730","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Segundo o Programa de Reanimação Neonatal, quando existe a necessidade do uso\nde adrenalina no momento da reanimação, a\ndiluição e a dose a ser administrada por via\nIntravenosa, respectivamente, são:","options":{"A":"1/5.000 / 0,05-0,1ml/kg.","B":"1/2.000 / 0,3-0,5ml/kg.","C":"1/1.000 / 0,1-0,5ml/kg.","D":"1/10.000 / 0,1-0,3ml/kg.","E":"1/5.000 / 0,1 -0,3 ml/kg."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-202751","number":"202751","sourceNumber":"202751","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual dos achados abaixo determina a escolha do tratamento para um recém nascido\ncom sífilis congênita?","options":{"A":"Radiografia de ossos longos com sinais de periostite.","B":"Pênfigo palmo plantar.","C":"Proteína no líquor > 160 mg/dl.","D":"Hemograma com score rodwell > 3.","E":"Vdrl no sangue do recém nascido 1/128."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-202756","number":"202756","sourceNumber":"202756","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Dos diagnósticos citados abaixo, qual o mais provável para o recém-nascido, cuja a\nmãe não fez pré-natal e apresenta baixo peso, anemia, icterícia, hepatoesplenomegalia,\nhidrocefalia e coriorretinite?","options":{"A":"Sífilis congênita.","B":"Toxoplasmose congênita.","C":"Doença de Chagas congênita.","D":"Infecção pelo citomegalovírus congênita.","E":"Rubéola Congênita."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-202774","number":"202774","sourceNumber":"202774","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Adolescente de 17 anos, internada em período expulsivo, dá à luz recém-nascido a\ntermo, vigoroso e sem nenhuma anormalidade\naparente ao exame clínico. A análise do cartão do\npré-natal da adolescente revela que, apesar de negativo no primeiro trimestre, o VDRL colhido no\núltimo trimestre de gestação foi positivo na diluição de 1/8. A adolescente informa que iniciou\ntratamento penicilínico na semana que antecedeu o parto e que seu parceiro não foi submetido a\ntratamento, pois seu VDRL foi não-reator. De acordo com as normas do Ministério da Saúde, além\nde colher VDRL da mãe, está indicado, nessa situação, considerar o tratamento da mãe:","options":{"A":"Inadequado e iniciar tratamento penicilínico do recém-nascido sem necessidade de realizar\nqualquer exame complementar.","B":"Adequado e iniciar tratamento penicilínico do recém-nascido apenas se o VDRL for positivo em\ndiluição maior ou igual à da mãe.","C":"Inadequado, realizar hemograma, punção lombar, radiografia de ossos longos e VDRL do\nrecém- nascido e iniciar tratamento penicilínico.","D":"Adequado e iniciar tratamento penicilínico do recém-nascido apenas se o VDRL da mãe, colhido\nnesse momento, for positivo em diluição >1/8.","E":"Inadequado realizar hemograma e VDRL. Se estiverem normais, fazer 1 dose de penicilina G\nbenzatina e dar alta ao paciente."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-199597","number":"199597","sourceNumber":"199597","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A gestante chegou em período expulsivo e o obstetra o chama pra assistir ao\nRecém-Nascido (RN). Ao nascer deve-se avaliar a vitalidade do RN por meio das seguintes\nperguntas segundo as Diretrizes da Reanimação Neonatal 2015:","options":{"A":"RN a termo?; RN com bom tônus muscular?; RN chorando ou respirando?","B":"RN pré-termo?; Líquido amniótico meconial?; RN chorando ou respirando?","C":"RN com gasping ou apneia?; Líquido amniótico meconial?; Frequência cardíaca > 100 bpm?","D":"RN respirando?; RN com bom tônus muscular?; Líquido amniótico meconial?"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196757","number":"196757","sourceNumber":"196757","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de mãe com 7 consultas pré natais, sem história de infecção urinária,\nhipertensão arterial ou diabetes durante a gestação, sorologias de prá natal: HIV não reagente no\nprimeiro e no terceiro trimestre, Toxoplasmose IgM negativo e IgG positivo no primeiro trimestre,\nRubéola IgM negativo e IgG positivo no primeiro trimestre, Citomegalovírus IgM negativo e IgG\npositivo no primeiro trimestre, VDRL 1:64 no primeiro trimestre e 1:32 no último trimestre, com\nhistória de tratamento com 3 doses de penicilina benzatina no primeiro trimestre de gestação. Qual\na conduta em relação ao recém nascido?","options":{"A":"Rx de ossos longos, hemograma, punção lombar e avaliar tratamento conforme resultado dos\nexames","B":"Penicilina benzatina dose única e internação hospitalar","C":"Penicilina procaína dose única e avaliação ambulatorial","D":"Penicilina benzatina dose única e alta hospitalar, sem necessidade de reavaliação"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-196767","number":"196767","sourceNumber":"196767","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O treinamento e padronização da assistência ao recém nascido na sala de parto é de\nsuma importância para garantir a redução de\ndanos caso haja algum desvio da normalidade\nesperada para o parto via vaginal. Ao imediato nascimento do bebê o Pediatra que presta\nassistência na sala de parto responde a três perguntas pré programadas e então inicia ou não sua\nintervenção. Caso a uma das três perguntas a resposta seja não, qual o próximo passo?","options":{"A":"prover calor, posicionar a cabeça em leve extensão e ventilar com balão valva máscara com ar\ncomprimido","B":"prover calor, posicionar a cabeça em leve extensão, aspirar boca e narinas, se necessário, e\nsecar","C":"prover calor, posicionar a cabeça em leve extensão, aspirar boca e narinas, ventilar com balão\nvalva máscara com ar comprimido e secar","D":"prover calor, posicionar a cabeça em leve extensão, aspirar boca e narinas, secar e ventilar com\nbalão valva máscara com ar comprimido"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-215148","number":"215148","sourceNumber":"215148","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante, CTP, de 40 anos, encontra-se na 30ª semana de gestação e devido a uma\ninfecção do trato urinário entra em trabalho de parto. O Prematuro de 30 semanas é encaminhado\na UTI neonatal, onde é estabilizado clinicamente. O pediatra deverá iniciar a nutrição desse\nrecém-nascido. Nesse caso, é CORRETO afirmar que:","options":{"A":"O prematuro deverá receber preferencialmente fórmula nutritiva.","B":"O prematuro deverá receber somente hidratação e reposição de eletrólitos.","C":"O alimento mais apropriado é o leite humano pasteurizado proveniente de um conjunto de mães\nde prematuros de idades pós-natal diversas, via\nenteral.","D":"O alimento mais apropriado é o leite da própria mãe de forma oral.","E":"O alimento mais apropriado é o leite da própria mãe, associado a reposições hidroeletrólicas e\nproteicas."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-187504","number":"187504","sourceNumber":"187504","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido com 12 horas de vida, suga bem seio materno, mãe com pouco\ncolostro. Nasceu a termo, AIG, com peso de 3000\ngramas, com APGAR de 9/9, e está em bom\nestado geral, com exame físico normal. Mãe relata pré-natal de 9 consultas, sem intercorrencias, e\ncom glicemias de jejum e teste oral de tolerância à glicose normais. Qual a conduta mais\nadequada?","options":{"A":"Prescrever fórmula láctea como complemento ao aleitamento materno.","B":"Incentivar o aleitamento materno, verificar glicemia capilar periférica do recém nascido, e\nprescrever fórmula láctea como complemento ao\naleitamento caso glicemia menor que 60 mg/dl.","C":"Incentivar o aleitamento materno, verificar glicemia capilar periférica do recém nascido, e\nprescrever fórmula láctea como complemento ao\naleitamento caso glicemia menor que 55 mg/dl.","D":"Incentivar o aleitamento materno, verificar glicemia capilar periférica do recém nascido, e\nprescrever fórmula láctea como complemento ao\naleitamento caso glicemia menor que 50 mg/dl.","E":"Incentivar o aleitamento materno exclusivo e não verificar glicemia capilar periférica do\nrecém-nascido."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-174362","number":"174362","sourceNumber":"174362","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido prematuro, com 33 semanas de idade gestacional, pesando 1.600 g, é\natendido pelo pediatra em sala de parto. Quais os primeiros passos a serem adotados?","options":{"A":"Assegurar a temperatura na sala de parto entre 23-26ºc, após clampeamento do cordão\numbilical, recém-nascido é levado a fonte de calor radiante, posiciona-se a cabeça do\n\nrecém-nascido em leve extensão, aspiração das narinas e boca se presença de secreção, secar o\npaciente e retirar compôs úmidos. Avaliação da FC, respiração e Tônus muscular. Todo\nprocedimento deve ser realizado em 60 segundos.","B":"Assegurar a temperatura na sala de parto entre 23-26ºc, após clampeamento do cordão\numbilical, recém-nascido é levado a fonte de calor\nradiante, posiciona-se a cabeça recém-nascido\nem leve extensão, aspiração das narinas e boca se presença de secreção, secar o paciente e\nretirar compôs úmidos. Avaliação da FC, respiração e Tônus muscular. Todo procedimento deve\nser realizado em 30 segundos.","C":"Assegurar a temperatura na sala de parto entre 23-26ºc, após clampeamento do cordão\numbilical, recém-nascido é levado a fonte de calor\nradiante, envolto em saco plástico transparente,\ntouca dupla, posiciona-se a cabeça do recém-nascido em leve extensão, aspiração das narinas e\nboca se secreção, e avaliação da FC, respiração e Tônus muscular. Todo procedimento deve ser\nrealizado em 30 segundos.","D":"Assegurar a temperatura na sala de parto entre 23-26ºc, após clampeamento do cordão\numbilical, recém-nascido é levado a fonte de calor radiante, posiciona-se a cabeça do\n\nrecém-nascido em leve extensão, inicia CPAP nasal com ventilador manual em T, e encaminhar a\nUTI neonatal para receber cuidados intensivos.","E":"Assegurar a temperatura na sala de parto entre 23-26ºc, após clampeamento do cordão\numbilical, recém-nascido é levado a fonte de calor radiante, posiciona-se a cabeça do\n\nrecém-nascido em leve extensão, realizar intubação orotraqueal e realizar uma dose de surfactante,\nmonitorização continua e encaminhamento à UTI neonatal acoplado ao ventilador Manuel em T."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-174370","number":"174370","sourceNumber":"174370","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém nascido, 36 semanas de idade gestacional, pesando 2000 g, é atendido pelo\npediatra em sala de parto, apresentando FC >100bpm, respiração rítmica, retração esternal,\nbatimento de asa de nariz e gemido expiratório. A Conduta a ser adotada, neste caso, é:","options":{"A":"Aplicar CPAP com ventilador manual em T e máscara facial.","B":"Iniciar ventilação com pressão positiva, com balão autoinflável e máscara.","C":"Iniciar ventilação com pressão positiva com ventilador mecânico manual em T e tubo traqueal.","D":"Obsetvar por 10 minutos e, se não melhorar, oferecer oxigênio.","E":"Aplicar CPAP com balão autoinflável e tubo traqueal."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-187509","number":"187509","sourceNumber":"187509","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Os neonatos prematuros têm maior risco de hemorragia craniana peri-intraventricular.\nQual o método de escolha para o diagnóstico\ndessa patologia?","options":{"A":"Raio X de crânio.","B":"Ultrassonografia craniana Transfontanelar.","C":"Tomografia computadorizada de Crânio.","D":"Cintilografia de Crânio.","E":"Punção ventricular."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-187511","number":"187511","sourceNumber":"187511","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Segundo as diretrizes do Programa de Reanimação Neonatal, qual método de\ndeterminar a frequência cardíaca parece ser o\nmais indicado para a condução da reanimação em\nsala de parto?","options":{"A":"A palpação do cordão umbilical.","B":"A ausculta do precórdio com o estetoscópio.","C":"A detecção do sinal de pulso pela oximetria.","D":"A detecção da atividade elétrica do coração pelo monitor cardíaco.","E":"A palpação do pulso radial."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-174356","number":"174356","sourceNumber":"174356","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, 40 semanas de idade gestacional, mãe primípara, sem\nintercorrências no pré-natal. Nasceu de parto vaginal em boas condições de vitalidade, pesando\n3500 g, sendo encaminhado ao alojamento conjunto. No primeiro dia de vida apresentou\ndificuldade para amamentar e icterícia com 15 horas de vida. Ao exame físico, apresenta icterícia\n\n+/4+ em face e parte superior do tronco, restante do exame normal. Baseado no quadro clínico\ndescrito, o diagnóstico mais provável e a conduta correta são:","options":{"A":"Icterícia fisiológica; suplementação com fórmula láctea de partida e fototerapia.","B":"Icterícia fisiológica; tipagem sanguínea e bilirrubina total e frações e fototerapia.","C":"Icterícia hemolítica; Coombs do recém-nascido, dosar substância redutora na urina e fototerapia.","D":"Icterícia hemolítica; Coombs da mãe, suplementação com leite humano de banco de leite e\nfototerapia.","E":"Icterícia hemolítica; tipagem sanguínea, Coombs da mãe e do recém-nascido, bilirrubina total e\nfrações e fototerapia."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-174361","number":"174361","sourceNumber":"174361","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Para efeito de vigilância epidemiológica, toda mãe com VDRL positivo na gravidez, e\nque não tenha recebido tratamento adequado,\nterá seu recém-nascido com diagnóstico como\nportador de sífilis congênita:","options":{"A":"Se ele apresentar VDRL positivo e radigráfia de ossos longos alterada e ou alterações\nclínico-laboratoriais.","B":"Se ele apresentar VDRL com titulação maior que a da mãe.","C":"Independente de sua condição clínica e de seu VDRL.","D":"Se ele apresentar VDRL positivo com qualquer titulação.","E":"Se ele apresentar VDRL positivo > 1:4 e tiver alteração clínica ou laboratorial compatível com a\ndoença."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-188028","number":"188028","sourceNumber":"188028","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Gestante portadora de cardiopatia deu entrada no pronto socorro obstétrico com relato\nde redução de movimentos fetais há 24 horas.\nApós avaliação obstétrica foi realizado parto\ncesariana de urgência sob anestesia geral de recém-nascido a termo, 40,3 semanas, bolsa rota no\nato com líquido amniótico meconial ++/4+, apresentação pélvica. Após recepcionar o\n\nrecém-nascido e efetuar os passos iniciais de reanimação, você percebe que o paciente se\nencontra pálido, em apneia, com frequência\ncardíaca de 50 bpm e hipotonia generalizada. Qual é a\nconduta a ser tomada no recém-nascido?","options":{"A":"Administrar o antagonista dos opióides - naloxone.","B":"Realizar aspiração traqueal sob visualização direta.","C":"Iniciar ventilação com pressão positiva.","D":"Intubar e administrar adrenalina endotraqueal.","E":"Iniciar massagem cardíaca externa."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-172813","number":"172813","sourceNumber":"172813","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Lactente de 2 meses é atendido no ambulatório de pediatria com história de choro\npersistente principalmente ao manuseio, ganho de\npeso inadequado, adenomegalia generalizada,\nhepatoesplenomegalia e palidez cutâneo-mucosa. A acompanhante desconhece a história\ngestacional. O diagnóstico mais provável é:","options":{"A":"Toxoplasmose congênita.","B":"Sífilis congênita.","C":"Citomegalovírus.","D":"Doença metabólica óssea."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-172750","number":"172750","sourceNumber":"172750","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido de 36 semanas de idade gestacional, necessitou de ventilação com\npressão positiva a 21% na sala de parto. No\nquinto minuto de vida, apresentou queda de satuação\naté 60%. Qual a conduta mais adequada?","options":{"A":"Aquecer e reavaliar após 10 minutos.","B":"Iniciar oxigenioterapia no CPAP nasal a 40%.","C":"Manter a saturação de O? em torno de 98% na sala de parto.","D":"Certificar se a ventilação com pressão positiva está sendo realizada com técnica correta."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-172556","number":"172556","sourceNumber":"172556","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN nascido de cesáreo, devido pré eclampsia, 37 semanas. No primeiro minuto:\nChorou forte, movimentos ativos, FC 115 bpm,\ncianose central. Foi aquecido, examinado, sem\nanormalidades, no quinto minuto permanece apenas cianose em extremidades. O APGAR desse\nRN:","options":{"A":"8/9","B":"8/10","C":"7/10","D":"6/9"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-149130","number":"149130","sourceNumber":"149130","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recentemente no Brasil em virtude das Olimpíadas no Rio de Janeiro e pelo\nsurgimento e disseminação de uma série de\ncasos de infecção pelo Zika virus, um pânico\ngeneralizado no país e mundo foi propagado. Muitas coisas foram ditas sobre o assunto e nas\nquestões abaixo, identifique a alternativa que aponta uma afirmação INCORRETA sobre o assunto:","options":{"A":"Isolado pela primeira vez em 1947, o Zika permaneceu em relativa obscuridade por cerca de 70\nanos, e num espaço de cerca de 1 ano, foi introduzido no Brasil, disseminando-se intensa e\nrapidamente no país e pelas Américas.","B":"O Zika vírus se tornou a doença infecciosa com maior ligação à anormalidades no\ndesenvolvimento fetal decoberta em mais de meio século, criando um alarme na Organização\nMundial de Saúde.","C":"Com os dados disponíveis até o momento é precipitado afirmar haver uma relação causal entre\no Zika vírus e a microcefalia, permanecendo\nainda apenas como uma forte suspeita.","D":"O primeiro grande surto de Zika foi detectado em Salvador / Bahia no ano de 2015. Nesse\nmesmo ano foram relatados mais de 4000 casos\nde microcefalia no Brasil e uma possível relação\ncausal com o Zika vírus foi estabelecida inicialmente.","E":"Apesar da taxa de infecção do Zika vírus na Bahia não poder ser precisamente estimada com os\ndados disponíveis, é seguramente possível\nafirmar que há uma forte correlação entre a infecção\npelo Zika vírus no primeiro trimeste de gestação e o risco de microcefalia."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-155444","number":"155444","sourceNumber":"155444","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo com peso ao nascer de 3400 g inicia icterícia com 20 horas de\nvida, sem apresentar outras alterações ao exame físico. A tipagem sanguínea materna é O\nnegativo e a do recém-nascido, A positivo. Coombs-direto: negativo. A hipótese diagnóstica é:","options":{"A":"Icterícia fisiológica.","B":"Doença hemolítica pelo sistema ABO.","C":"Doença hemolítica pelo sistema Rh.","D":"Doença hemolítica pelos sistemas Rh e ABO.","E":"Deficiência de glicose-6-fosfato desidrogenase."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-148577","number":"148577","sourceNumber":"148577","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O escore de Apgar é muito utilizado para avaliar o recém-nascido após o parto. Qual a\nindicação do Apgar?","options":{"A":"O escore de Apgar auxilia na identificação de pacientes com paralisia cerebral.","B":"A nota do Apgar no primeiro minuto prediz a evolução neurológica da criança.","C":"O escore de Apgar avalia de modo sistemático o recém-nascido após o parto. No primeiro\nminuto pode assinalar a necessidade de ressuscitação.","D":"O escore de Apgar nos auxilia na identificação da idade gestacional do recém-nascido.","E":"O escore de Apgar nos auxilia na identificação de icterícia neonatal."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-148587","number":"148587","sourceNumber":"148587","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"São considerados recém-nascidos de alto risco:","options":{"A":"Crianças com peso inferior a 2.500 g são considerados recém-nascidos de alto risco. Pesos\nsuperiores são considerados fator de proteção.","B":"Nascimentos antes de 37 semanas são considerados de alto risco. Nascimentos após 37\nsemanas são considerados fator de proteção.","C":"Pacientes Pequenos para a Idade Gestacional (PIG) são considerados recém-nascidos de alto\nrisco. Os pacientes Adequados para a Idade Gestacional (AIG) e Grande para a Idade Gestacional\n(GIG) são considerados fator de proteção.","D":"Crianças com peso inferior a 2.500 g ou superior a 4.000 g são considerados recém-nascidos de\nalto risco.","E":"Nascimentos antes de 32 semanas e acima de 40 semanas são considerados de alto risco."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-149131","number":"149131","sourceNumber":"149131","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo com 16 dias de vida, em aleitamento materno exclusivo, é\nlevado a consulta devido a quadro de\nicterícia. Exame físico: corado, ictérico até zona III de\nKramer, fígado palpável a 1cm do RCD, Traube livre. Exames laboratoriais (colhidos em regime de\nurgência): BT: 15,1mg/dl, BI: 14,8mg/dl, Ht: 47%. As hipóteses diagnósticas que devem ser\nconsideradas incluem?:","options":{"A":"atresia de vias biliares e hipotireoidismo","B":"Icterícia do leite materno e hipotireoidismo","C":"icterícia fisiológica e icterícia do leite materno","D":"icterícia fisiológica e incompatibilidade materno-fetal","E":"incompatibilidade materno-fetal e atresia de vias biliares"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-148551","number":"148551","sourceNumber":"148551","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A Doença das Membranas Hialinas ou Síndrome de Desconforto Respiratório é uma\ndoença frequente e fundamentalmente\nrelacionada à deficiência primária de surfactante. Observe\nas afirmativas abaixo e marque a sentença correta a respeito da Doença das Membranas Hialina no\nrecém-nascido.","options":{"A":"A Doença das Membranas Hialinas ocorre principalmente em recém-nascido pós-termo.","B":"A Doença das Membranas Hialinas tem incidência maior em mães com hipertensão crônica ou\nhipertensão associada à gestação.","C":"A gestação múltipla é um fator de proteção para a Doença das Membranas Hialinas.","D":"O uso antenatal de corticoide aumenta o risco de Doença das Membranas Hialinas.","E":"60-80% de todos os recém-nascidos com idade gestacional menor que 28 semanas apresentam\nDoença das Membranas Hialina."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-148584","number":"148584","sourceNumber":"148584","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Observe as frases sobre icterícia na infância e assinale a alternativa que contém a\nresposta correta: I- Sepse neonatal é possível causa de icterícia com hiperbilirrubinemia indireta\n(não conjugada). II- Colecistite em crianças pode causar icterícia. III- O aleitamento materno pode\ncausar icterícia.","options":{"A":"As alternativas I e II estão corretas.","B":"As alternativas II e III estão corretas.","C":"Todas as alternativas estão corretas.","D":"Somente a alternativa II está correta.","E":"Todas as alternativas estão erradas."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-148592","number":"148592","sourceNumber":"148592","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Os sucessos na prevenção da transmissão vertical, principal mecanismo de aquisição\ndo HIV em pediatria, levaram a uma\nsignificativa redução dos casos novos, porém, com\nestabilização nos últimos anos. Observe as afirmativas abaixo e marque a sentença incorreta a\nrespeito de infecção por HIV na infância.","options":{"A":"Em todos os recém-nascidos de mulheres infectadas pelo HIV recomenda-se a não\namamentação e a substituição do leite materno por fórmula infantil após aconselhamento.","B":"Todos os recém-nascidos de mulheres infectadas pelo HIV devem receber profilaxia com\nantirretroviral.","C":"No diagnóstico de crianças menores de 18 meses de idade, resultados detectáveis de carga viral\nabaixo de 5.000 cópias/mL devem ser cuidadosamente analisados e repetidos por causa da\npossibilidade de um resultado falso-positivo.","D":"Uma criança menor de 18 meses de idade com duas cargas virais indetectáveis, sendo a\nsegunda após quatro meses de idade, é\nconsiderada não infectada pelo HIV.","E":"O parto vaginal e o tratamento da mãe HIV positiva com antirretrovirais reduz o risco de\ntransmissão do vírus para o bebê."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-162536","number":"162536","sourceNumber":"162536","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A retinopatia da prematuridade é uma das principais causas de cegueira e baixa visão\ninfantil. São considerados fatores que podem contribuir para o desenvolvimento da retinopatia da\nprematuridade, EXCETO:","options":{"A":"Oxigenoterapia.","B":"Transfusão sanguínea.","C":"Hiperbilirrubinemia.","D":"Prematuridade.","E":"Baixo peso ao nascer."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-162543","number":"162543","sourceNumber":"162543","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido com 25 dias de vida é levado ao pediatra para consulta de puericultura.\nAo exame físico, está afebril, em bom estado\ngeral, e tem icterícia colestática, hepatomegalia, e\nfezes acólicas. A mãe tem exames do pré-natal negativos para HIV, toxoplasmose, rubéola,\ncitomegalovírus, hepatite B, herpes e sífilis. Nasceu a termo, sem intercorrências. Qual o\ndiagnóstico mais provável?","options":{"A":"Galactosemia.","B":"Atresia de vias biliares.","C":"Tirosinemia.","D":"Sepse.","E":"Cisto de colédoco."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-155423","number":"155423","sourceNumber":"155423","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação à avaliação genético-clínica do recém-nascido, podemos afirmar, EXCETO:","options":{"A":"São suportes para o diagnóstico final e tomada de condutas: anamnese e história familiar.","B":"A presença de pelo menos 3 malformações maiores, associadas ou não a defeitos menores,\ncaracterizam as síndromes malformativas.","C":"Prega palmar transversal única bilateral pode ser encontrada num recém-nascido saudável, de\ncariótipo normal.","D":"A presença de três anomalias menores indica a pesquisa de anomalias maiores.","E":"O cariótipo é essencial para conclusão diagnóstica da maioria dos quadros dismórficos."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-155424","number":"155424","sourceNumber":"155424","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual a orientação correta, na alta hospitalar a ser dada à mãe de um recém-nascido\ncom teste de emissão otoacústica (EOA) alterado,\nsendo ele um bebê sem indicadores de risco\npara perda auditiva?","options":{"A":"Reteste com 6 meses de vida.","B":"Reteste no período de 30 dias.","C":"Reteste com 1 ano de vida.","D":"Reteste com 9 meses de vida.","E":"Encaminhar imediatamente para um otorrinolaringologista."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-162515","number":"162515","sourceNumber":"162515","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre a citomegalovirose na gestação, podemos afirmar, EXCETO:","options":{"A":"De forma geral a realização rotineira de testes sorológicos para detecção de anticorpos anti-\ncitomegalovirus durante o pré-natal não está indicada para a população brasileira.","B":"A grande maioria das gestantes é assintomática durante a primo-infecção pelo citomegalovírus.","C":"Praticamente todas as gestantes são assintomáticas durante a recorrência pelo citomegalovírus.","D":"A transmissão vertical pode ocorrer durante a vida fetal, no momento do parto ou durante o\naleitamento materno.","E":"Em casos de soro positividade materna para o citomegalovírus, o aleitamento materno não é\ncontraindicado, devendo apenas ser suspenso temporariamente na infecção aguda."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-155341","number":"155341","sourceNumber":"155341","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em relação às infecções congênitas no recém-nascido, é CORRETO afirmar que:","options":{"A":"A infecção por citomegalovírus pode ser transmitida ao concepto em qualquer período da\ngravidez.","B":"A infecção por citomegalovírus não apresenta quadros graves no período neonatal.","C":"A sífilis pode ser transmitida ao concepto somente no último trimestre da gestação.","D":"A presença de rubéola congênita no recém-nascido não requer isolamento do mesmo.","E":"A infecção fetal pelo vírus da rubéola ocorre principalmente no último trimestre da gestação."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-155351","number":"155351","sourceNumber":"155351","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A sífilis congênita é, ainda, um importante problema de saúde pública, podendo ser\nprevenida. O tratamento da gestante é considerado eficaz ao seu recém-nascido se concluído até\nquantos dias antes de ocorrer o parto?","options":{"A":"15.","B":"30.","C":"40.","D":"45.","E":"60."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-137808","number":"137808","sourceNumber":"137808","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido na sala de parto, a termo, liquido amniótico claro, nasce em apneia\ne hipotônico. Ordene os procedimentos que definem\ncorretamente a sequência de atendimento\ninicial: (1) Aspirar vias aéreas se necessário; (2) Secar e remover os campos úmidos; (3) Avaliar\nrespiração e frequência cardíaca; (4) Prover calor; (5) Posicionar a cabeça. A ordem CORRETA\ndos números de cima para baixo é:","options":{"A":"1-2-3-4-5","B":"2-1-4-3-5","C":"4-5-1-2-3","D":"1-5-2-4-3","E":"4-5-2-1-3"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-137823","number":"137823","sourceNumber":"137823","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com relação à icterícia neonatal, assinale as associações corretas: 1- Hipotireoidismo ;\n2- Icterícia fisiológica ; 3- Atresia de vias biliares; 4- Incompatibilidade sanguínea; 5- Leite\nhumano;\nA- Icterícia com colúria; B- Icterícia precoce; C- Icterícia prolongada; D- Icterícia Tardia materno\nfetal; E- Icterícia sem colúria.","options":{"A":"1A; 2B; 3C.","B":"1C;2E;4B.","C":"1B; 3E; 4A.","D":"3D; 4C; 5C.","E":"1D; 2A; 5C."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-137815","number":"137815","sourceNumber":"137815","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Em um RN com 36 horas de vida e diagnóstico de toxoplasmose congênita\ncomprovada, a fundoscopia mostra\ncoriorretinite macular bilateral em atividade. O hemograma\napresenta 850 neutrófilos/mm³ e bilirrubina total de 9,0 mg/dl, com bilirrubina direta de 0,7 mg/dl.\nQual seria o esquema terapêutico mais adequado para esta criança?","options":{"A":"Sulfadiazina, pirimetamina, ácido folínico.","B":"Espiramicina e corticosteroides.","C":"Sulfadiazina, pirimetamina, ácido folínico e corticosteroide.","D":"Espiramicina alternada com sulfadiazina + pirimetamina + ácido folínico.","E":"Cirurgia refrativa e sulfadiazina."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-137840","number":"137840","sourceNumber":"137840","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, de parto vaginal, Apgar 1º min: 8, 5ºmin: 9, realizado oximetria\nde pulso (?teste do coraçãozinho?) com 30\nhoras de vida, sendo repetido após uma hora. SatO2\nem membro superior direito: 98% e em membro inferior direito: 93%. A conduta indicada é:","options":{"A":"Ecocardiograma.","B":"Indometacina IV.","C":"Oferta de oxigênio em hood (60%).","D":"Teste terapêutico com óxido nítrico.","E":"Alta hospitalar e consulta ambulatorial com cardiopediatra."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-126894","number":"126894","sourceNumber":"126894","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O rastreamento de doenças no período neonatal é mundialmente aceito como prática\nrelevante de saúde pública. Quanto à triagem neonatal, assinale a alternativa INCORRETA.","options":{"A":"O exame deve ser colhido entre 30 e 40 dias de vida.","B":"A suspeita de hipotireoidismo congênito é pesquisada através da dosagem de TSH.","C":"A dosagem de tripsina permite o diagnóstico de fibrose cística.","D":"A dosagem do hormônio 17-hidroxiprogesterona permite o diagnóstico de hiperplasia adrenal\ncongênita."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-126918","number":"126918","sourceNumber":"126918","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN de T.G.C., sexo masculino, 39 semanas, nasceu de parto vaginal, apgar 9/10.\nAtualmente está com 36 horas de vida. Ao\nexame: Acianótico, FC=132bpm, FR=43irpm, PA=80/60\nmmHg. Peso ao nascer = 2870g. Estatura ao nascer = 49cm. Perímetro cefálico ao nascer = 34 cm.\nAusculta cardíaca normal, ausculta respiratória normal. Abdômen flácido, sem visceromegalias.\n\nAvaliação do sistema nervoso central normal. Sobre à classificação do Recém-Nascido (RN) quanto\nà idade gestacional, peso, estatura e\nperímetro cefálico, assinale a alternativa CORRETA.","options":{"A":"RN a termo, PIG, estatura normal.","B":"RN pré-termo porque tem menos de 40 semanas.","C":"RN pequeno para a idade gestacional, pré-termo.","D":"RN AIG, estatura normal, perímetro cefálico normal."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131652","number":"131652","sourceNumber":"131652","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Assinale a opção errada, com relação à reanimação neonatal:","options":{"A":"Recém-nascido a termo, que nasce chorando, com respiração rítmica e regular, com tônus\nmuscular em flexão, e sem líquido amniótico meconial, não necessita de nenhuma manobra de\nreanimação.","B":"Recomenda-se que o RN a termo, saudável e com boa vitalidade ao nascer seja posicionado no\nnível da placenta por 1 a 3 minutos, antes de clampear o cordão umbilical.","C":"Após o clampeamento do cordão, o recém-nascido que nasce com peso inferior a 1500 gramas\né recepcionado em campos aquecidos, colocado sob\ncalor radiante, e logo a seguir é envolvido em\nfilme plástico transparente de polietileno","D":"Todo RN com líquido amniótico meconial espesso logo após o nascimento deve ser submetido à\naspiração traqueal.","E":"A avaliação da coloração da pele e mucosas do recém-nascido não é mais utilizada para decidir\nprocedimentos na sala de parto."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131654","number":"131654","sourceNumber":"131654","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, que nasceu de parto normal, sem intercorrências. Com 12\nhoras de vida, iniciou febre,\nhipoatividade, taquipneia e desconforto respiratório. Teve piora clínica\nrápida, evoluindo com insuficiência respiratória. Tratando-se de quadro infeccioso, o agente\netiológico mais provável é:","options":{"A":"Candida albicans.","B":"Staphylococcus aureus.","C":"Pseudomonas aeruginosa.","D":"Enterobacter.","E":"Streptococcus agalactiae."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131656","number":"131656","sourceNumber":"131656","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com relação ao teste do reflexo vermelho, assinale a alternativa errada.","options":{"A":"É uma ferramenta de rastreamento de alterações que possam comprometer a transparência dos\nmeios oculares.","B":"Deve ser realizado utilizando um oftalmoscópio direito, em sala escurecida, não havendo\nnecessidade de colírios.","C":"Em caso de reflexo alterado ou suspeito, a criança deve ser encaminhada ao oftalmologista.","D":"Devem ser submetidos ao teste do reflexo vermelho somente os recém-nascidos com peso\nmenor que 2000 gramas ao nascer.","E":"Dentre as doenças que o teste do reflexo vermelho pode detectar, estão a Catarata, o\nGlaucoma, a Toxoplasmose e o Retinoblastoma."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-126927","number":"126927","sourceNumber":"126927","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN de S.O.N., primeira filha, sexo feminino, nascida a termo. A mãe tem 24 anos,\nescolaridade primária, e fez pré-natal com 5\nconsultas. Exames realizados no pré-natal: Anti-HIV\nnegativo; HBsAg negativo, VDRL não reator. Toxoplasmose: exame do primeiro trimestre gestação:\nIgG negativo, IgM negativo; terceiro trimestre gestação: IgG positivo; IgM positivo. Considerando o\ncaso descrito, assinale a alternativa CORRETA.","options":{"A":"A mãe teve uma viragem sorológica para toxoplasmose entre o primeiro e o terceiro trimestres\nde gestação, significando reativação da doença.","B":"A mãe teve uma viragem sorológica para toxoplasmose entre o primeiro e o terceiro trimestres\nde gestação, significando contaminação pelo\ntoxoplasma.","C":"O teste de avidez para IgG, deve ser feito, para confirmar a infecção por toxoplasmose na mãe.","D":"O recém-nascido não tem risco de toxoplasmose, porque a doença ocorreu no final da gestação."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131659","number":"131659","sourceNumber":"131659","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com relação à convulsão febril simples, assinale a alternativa errada.","options":{"A":"Pode ser focal ou generalizada.","B":"Dura no máximo 15 minutos.","C":"Vem acompanhada de febre de 38 graus Celsius ou maior.","D":"Não recorre num período de 24 horas.","E":"Não causa na criança efeitos adversos a longo prazo."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-131660","number":"131660","sourceNumber":"131660","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"São sinais clínicos frequentes da meningite bacteriana no período neonatal, exceto:","options":{"A":"Respiração irregular.","B":"Hipotonia, hiporreflexia.","C":"Rigidez de nuca.","D":"Tremores, convulsões.","E":"Irritabilidade, letargia."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-127162","number":"127162","sourceNumber":"127162","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A reanimação neonatal deve ser realizada de forma ativa e seguindo recomendações\nmédicas baseadas na melhor evidência científica.\nQual alternativa abaixo apresenta a sequência\nCORRETA referente aos passos iniciais da reanimação?","options":{"A":"Secar e remover os campos úmidos, colocar o recém-nascido sob fonte radiante, posicionar a\ncabeça, aspirar narinas e boca (se excesso de secreções).","B":"Aspirar narinas e boca (se excesso de secreções), secar e remover os campos úmidos, colocar\no recém-nascido sob fonte radiante e posicionar a\ncabeça.","C":"Colocar o recém-nascido sob fonte radiante, posicionar a cabeça, aspirar narinas e boca (se\nexcesso de secreções), secar e remover os campos úmidos.","D":"Colocar o recém-nascido sob fonte radiante, secar e remover os campos úmidos, posicionar a\ncabeça, aspirar narinas e boca (se excesso de secreções).","E":"A ordem das manobras de reanimação deverá levar em conta a vitalidade do recém-nascido."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-127168","number":"127168","sourceNumber":"127168","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Correlacione a primeira coluna, dos agentes etiológicos, com a segunda, que se refere\nàs manifestações clínicas mais significativas da\ninfecção congênita, e escolha a resposta\nCORRETA: I- Rubéola; II- Citomegalovírus; III- Toxoplasmose; IV- Vírus herpes simples; V- Sífilis.\n(\n\n) Vesículas e conjuntivite; ( ) Microcefalia e calcificação intracraniana; ( ) Catarata e\ncardiopatia\ncongênita; ( ) Hidrocefalia e coriorretinite; ( ) Exantema maculopapular e lesão óssea.","options":{"A":"III ? II ? IV ? I ? V.","B":"V ? III ? I ? II ? IV.","C":"IV ? II ? I ? III ? V.","D":"V ? III ? I ? IV ? II.","E":"IV ? II ? III ? V ? I."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-100961","number":"100961","sourceNumber":"100961","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Neonato apresentando torcicolo congênito pode ter associação de outras deformidades\ncomo a alteração da coluna cervical. Além\ndessa associação deve-se pesquisar também:","options":{"A":"Rim único.","B":"Artrogripose.","C":"Cardiopatia congênita.","D":"Osteogênese imperfecta.","E":"Displasia congênita do quadril."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-100953","number":"100953","sourceNumber":"100953","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido com 44 horas de vida, a termo, em alojamento conjunto, parto normal,\nraça negra, aleitamento materno exclusivo,\nadequado para idade gestacional, encontra-se ictérico\naté zona II de Kramer. Mãe O positivo e recém-nascido A positivo. Qual a melhor conduta?","options":{"A":"Iniciar fototerapia imediatamente.","B":"Liberar o recém-nascido e tranquilizar a família.","C":"Dosar a bilirrubina e dar alta com acompanhamento já marcado.","D":"Liberar o recém-nascido para marcar consulta em sua unidade de saúde.","E":"Iniciar água nos intervalos das mamadas."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-101009","number":"101009","sourceNumber":"101009","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Durante a atenção, na sala de parto normal de uma gestante de risco habitual, foi\nobservado um líquido amniótico com grumos, um recém-nascido que chorou logo, frequência\ncardíaca, respiratória e tônus normais. A conduta conforme o Programa de Reanimação Neonatal\né:","options":{"A":"Aquecer, posicionar vias aéreas, secar e estimular o recém-nascido nesta ordem.","B":"Deixar com a mãe provendo seu aquecimento, mantendo suas vias aéreas pérvias, secando e\npermitindo o contato ao seio materno.","C":"Banhar imediatamente e deixar com a mãe já vestido.","D":"Deixar em contato pele a pele com a mãe na sala climatizada a 20°C.","E":"Secar, aquecer, estimular e posicionar vias aéreas nesta ordem."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-106374","number":"106374","sourceNumber":"106374","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido com hidrocefalia, coriorretinite e calcificações cerebrais difusas\nprovavelmente é portador de:","options":{"A":"citomegalovírus.","B":"rubéola congênita.","C":"toxoplasmose.","D":"sífilis congênita.","E":"listeriose."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-106380","number":"106380","sourceNumber":"106380","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido a termo, no quarto dia de vida, em aleitamento materno exclusivo,\napresenta bilirrubina total de 10 mg/dl. O grupo\nsanguíneo materno é ?A? RH positivo, e o RN é\n\n?0? RH positivo. Sua conduta diante desse caso é:","options":{"A":"dar alta hospitalar ao RN e manter em aleitamento materno exclusivo.","B":"dar alta hospitalar ao RN e substituir o aleitamento materno por fórmula láctea.","C":"manter o RN no hospital e repetir dosagem sérica de bilirrubina no dia seguinte.","D":"manter o RN no hospital e iniciar fototerapia única.","E":"manter o RN no hospital e iniciar fototerapia dupla."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-111658","number":"111658","sourceNumber":"111658","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O exame de triagem oftalmológico, onde em ambiente escuro, a luz do oftalmoscópio é\ndirecionada às pupilas do recém-nascido, permite o diagnóstico precoce de:","options":{"A":"proptose e epífora.","B":"glaucoma e alterações arteriovenosas","C":"catarata e alterações arteriovenosas.","D":"coloboma e glaucoma.","E":"catarata e retinoblastoma."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-59375","number":"59375","sourceNumber":"59375","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Com relação à doença de Hirschsprung, marque a alternativa INCORRETA:","options":{"A":"Na doença de Hirschsprung observa-se na histologia ausência dos plexos de Meissner e\nAuerbach e feixes nervosos hipertrofiados\ncom altas concentrações de acetilcolinesterase entre as\ncamadas musculares e na submucosa.","B":"O toque retal revela tônus anal normal e é usualmente seguido por eliminação explosiva de\nfezes fétidas ou gases.","C":"Uma vez que o diagnóstico esteja estabelecido, o tratamento definitivo é a intervenção\ncirúrgica.","D":"A doença de Hirschsprung deve ser suspeitada em qualquer RN, principalmente em prematuros\n(mais acometidos) com atraso na eliminação de\nfezes."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-59393","number":"59393","sourceNumber":"59393","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN com 5 dias de vida, foi levado pela mãe à maternidade em que nasceu devido\nbolhas tensas de conteúdo purulento com halo\neritematoso e bolhas rotas com descamação em\ncolarete, duas em prega do pescoço e cinco em região axilar direita, não dolorosas à palpação.\nMantendo bom estado geral, em Aleitamento Materno Exclusivo. Mãe refere parto cesáreo, bolsa\nrota no ato e nega infecção (corrimento vaginal ou infecção urinária). Pode-se afirmar:","options":{"A":"Trata-se de um caso de piodermite, essas lesões são conhecidas como periporites. São\ndecorrentes de contaminação dos orifícios e dos ductos de glândulas.","B":"O diagnóstico é, em geral, clínico, mas exames bacteriológicos podem ser realizados,\nprincipalmente para detectar a sensibilidade da cepa estafilocócica aos antibióticos.","C":"O tratamento é desnecessário, a afecção é autolimitada e desaparece espontaneamente sem\ndeixar sequelas.","D":"O quadro cutâneo pode ser acompanhado de eosinofilia sanguínea em 7 a 15% dos casos. Nos\ncasos duvidosos pode ser realizado exame\ncitológico das vesículas que revela presença de\neosinófilos."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-59415","number":"59415","sourceNumber":"59415","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"RN nascido de parto normal, 37 semanas e 3 dias. No primeiro minuto apresentou:\nbradicardia (FC < 100 bpm), flácido, sem\nmovimentos respiratórios, azul pálido e reagindo pouco.\nFoi aquecido, estimulado e feito O2 inalatório, respondeu com choro forte, FC > 100 bpm,\nmovimento ativo, cianose apenas de extremidades. O APGAR desse RN:","options":{"A":"2/9","B":"1/7","C":"2/7","D":"3/8"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-59081","number":"59081","sourceNumber":"59081","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Relacione corretamente os dados maternos com as manifestações clínicas no\nrecém-nascido e assinale a alternativa CORRETA: Doença Materna: A - Coxsackie vírus; B -\nLúpus eritematoso sistêmico; C - Rubéola; D - Diabetes mellitus. Doença Neonatal: I -\nMiocardiopatia hipertrófica; II - Bloqueio atrioventricular total; III - Miocardite congênita; IV -\nPersistência do canal arterial.","options":{"A":"A II, B II, C III, D IV","B":"A III, B IV, C I, D II","C":"A III, B II, C IV, D I","D":"A IV, B II, C III, D I","E":"A II, B I , C IV, D III"},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-59084","number":"59084","sourceNumber":"59084","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Mãe de recém-nascido de parto cesáreo, a termo, 72 horas de vida, reflexo de sucção\nnormal, encontra-se com dificuldade de amamentar por fissura mamária à direita. Produção de leite\nadequada. Qual a melhor conduta?","options":{"A":"Translactação com fórmula infantil na mama direita.","B":"Suspender totalmente a amamentação na mama direita.","C":"Ordenhar a mama direita pré-sucção e acertar a \"pega\".","D":"Manter o mamilo bem seco com protetores de algodão.","E":"Administrar metoclopramida para mãe."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-366980","number":"366980","sourceNumber":"366980","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido prematuro está na Unidade de Cuidado Intensivo Neonatal e\ndesenvolve súbito desconforto respiratório,\ncom cianose e queda da saturação de oxigênio. Qual é\na suspeita clínica mais provável?","options":{"A":"Pneumotórax.","B":"Asma bronquial.","C":"Cardiopatia congênita.","D":"Bronquiolite."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-363932","number":"363932","sourceNumber":"363932","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Quais características são indicativas de icterícia neonatal grave com necessidade de\natenção médica imediata?","options":{"A":"Olhos amarelados, letargia e recusa alimentar.","B":"Choro noturno e pele amarelada no rosto.","C":"Pele amarelada que desaparece quando pressionada.","D":"Icterícia persistente por mais de um mês."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-363931","number":"363931","sourceNumber":"363931","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O contato pele a pele do recém-nascido (RN) com sua mãe, imediatamente após o\nparto,","options":{"A":"aumenta a incidência de hipoglicemia neonatal.","B":"contribui com o aumento de casos de hemorragia materna no pós-parto.","C":"é indicado a todos os recém-nascidos (RNs) com boas condições de nascimento.","D":"provoca um maior número de casos de hipotermia neonatal."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-331989","number":"331989","sourceNumber":"331989","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre as crianças expostas ao HIV, é correto afirmar que:","options":{"A":"Nos primeiros seis meses de vida, não devem receber as vacinas oferecidas pelo PNI, mas sim\nimunológicos especiais no centro de referência.","B":"O Ministério de Saúde do Brasil recomenda que a coleta da primeira carga viral seja feita na\nsegunda semana de vida do recém-nascido.","C":"Deve-se iniciar a profilaxia para pneumonia por Pneumocystis jiroveci com o uso de\nsulfametoxazol + trimetoprim três vezes por\nsemana se a contagem de linfocitos CD4 estiver abaixo\nde 15%.","D":"As não infectadas tendem a apresentar mais infecções bacterianas e quadros mais graves se\ncomparadas a crianças não expostas ao HIV.","E":"Para o diagnóstico de infecção pelo HIV, a recomendação é que o teste anti-HIV seja feito entre\no sexto e o 12° mês de vida."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-330090","number":"330090","sourceNumber":"330090","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Há uma infecção congênita que ocorre, geralmente, por infecção genital materna. É\nmais comum sua transmissão durante o trabalho de parto ou pós-natal e chega a 50% no parto\nvaginal. Mulheres com primo-infecção geralmente são assintomáticas, enquanto aquelas com\ninfecção recidivante têm a transmissão intraparto diminuída para uma taxa de 3% a 5% pela\npresença de anticorpos preexistentes. A alternativa correspondente à infecção é:","options":{"A":"Infecção congênita por herpes simples.","B":"Sífilis congênita precoce.","C":"Infecção congênita por citomegalovírus.","D":"Rubéola congênita."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-331990","number":"331990","sourceNumber":"331990","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A toxoplasmose congênita é uma doença evitável se os cuidados com a gestante, a\ninterpretação dos exames durante o pré-natal e a indicação do tratamento forem corretos. Nesse\ncontexto, é um erro afirmar que:","options":{"A":"A transmissão vertical em gestante com infecção crônica é improvável, exceto se ela for\nimunodeprimida.","B":"A espiramicina é medicação para a profilaxia da toxoplasmose congênita.","C":"Se a IgG e a IgM forem positivas para toxoplasmose e o resultado de teste de avidez for baixo\ndurante a gravidez, isto significa que a gestante tem infecção recente e o tratamento para\ntoxoplasmose deve ser iniciado imediatamente.","D":"Havendo soroconversão durante a gravidez, é indicada a pesquisa de DNA do toxoplasma pela\ntécnica de PCR em líquido amniótico para investigar infecção fetal.","E":"Se a IgG e a IgM forem negativas para toxoplasmose no primeiro trimestre de gestação, o feto\nnão será infectado e não está indicado o tratamento da gestante."},"answer":"E","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-346440","number":"346440","sourceNumber":"346440","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual dos seguintes fatores de risco não está associado com a Doença da Membrana\nHialina?","options":{"A":"Diabetes Materno;","B":"Cesárea eletiva na ausência de trabalho de parto;","C":"Prematuridade;","D":"Doença hipertensiva específica da gravidez."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-346441","number":"346441","sourceNumber":"346441","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual das seguintes características está associada com Icterícia Neonatal Fisiológica?","options":{"A":"Icterícia desde o primeiro dia de vida;","B":"Atinge o pico de bilirrubina total dentro de 07 dias;","C":"Icterícia associada com anemia;","D":"Icterícia associada com perda de peso."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-346444","number":"346444","sourceNumber":"346444","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Criança de 08 anos, com quadro de encefalopatia hipóxico isquêmica,\ntraqueostomizada e gastrostomizada, apresenta\ndisfagia, sialorreia importante e pneumonias de\nrepetição. Qual a conduta inicial mais adequada?","options":{"A":"Antibioticoterapia profilática;","B":"Desconexão laringotraqueal;","C":"Colírio de Atropina por via oral;","D":"Observação clínica."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-342639","number":"342639","sourceNumber":"342639","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Catarata congênita, retinopatia, persistência do canal arterial e baixo peso ao nascer\nsão manifestações clínicas comumente encontradas em\nque patologia?","options":{"A":"síndrome da rubéola congênita","B":"hipotireoidismo congênito","C":"toxoplasmose congênita","D":"sífilis congênita"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-334816","number":"334816","sourceNumber":"334816","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Atualmente, qual é o exame considerado padrão ouro para o diagnóstico de atresia\nbiliar?","options":{"A":"Ultrassonografia abdominal com visualização do sinal do cordão triangular.","B":"Cintilografia hepatobiliar sem evidência de excreção intestinal do contraste.","C":"Colangiografia transoperatória.","D":"Histologia (proliferação ductal, plungs biliares, edema e arquitetura biliar preservada)."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-334819","number":"334819","sourceNumber":"334819","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Os recém-nascidos prematuros que não possuem quantidades adequadas de\nsurfactante podem desenvolver insuficiência\nrespiratória grave. Nesse cenário, o que acontece com\na tensão superficial alveolar e a complacência pulmonar, respectivamente?","options":{"A":"Reduzida; reduzida.","B":"Aumentada; aumentada.","C":"Aumentada; reduzida.","D":"Reduzida; aumentada."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-334823","number":"334823","sourceNumber":"334823","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre a triagem neonatal realizado por meio do teste do pezinho sabe-se que:","options":{"A":"qualquer alteração do exame só será valorizada se o paciente apresentar clínica compatível com\na doença testada.","B":"as doenças obrigatórias testadas são: fenilcetonúria, hipotireoidismo congênito, doença\nfalciforme, fibrose cística, hiperplasia adrenal congênita e deficiência de biotinidase.","C":"a coleta deverá ocorrer ao nascimento, antes da alta da maternidade.","D":"prematuridade e hemotransfusões não interferem no resultado do teste."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-339823","number":"339823","sourceNumber":"339823","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascida com 56 horas de vida apresenta icterícia que se iniciou com 14 horas\nde vida. Encontra-se em aleitamento materno\nexclusivo e pesando 2925 gramas. Genitora GIPIA0\nfez pré-natal sem intercorrência, classificação sanguínea da mãe. O negativo. A recém-nascida\nnasceu bem, o cordão umbilical foi clampeado 60 segundos após o nascimento, com o seguinte\npeso: 2900 gramas. Exame físico: icterícia em face, tronco e membros e palidez cutâneo-mucosa.\nClassificação sanguínea do recém-nascido A positivo com Coombs direto negativo. Restante do\nexame físico normal. A provável causa dessa icterícia deve ser","options":{"A":"incompatibilidade materno-fetal Rh.","B":"incompatibilidade materno-fetal ABO.","C":"icterícia do leite materno.","D":"clampeamento tardio do cordão umbilical.","E":"deficiência de G6PD."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-339826","number":"339826","sourceNumber":"339826","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Quando deve ser clampeado o cordão umbilical de um recém-nascido (RN) a termo\ncom boa vitalidade?","options":{"A":"Imediatamente após o nascimento.","B":"Até 60 segundos após o nascimento.","C":"Entre 1 e 3 minutos de vida do RN.","D":"Após 3 minutos de vida do RN."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-300814","number":"300814","sourceNumber":"300814","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A anemia é definida como a concentração de hemoglobina abaixo do segundo\ndesvio-padrão da média da distribuição da\nhemoglobina para população de mesma idade e sexo,\nvivendo na mesma altitude. Quanto à anemia fisiológica em prematuros, é CORRETO afirmar:","options":{"A":"É mais pronunciada, ocorrendo mais cedo e com um nadir mais alto em comparação com\ncrianças nascidas a termo. Essa condição também é chamada de ?anemia da prematuridade?.","B":"Possui um mecanismo semelhante àquele que provoca anemia em crianças nascidas a termo e\ncausa anemia em prematuros nas primeiras 4 a 12 semanas.","C":"A eritropoetina mais alta, a vida-média mais curta das hemácias (35 a 50 dias), o crescimento\nrápido e as flebotomias mais frequentes\ncontribuem para o menor nadir de Hb em prematuros.","D":"A anemia da prematuridade afeta mais comumente crianças < 36 semanas de gestação."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-315790","number":"315790","sourceNumber":"315790","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Sobre o tratamento da Retinopatia da Prematuridade (ROP), assinale a alternativa\ncorreta.","options":{"A":"A terapia antiangiogênica é uma opção nos casos de falha do tratamento com laser ou quando\nsabidamente os resultados tendem a ser ruins com o tratamento isolado com laserterapia.","B":"O paciente está definitivamente curado quando a doença regride após o tratamento com a\ninjeção de antiangiogênico.","C":"A injeção de antiangiogênico é a terapia de escolha.","D":"O uso de antiangiogênico em prematuros tem poucos efeitos deletérios."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-300823","number":"300823","sourceNumber":"300823","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"A palavra ?neonatologia? deriva de ?natos? que, em latim, significa ?nascer?, e\n\n?logos?, que quer dizer ?tratado? ou ?estudo?. Em resumo, é o ?conhecimento do recém-nascido\nhumano?. É uma das especialidades\npediátricas com atenção voltada ao Recém-Nascido (RN)\nsadio ou com problemas de saúde. Considerando o contexto do controle de temperatura de RNs, é\nCORRETO afirmar:","options":{"A":"Oferecer e manter ambiente com temperatura estável permite ao prematuro consumo mínimo de\nenergia e, consequentemente, menor consumo de oxigênio. A umidade do ar estável também\ncontribui para a manutenção da temperatura corpórea.","B":"A hipertermia pode ocorrer devido à perda de calor para o ambiente que está fora das condições\nideais, procedimentos demorados que expõem o RN ao\nfrio, quadros de hipóxia, choque,\nhipoglicemia, infecção grave, lesão cerebral, hipotireoidismo ou uso de benzodiazepínicos.","C":"A maior perda de calor de um RN ocorre nas primeiras 24 horas de vida. Sem medidas de\ncontrole térmico, o bebê pode perder de 2 a 4°C\nde sua temperatura corpórea. Por isso, nesse\nperíodo, deve-se evitar o transporte na incubadora de transporte de dupla parede, utilizando outros\nmétodos de controle de temperatura.","D":"No transporte de prematuros, a utilização do gorro é indiferente para prevenir perda de calor por\nmeio das fontanelas, que representam grande área de troca de calor no RN, devendo ser utilizado\nsaco plástico, que confere proteção adequada contra perda de calor corpóreo, além de possibilitar\na visualização completa do neonato, permitindo avaliação clínica apropriada."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-314122","number":"314122","sourceNumber":"314122","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido, cuja mãe tem tipagem sanguínea \"A\" Rh positivo, nasceu com 36\nsemanas de idade gestacional, por parto\nnormal e apresentou icterícia (zona III) com 30 horas de\nvida. Neste momento, qual é a conduta as ser tomada imediatamente, além de colocar o RN sob\nfototerapia?","options":{"A":"Manter sob observação clínica.","B":"Realizar exsanguineotransfusão.","C":"Administrar imunoglobulina endovenosa.","D":"Solicitar exames laboratoriais."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-302861","number":"302861","sourceNumber":"302861","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Qual a idade ideal para a realização da triagem neonatal para hipotireoidismo congênito\nem recém-nascidos a termo?","options":{"A":"Até 24 horas de vida.","B":"Do 3° ao 5o dia de vida.","C":"Após o 10° dia de vida.","D":"Após o 7o dia de vida.","E":"Do 1° ao 7o dia de vida."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-300827","number":"300827","sourceNumber":"300827","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Paciente, sexo feminino, 1 ano e 1 mês, com percentil 25 para peso, percentil 10 para\ncomprimento e percentil abaixo de 5 para perímetro cefálico. O nascimento ocorreu a termo, sendo\nrevelado na inspeção pequeno tamanho de crânio. Apresenta retardo de desenvolvimento e, ao\nnascimento, teve icterícia neonatal prolongada. Atualmente, apresenta crises de convulsões.\n\nConsiderando as descrições do enunciado, a melhor explicação para o pequeno tamanho da\ncriança é:","options":{"A":"Síndrome de Down.","B":"Hipotireoidismo congênito.","C":"Craniofaringioma.","D":"Infecção congênita por citomegalovírus."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313217","number":"313217","sourceNumber":"313217","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Um recém-nascido com 37 semanas de vida apresentou, ao nascimento, respiração\nadequada, choro forte, bom tônus em flexão o e líquido amniótico meconial. Com base nesse\ncálculo assinale a alternativa correta:","options":{"A":"o recém-nascido deverá ser aquecido, e sua vitalidade, avaliada enquanto se encontrar junto à\nmãe.","B":"o cordão umbilical deverá ser clampeado imediatamente após a extração completa do\nrecém-nascido da cavidade uterina","C":"o recém-nascido deverá ser examinado na mesa de reanimação da sala de parto antes de ser\ncolocado junto à mãe","D":"as vias aéreas superiores deverão ser aspiradas assim que o polo cefálico se desprender"},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-313218","number":"313218","sourceNumber":"313218","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Acerca do clampeamento tardio do cordão umbilical na sala de parto, assinale a\nalternativa correta:","options":{"A":"em recém-nascido que não tenha iniciado a respiração ao nascer, a necessidade de intubação\norotraqueal será menor","B":"em recém-nascido pré-termo, diminui a incidência de hemorragia intracraniana","C":"aumenta o risco de enterocolite necrosante","D":"é contraindicado a recém-nascido pré-termo com menos de 34 semanas de idade gestacional"},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-315805","number":"315805","sourceNumber":"315805","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido prematuro, de 26 semanas, pesando 900g, masculino, internado em\nleito de terapia intensiva neonatal desde o\nnascimento para suporte à vida. No momento encontra\nfórmula hidrolisada em sonda enteral associada à nutrição parenteral em cateter central de inserção\nperiférica. Hoje, com 15 dias de vida, apresentou letargia, alguns episódios de apneia, aumento do\nresíduo gástrico e distensão abdominal. Os exames séricos evidenciaram leucocitose e\nplaquetopenia com aumento de provas inflamatórias inespecíficas. Mantém-se hemodinamicamente\ncom abdome distendido, doloroso difusamente, mas sem sinais de irritação peritoneal. Ausência de\nflogoses e parede abdominal. Foram realizadas as radiografias abaixo. A principal hipótese\ndiagnóstica é:","options":{"A":"Íleo meconial.","B":"Volvo de sigmoide.","C":"Enterocolite necrosante.","D":"Invaginação intestinal."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-315806","number":"315806","sourceNumber":"315806","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém-nascido prematuro, de 26 semanas, pesando 900g, masculino, internado em\nleito de terapia intensiva neonatal desde o\nnascimento para suporte à vida. No momento encontra\nfórmula hidrolisada em sonda enteral associada à nutrição parenteral em cateter central de inserção\nperiférica. Hoje, com 15 dias de vida, apresentou letargia, alguns episódios de apneia, aumento do\nresíduo gástrico e distensão abdominal. Os exames séricos evidenciaram leucocitose e\nplaquetopenia com aumento de provas inflamatórias inespecíficas. Mantém-se hemodinamicamente\ncom abdome distendido, doloroso difusamente, mas sem sinais de irritação peritoneal. Ausência de\nflogoses e parede abdominal. Foram realizadas as radiografias abaixo. A melhor conduta no\nmomento é:","options":{"A":"Piloromiotomia.","B":"Antibioticoterapia sistêmica, dieta zero e suporte clínico.","C":"Colonoscopia descompressiva.","D":"Biopsias retais e abaixamento de cólon."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-308275","number":"308275","sourceNumber":"308275","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Ao longo século, a evolução das pesquisas em biologia molecular possibilitou muitas\naplicações a beira leito com considerável impacto clinico no tratamento em oncologia. Neste\ncontexto, conhecimento sobre a genética do câncer demonstrou que a base fisiopatológica tem\nforte associação com consecutivas alterações somáticas no DNA resultando em proliferações\ncelulares irrestritas. Este conceito hoje muito claro, foi uma das bases ou ponto de partida das\npesquisas que resultaram nos desfechos clínicos atuais. Entretanto, ainda há muito o que descobrir\ne avançar no tratamento do câncer. Considerando a temática da genética oncológica e sua\nimportância na prática clínica em oncologia, resposta as questões abaixo. Sobre a epigenética e os\nmecanismos de manifestação de doenças podemos afirmar que:","options":{"A":"Uma modificação epigenética se refere a uma mudança no genoma, herdada pela progênie\ncelular, que não envolve mudança na sequência de DNA.","B":"Uma modificação epigenética se refere a uma mudança no genoma, herdada pela progênie\ncelular, que envolve mudança na sequência de DNA.","C":"Uma modificação epigenética se refere a uma mudança no genoma, herdada pela progênie\ncelular, que geralmente envolve mudança na sequência de DNA.","D":"Uma modificação epigenética se refere a uma mudança no genoma, herdada pela progênie\ncelular, que geralmente não envolve mudança na sequência de DNA."},"answer":"A","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-316370","number":"316370","sourceNumber":"316370","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O recém-nascido deve passar por vários rastreios. Dentre eles, temos o teste do\npezinho e o teste do reflexo vermelho. Qual a data correta para realizar esses exames,\nrespectivamente:","options":{"A":"Após 7º dia de vida / a cada 3 meses até os 2 anos de idade.","B":"3º ao 5º dia de vida / 1 consulta, 4 meses, 6 meses, 12 meses e 2 anos.","C":"1º ao 10º dia de vida / a cada 3 meses até os 2 anos de idade.","D":"Ambos do 3º ao 5º dia de vida."},"answer":"B","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-308288","number":"308288","sourceNumber":"308288","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"O nosso país atualmente apresenta quedas nas taxas de transmissão vertical do HIV.\n\nEste fato é decorrente de medidas profiláticas, envolvendo cuidados com o binômio\n\nmãe-recém-nascido. Medidas como o aumento do número de diagnósticos realizados durante o\npré-natal, utilização da terapia antirretroviral e medidas profiláticas para o recém-nascido\ncontribuíram para esse cenário (Pascom et al.,2020). Gestante, portadora do vírus HIV há cerca de\n3 anos, não faz uso de terapia antirretroviral, deu entrada no Hospital e Maternidade Dona Íris, em\ntrabalho de parto. Recém nascido com peso ao nascimento de 3150 gramas, Capurro de 39\nsemanas e 2 dias. Qual (is) antirretroviral (is) este recém-nascido deverá receber?","options":{"A":"AZT (zidovudina) por 42 dias.","B":"AZT (zidovudina) por 28 dias e NVP (nevirapina) por 3 dias.","C":"AZT (zidovudina) , NVP (nevirapina) e 3TC (lamivudina) por 28 dias.","D":"AZT (zidovudina) , 3TC (lamivudina) e RAL (raltegravir) por 28 dias."},"answer":"D","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-1-308289","number":"308289","sourceNumber":"308289","collectionBlock":"medcurso:medcurso-pediatria-ped-1","collectionLabel":"Medcurso · PED 1","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 1","subtopic":"","stem":"Recém- nascido a termo de 39 semanas e 5 dias, parto normal, com 18 horas de vida,\nem bom estado geral, grupo sanguíneo A\npositivo, em aleitamento materno exclusivo, apresenta-se\nictérico até a região do tronco. Tipagem sanguínea materna: O positivo. Realizado bilirrubina\ntranscutânea deste recém-nascido, com valor de 9,5. A conduta mais adequada neste caso é:","options":{"A":"Solicitar hematócrito, hemoglobina, bilirrubinas, coombs direto e reticulócitos, iniciar\nfototerapia e\nsuspender aleitamento materno.","B":"Solicitar hematócrito, hemoglobina, bilirrubinas, coombs direto e reticulócitos, aguardar\nresultados de exames e iniciar complementação com fórmula.","C":"Solicitar hematócrito, hemoglobina, bilirrubinas, coombs direto e reticulócitos, iniciar\nfototerapia e\nmanter aleitamento materno.","D":"Iniciar imediatamente fototerapia e suspender aleitamento materno."},"answer":"C","source":"Pediatria/PED 1/PED 1.txt","sourceLabel":"Medcurso · PED 1","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
